window.SDT_LESSONS=window.SDT_LESSONS||{};window.SDT_LESSONS["U2"]={"deck":"U2","slides":[{"p":1,"title":"2강 표지: 아르누보, 유겐트슈틸, 아르데코","terms":["Art Nouveau","Jugendstil","아르데코"],"pass1":[{"kind":"say","lines":["2강 표지예요. 연둣빛 띠에 '02 아르누보 유겐트슈틸 아르데코' 한 줄만 있어요.","1강에서 기계를 싫어한 사람들을 봤다면, 이제는 새 장식을 만드는 사람들이에요.","주문을 다시 외워요. 기계 시대에 건축은 어떻게 생겨야 하나? 싫어 → 새 장식 → 정리 → 없애."]},{"kind":"goal","items":["**아르 누보(Art Nouveau)** 가 무엇이고 언제인지 말할 수 있어요.","**유겐트슈틸(Jugendstil)** 이 **아르 누보(Art Nouveau)** 와 어떻게 다른지 알 수 있어요.","**아르데코** 와 시카고 학파까지 이 강의 한 덩어리로 묶어서 볼 수 있어요."]}],"pass2":[{"kind":"points","head":"2강이 다루는 세 가지 이름","items":["**아르 누보(Art Nouveau)**: 자연의 곡선으로 만든 새 양식(1890-1910)이에요.","**유겐트슈틸(Jugendstil)**: 그 곡선을 독일에서 기하학으로 정리한 양식이에요.","**아르데코**: 곡선 대신 번개와 지그재그를 쓰는, 더 늦은 기하 장식 양식이에요.","표지에 적힌 순서가 곧 시간 순서이자 곡선이 직선으로 변해 가는 순서예요."]}],"pass3":[]},{"p":2,"title":"절충주의와 낭만주의적 리바이벌","terms":["절충주의","역사주의","Art Nouveau"],"pass1":[{"kind":"say","lines":["글 세 줄과 사진 두 장이에요. 왼쪽은 그리스 신전 같은 돌 문, 오른쪽은 뾰족탑 성이에요.","아르 누보가 나오기 직전, 19세기 후반 유럽이 어떤 상태였는지 보여 주는 쪽이에요.","한마디로 옛날 양식 견본집에서 마음에 드는 것을 골라 겉에 붙이던 시대예요."]},{"kind":"analogy","head":"옛 양식 뷔페","scene":"뷔페에 가서 파스타, 초밥, 떡볶이를 한 접시에 담은 모습이에요.","map":[["접시","건물 한 채"],["파스타, 초밥, 떡볶이","고딕, 르네상스, 고전 기둥"],["맛이 따로 노는 접시","용도와 상관없이 겉만 꾸민 **절충주의** 건물"]]}],"pass2":[{"kind":"points","head":"**절충주의** 가 무엇인가요","items":["과거를 모방하면서 건물의 목적과 상관없이 잡다한 양식으로 외관을 치장했어요.","외벽은 역사적 양식을 모아 놓은 견본들에서 임의로 골라서 장식했어요.","이것을 나쁘게 보는 쪽에서는 **절충주의** 및 **역사주의** 라고 불러요.","**역사주의** 는 영어로 Historism 이라고 슬라이드에 적혀 있어요."]},{"kind":"look","walked":1},{"kind":"compare","head":"두 사진이 말해 주는 것","cols":["왼쪽 사진","오른쪽 사진"],"rows":[["고전 신전에서 빌려 온 기둥과 박공","중세 성에서 빌려 온 뾰족탑과 성벽"],["돌을 쌓아 무겁고 수평으로 퍼짐","탑이 솟아 낭만적이고 수직으로 솟음"],["둘 다 19세기의 새 건물인데 겉모습만 옛 양식이에요","그래서 **절충주의** 라고 불러요"]]}],"pass3":[{"kind":"check","q":"건물 용도와 상관없이 여러 역사 양식을 골라 겉을 꾸민 경향을 뭐라고 하나요?","choices":["**절충주의**","**아르 누보(Art Nouveau)**","**미술공예운동(Arts and Crafts Movement)**"],"a":0,"why":"부정적으로 평가하는 쪽에서는 **역사주의**(Historism)라고도 불러요."},{"kind":"english","head":"논술 답안: 절충주의","en":"절충주의는 과거를 모방하면서 건물의 목적과는 상관없이 잡다한 양식으로 외관을 치장한 경향이며, 외벽은 역사적 양식 견본에서 임의로 골라 장식되었다.","ko":"정의, 겉치장, 견본에서 임의 선택 세 가지를 한 문장에 넣어요.","tip":"부정적으로 볼 때의 이름이 역사주의(Historism)라는 점을 꼭 덧붙여요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.05,0.44,0.06],"c":[0.018,0.025,0.484,0.11],"r":5.8667,"img":"img/U2/walk/p002_21_01.jpg","say":"제목이에요. 절충주의와 낭만주의적 리바이벌."},{"b":[0.05,0.16,0.9,0.11],"c":[0.005,0.115,0.99,0.2],"r":6.6,"img":"img/U2/walk/p002_21_02.jpg","say":"첫 항목이에요. 목적과 상관없이 잡다한 양식으로 외관을 치장했어요."},{"b":[0.05,0.27,0.9,0.07],"c":[0.005,0.205,0.99,0.2],"r":6.6,"img":"img/U2/walk/p002_21_03.jpg","say":"둘째 항목이에요. 외벽은 역사적 양식 견본들에서 임의로 골라 장식되었어요."},{"b":[0.05,0.34,0.9,0.12],"c":[0.005,0.3,0.99,0.2],"r":6.6,"img":"img/U2/walk/p002_21_04.jpg","say":"셋째 항목이에요. 부정적으로 보면 **절충주의** 및 **역사주의**(Historism)라고 해요."},{"b":[0.03,0.47,0.48,0.42],"c":[0.006,0.449,0.528,0.462],"r":1.5238,"img":"img/U2/walk/p002_21_05.jpg","say":"왼쪽 사진이에요. 도리아식 기둥과 삼각 박공을 그대로 옮겨 온 고전풍 문이에요."},{"b":[0.53,0.47,0.44,0.42],"c":[0.508,0.449,0.484,0.462],"r":1.3968,"img":"img/U2/walk/p002_21_06.jpg","say":"오른쪽 사진이에요. 뾰족탑이 여러 개 달린 중세 성 모양이에요. 두 건물이 같은 시대예요."}]}},{"p":3,"title":"절충주의 주택 양식","terms":["절충주의","역사주의"],"pass1":[{"kind":"say","lines":["목록 다섯 줄과 아래쪽 판화 한 장이에요. 집들이 한 줄로 늘어서 있어요.","**절충주의** 가 집에 적용되면 어떤 모습인지 항목으로 정리한 쪽이에요.","가짜 돌 장식, 뻔한 지붕창, 비례를 무시한 넓은 창이 핵심이에요."]}],"pass2":[{"kind":"points","head":"**절충주의** 주택 양식의 특징","items":["혼합된 양식의 절충식 고딕, 급경사 지붕, 다갈색 벽돌을 써요.","상투적인 수법의 지붕창(dormer)과 박공(gable)을 써요. 지붕에 낸 창이 dormer 예요.","회반죽한 석재나 인공석재로 장식해요. 진짜 돌이 아니라 돌처럼 보이게 만든 것이에요.","값싼 유리가 보급되어 넓은 창문을 달았고, 전통적인 비례 체계는 무시했어요.","19세기 후반은 고전, 이탈리아와 프랑스 르네상스, 회화풍(picturesque) 토착 건축이 뒤섞인 혼란기예요."]},{"kind":"look","walked":1},{"kind":"bg","src":"기초 다지기: 건축 용어","lines":["박공(gable)은 지붕 두 면이 맞닿아 생기는 삼각형 벽면이에요.","지붕창(dormer)은 경사 지붕을 뚫고 튀어나온 작은 창이에요.","두 낱말은 이 과목에서 계속 나오니 그림으로 외워 두면 편해요."]}],"pass3":[{"kind":"check","q":"**절충주의** 주택에서 넓은 창문을 달 수 있게 된 이유는 무엇인가요?","choices":["값싼 유리가 보급되어서","철골이 발명되어서","엘리베이터가 나와서"],"a":0,"why":"값싼 유리 보급으로 넓은 창을 달았고, 그 대신 전통적인 비례 체계는 무시되었어요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**절충주의** 와 **역사주의** 는 같은 현상을 부르는 두 이름이에요. 둘을 다른 양식으로 외우면 안 돼요.","다갈색 벽돌은 **절충주의** 주택의 특징이에요. 1강의 붉은 벽돌 주택과 헷갈리지 않게 조심해요."]}],"walk":{"head":null,"parts":[{"b":[0.04,0.04,0.35,0.06],"c":[0.0225,0.015,0.385,0.11],"r":4.6667,"img":"img/U2/walk/p003_21_01.jpg","say":"제목 줄이에요. 절충주의 주택 양식."},{"b":[0.07,0.11,0.7,0.28],"c":[0.035,0.094,0.77,0.312],"r":3.2906,"img":"img/U2/walk/p003_21_02.jpg","say":"특징 다섯 줄이에요. 고딕, 급경사 지붕, dormer, 박공, 인공석재, 넓은 창."},{"b":[0.07,0.46,0.88,0.12],"c":[0.026,0.4222,0.968,0.1956],"r":6.5985,"img":"img/U2/walk/p003_21_03.jpg","say":"화살표 문장이에요. 여러 건축양식이 혼재한 19세기 후반의 혼란기예요."},{"b":[0.22,0.58,0.63,0.4],"c":[0.1885,0.56,0.693,0.44],"r":2.1,"img":"img/U2/walk/p003_21_04.jpg","say":"아래 판화예요. 한 줄로 이어진 집들인데 지붕 모양과 창 모양이 집마다 다 달라요."}]}},{"p":4,"title":"모더니즘과 건축가들: 인간환경의 재창조","terms":["Art Nouveau","Wiener Secession","아르데코"],"pass1":[{"kind":"say","lines":["글자만 있는 목록 쪽이에요. 앞으로 배울 사조 이름이 쭉 적혀 있어요.","20세기 자본주의가 커지면서 예술 성향과 건축 양식이 우르르 쏟아진다는 이야기예요.","지금은 다 외울 필요 없어요. 2강의 **아르 누보(Art Nouveau)** 가 이 목록의 두 번째라는 것만 봐요."]},{"kind":"recap","items":["1강: 기계가 싫다고 손으로 만들자던 시기예요.","2강: 그래도 새 양식은 필요하니 자연 곡선으로 새 장식을 만들어요.","뒤 강의: 곡선을 정리하고, 끝내 장식을 없애요."]}],"pass2":[{"kind":"points","head":"슬라이드에 적힌 흐름 목록","items":["빅토리아 시대의 박애주의(Philanthropism) 운동.","**아르 누보(Art Nouveau)**: 곡선은 계속된다.","비엔나 제체시온(**빈 분리파(Wiener Secession)**)과 표현주의: 개성에 대한 예찬.","독일공작연맹, 이탈리아 미래파, 러시아 구조주의, 독일 합리주의.","데 스테일, 르 코르뷔지에, 파시즘 건축, 미스 반 데어 로에, 바우하우스와 국제주의 양식."]},{"kind":"look","walked":1},{"kind":"bg","src":"기초 다지기: 이 목록의 쓰임","lines":["이 쪽은 한 학기 전체의 차례표예요. 2강은 **아르 누보(Art Nouveau)** 와 **아르데코** 를 맡아요.","3강은 **빈 분리파(Wiener Secession)**, 4강은 바우하우스와 데 스테일로 이어져요."]}],"pass3":[{"kind":"check","q":"슬라이드가 **아르 누보(Art Nouveau)** 에 붙인 설명 문구는 무엇인가요?","choices":["곡선은 계속된다","산업의 힘, 제거의 예술","개성에 대한 예찬"],"a":0,"why":"산업의 힘과 제거의 예술은 바우하우스와 국제주의 양식, 개성에 대한 예찬은 제체시온과 표현주의예요."}],"walk":{"head":null,"parts":[{"b":[0.03,0.03,0.55,0.07],"c":[0.0025,0.0039,0.605,0.1222],"r":6.6012,"img":"img/U2/walk/p004_21_01.jpg","say":"제목이에요. 모더니즘과 건축가들, 인간환경의 재창조."},{"b":[0.06,0.14,0.85,0.11],"c":[0.0175,0.1005,0.935,0.1889],"r":6.5996,"img":"img/U2/walk/p004_21_02.jpg","say":"모던 시대의 도래. 20세기 자본주의 확장과 함께 여러 조류가 등장해요."},{"b":[0.06,0.29,0.85,0.35],"c":[0.0175,0.2725,0.935,0.385],"r":3.2381,"img":"img/U2/walk/p004_21_03.jpg","say":"앞쪽 목록이에요. 박애주의부터 독일 합리주의까지 일곱 줄이에요."},{"b":[0.06,0.66,0.9,0.28],"c":[0.01,0.644,0.99,0.312],"r":4.2308,"img":"img/U2/walk/p004_21_04.jpg","say":"뒤쪽 목록이에요. 데 스테일부터 바우하우스와 국제주의 양식까지예요."}]}},{"p":5,"title":"아르 누보(Art Nouveau), 1890-1910","terms":["Art Nouveau","Arts and Crafts Movement","역사주의"],"pass1":[{"kind":"say","lines":["제목에 연도가 들어간 글 슬라이드예요. 아래에 큰따옴표 문장이 하나 있어요.","**아르 누보(Art Nouveau)** 가 언제, 어디서, 왜 시작됐는지 말해 주는 쪽이에요.","핵심 한 줄은 '예술에는 일정한 형식이 없다' 예요."]},{"kind":"analogy","head":"교복을 벗은 학교","scene":"정해진 교복만 입던 학교에서 갑자기 사복을 허락한 날이에요.","map":[["교복 규정","고전 양식의 규칙과 **역사주의**"],["사복 허용","예술에는 일정한 형식이 없다는 선언"],["각자 다른 옷차림","예술가 개인의 개성이 드러난 **아르 누보(Art Nouveau)**"]]}],"pass2":[{"kind":"points","head":"**아르 누보(Art Nouveau)** 의 기본 사실","items":["1890-1910 에 성행했고, 최고조를 이룬 시기는 1890-1905 예요.","19세기 말 벨기에의 화랑 이름에서 시작했고, 당시로서는 전위적이었어요.","1893년부터 벨기에 브뤼셀에서 매년 전시회를 열어 영국의 **미술공예운동(Arts and Crafts Movement)** 을 소개했어요.","형식이 아닌 삶의 필요에 의해 기술이 동원되고 그 결과가 미를 강조할 때 양식이 가치를 갖는다고 봤어요.","전통적인 예술관을 거부했고, 진부한 예술관에서 벗어나 모든 분야에서 통일된 양식을 추구했어요."]},{"kind":"look","walked":1},{"kind":"bg","src":"기초 다지기: 1강과 이어 보기","lines":["**미술공예운동(Arts and Crafts Movement)** 은 기계가 싫어서 손으로 만들자고 했어요.","**아르 누보(Art Nouveau)** 는 그 정신을 이어받았지만 기계와 철, 유리는 거부하지 않았어요.","그래서 주문이 싫어에서 새 장식으로 넘어가는 자리가 바로 이 쪽이에요."]}],"pass3":[{"kind":"check","q":"**아르 누보(Art Nouveau)** 가 최고조를 이룬 시기는 언제인가요?","choices":["1860-1900","1890-1905","1920-1930"],"a":1,"why":"전체 기간은 1890-1910, 최고조는 1890-1905 예요. 두 숫자를 따로 외워요."},{"kind":"check","q":"1893년부터 매년 전시회를 열어 영국 **미술공예운동(Arts and Crafts Movement)** 을 소개한 도시는 어디인가요?","choices":["파리","브뤼셀","빈"],"a":1,"why":"벨기에 브뤼셀이에요. **아르 누보(Art Nouveau)** 라는 이름도 벨기에 화랑 이름에서 왔어요."},{"kind":"english","head":"논술 답안: 아르 누보의 성립","en":"아르 누보는 1890년에서 1910년 사이에 성행한 유럽의 예술 사조로 최고조는 1890년에서 1905년이며, 19세기 말 벨기에의 화랑 이름에서 시작되어 1893년부터 브뤼셀 전시회를 통해 영국 미술공예운동을 소개하였다.","ko":"연도, 출발지, 브뤼셀 전시회 세 가지를 한 문장에 넣어요.","tip":"벨기에 화랑, 브뤼셀 전시회, 1893 을 하나로 묶어 외워요."}],"walk":{"head":null,"parts":[{"b":[0.06,0.06,0.52,0.06],"c":[0.034,0.0322,0.572,0.1156],"r":6.5975,"img":"img/U2/walk/p005_21_01.jpg","say":"제목이에요. 아르 누보(Art Nouveau) (1890-1910). 연도가 시험에 그대로 나와요."},{"b":[0.05,0.15,0.9,0.13],"c":[0.005,0.115,0.99,0.2],"r":6.6,"img":"img/U2/walk/p005_21_02.jpg","say":"첫 항목이에요. 형식이 아니라 삶의 필요에서 나온 기술이 미를 만들 때 양식이 된다는 뜻이에요."},{"b":[0.05,0.27,0.9,0.12],"c":[0.005,0.23,0.99,0.2],"r":6.6,"img":"img/U2/walk/p005_21_03.jpg","say":"벨기에 화랑 이름에서 시작, 1893년부터 브뤼셀에서 매년 전시회를 열었어요."},{"b":[0.05,0.39,0.9,0.17],"c":[0.005,0.374,0.99,0.202],"r":6.5347,"img":"img/U2/walk/p005_21_04.jpg","say":"그다음 두 항목이에요. 새로운 예술 운동인 아르 누보가 통일된 양식을 추구하고 전통 예술관을 거부해요."},{"b":[0.09,0.61,0.36,0.06],"c":[0.072,0.585,0.396,0.11],"r":4.8,"img":"img/U2/walk/p005_21_05.jpg","say":"굵은 따옴표 문장이에요. 예술에는 일정한 형식이 없다."},{"b":[0.27,0.69,0.7,0.11],"c":[0.23,0.6672,0.77,0.1556],"r":6.5981,"img":"img/U2/walk/p005_21_06.jpg","say":"오른쪽 아래 두 줄이에요. 최고조는 1890-1905 라고 다시 못 박아요."}]}},{"p":6,"title":"아르 누보의 뜻, 성격, 재료","terms":["Art Nouveau","wrought iron","역사주의"],"pass1":[{"kind":"say","lines":["글만 있는 쪽이에요. 항목 여섯 줄과 아래 재료 목록 세 줄이에요.","**아르 누보(Art Nouveau)** 는 프랑스어로 '새로운 미술' 이라는 뜻이에요.","여기서 제일 중요한 한 줄은 '공간보다는 표면과 장식 위주' 예요."]}],"pass2":[{"kind":"points","head":"**아르 누보(Art Nouveau)** 의 성격","items":["프랑스어로 새로운 미술이라는 뜻이에요.","고전 체계를 대체한 최초의 양식이에요. 과거 전통 양식을 배제하고 새 형태를 만들려 했어요.","새로운 산업의 주체인 부르주아의 탄생과 함께 등장했고 산업자본주의를 타고 유럽 전역으로 퍼졌어요.","산업생산과 장식예술의 결합이라는 목표 아래 산업생산물의 디자인을 아름답게 만들려 했어요.","예술가 개인의 주관성과 창의력을 중시했고, 공간보다는 표면과 장식 위주였어요."]},{"kind":"points","head":"재료와 디테일","items":["컬러풀한 이국적 형태의 합판을 썼어요.","형틀로 만들어진 석재를 썼어요. 돌을 깎지 않고 틀에 부어 같은 모양을 여러 개 만들어요.","**단철(wrought iron)** 로 된 창살과 발코니를 썼어요. 두드려 늘일 수 있어 곡선을 뽑기 좋아요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**아르 누보(Art Nouveau)** 의 관심이 더 향한 쪽은 어디인가요?","choices":["공간보다 표면과 장식","표면보다 공간 구성","구조보다 설비"],"a":0,"why":"공간보다는 표면과 장식 위주였어요. 공간을 다루는 일은 3강의 로스부터 본격화돼요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**아르 누보(Art Nouveau)** 는 과거 양식을 배제했어요. 옛 양식을 골라 쓰던 **역사주의** 와 반대예요.","'고전 체계를 대체한 최초의 양식' 이라는 표현을 그대로 외워 두면 객관식에서 바로 골라요."]}],"walk":{"head":null,"parts":[{"b":[0.05,0.08,0.45,0.05],"c":[0.0275,0.05,0.495,0.11],"r":6.0,"img":"img/U2/walk/p006_22_01.jpg","say":"첫 줄이에요. 아르 누보는 프랑스어로 새로운 미술."},{"b":[0.05,0.14,0.92,0.11],"c":[0,0.0928,1,0.2045],"r":6.52,"img":"img/U2/walk/p006_22_02.jpg","say":"고전 체계를 대체한 최초의 양식이라는 문장이에요. 시험에 자주 나와요."},{"b":[0.05,0.26,0.92,0.11],"c":[0,0.2128,1,0.2045],"r":6.52,"img":"img/U2/walk/p006_22_03.jpg","say":"부르주아의 탄생, 산업자본주의를 타고 유럽 전역으로 확산."},{"b":[0.05,0.37,0.92,0.13],"c":[0,0.3328,1,0.2045],"r":6.52,"img":"img/U2/walk/p006_22_04.jpg","say":"산업생산과 장식예술의 결합이라는 목표 줄이에요."},{"b":[0.05,0.5,0.5,0.11],"c":[0.025,0.484,0.55,0.142],"r":5.1643,"img":"img/U2/walk/p006_22_05.jpg","say":"개인의 주관성 중시, 그리고 공간보다는 표면과 장식 위주."},{"b":[0.07,0.65,0.45,0.25],"c":[0.0475,0.634,0.495,0.282],"r":2.3404,"img":"img/U2/walk/p006_22_06.jpg","say":"재료와 디테일 세 줄이에요. 합판, 형틀 석재, **단철(wrought iron)** 창살과 발코니."}]}},{"p":7,"title":"아르 누보의 형태 특징과 지역별 이름","terms":["Art Nouveau","Jugendstil","Wiener Secession","구스타프 클림트","알폰스 무하","wrought iron"],"pass1":[{"kind":"say","lines":["그림 두 장과 항목 다섯 줄이에요. 왼쪽은 금빛 초상화, 오른쪽은 꽃에 둘러싸인 여인이에요.","**아르 누보(Art Nouveau)** 의 모양 특징과 나라별 이름을 한 번에 정리한 쪽이에요.","왼쪽이 **구스타프 클림트**, 오른쪽이 **알폰스 무하** 의 그림이라고 슬라이드가 알려 줘요."]},{"kind":"analogy","head":"덩굴이 자란 그림","scene":"담장을 타고 올라간 나팔꽃 덩굴을 그대로 벽에 옮긴 모습이에요.","map":[["덩굴 줄기","끊기지 않고 이어지는 완만한 곡선"],["한쪽으로 치우친 잎","비대칭에 의한 아름다움"],["꽃과 잎","백합, 소용돌이, 리본 같은 장식 모티프"]]}],"pass2":[{"kind":"points","head":"형태 특징","items":["자연물, 특히 꽃이나 식물 덩굴에서 따온 장식적인 곡선이 특징이에요.","비대칭에 의한 아름다움을 추구했어요. 좌우가 똑같이 생기지 않아요.","직선과 각진 형태는 배제하고 완만한 곡선으로 식물, 잎, 추상적 동물, 백합, 소용돌이, 리본을 표현해요.","새로운 재료인 철과 유리를 많이 썼고, **단철(wrought iron)** 창살과 발코니가 그 예예요."]},{"kind":"compare","head":"나라마다 다른 이름","cols":["나라","부르는 이름"],"rows":[["프랑스, 벨기에","**아르 누보(Art Nouveau)**"],["독일","**유겐트슈틸(Jugendstil)**"],["오스트리아","제체시온, 곧 **빈 분리파(Wiener Secession)**"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**아르 누보(Art Nouveau)** 를 오스트리아에서 부른 이름은 무엇인가요?","choices":["**유겐트슈틸(Jugendstil)**","제체시온","아르데코"],"a":1,"why":"독일은 **유겐트슈틸(Jugendstil)**, 오스트리아는 제체시온 곧 **빈 분리파(Wiener Secession)** 예요."},{"kind":"check","q":"슬라이드가 든 **아르 누보(Art Nouveau)** 회화의 대표 화가 두 사람은 누구인가요?","choices":["모네와 르누아르","**구스타프 클림트** 와 **알폰스 무하**","피카소와 브라크"],"a":1,"why":"**구스타프 클림트** 는 금빛 장식, **알폰스 무하** 는 꽃과 덩굴 포스터로 기억해요."},{"kind":"english","head":"논술 답안: 아르 누보의 형태 특징","en":"아르 누보는 자연물 특히 꽃과 식물 덩굴에서 따온 장식적 곡선과 비대칭의 아름다움을 추구하였고, 직선과 각진 형태를 배제하였으며 새로운 재료인 철과 유리를 적극 사용하였다.","ko":"곡선, 비대칭, 직선 배제, 철과 유리 네 가지를 넣어요.","tip":"꽃 곡선, 비대칭, 철과 유리 세 낱말만 붙잡으면 문장이 만들어져요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.06,0.45,0.05],"c":[0.0275,0.03,0.495,0.11],"r":6.0,"img":"img/U2/walk/p007_22_01.jpg","say":"맨 위 줄이에요. 회화는 **구스타프 클림트**, **알폰스 무하** 등."},{"b":[0.03,0.13,0.37,0.52],"c":[0.0115,0.104,0.407,0.572],"r":0.9487,"img":"img/U2/walk/p007_22_02.jpg","say":"왼쪽 **구스타프 클림트** 그림이에요. 금빛 바탕에 네모와 눈 모양 무늬가 촘촘해요."},{"b":[0.43,0.13,0.52,0.52],"c":[0.404,0.104,0.572,0.572],"r":1.3333,"img":"img/U2/walk/p007_22_03.jpg","say":"오른쪽 **알폰스 무하** 그림이에요. 여인을 덩굴과 꽃이 감싸고 배경이 검어요."},{"b":[0.06,0.68,0.85,0.12],"c":[0.0175,0.6455,0.935,0.1889],"r":6.5996,"img":"img/U2/walk/p007_22_04.jpg","say":"곡선과 비대칭을 말하는 두 줄이에요."},{"b":[0.06,0.8,0.88,0.18],"c":[0.016,0.784,0.968,0.212],"r":6.0881,"img":"img/U2/walk/p007_22_05.jpg","say":"아래 세 줄이에요. 지역적 특성에 따라 여러 이름으로 알려졌고, 독일은 **유겐트슈틸(Jugendstil)**, 오스트리아는 제체시온이에요."}]}},{"p":8,"title":"오토 바그너, 호프 파빌리온, 빈, 1898","terms":["Art Nouveau","Otto Wagner","호프 파빌리온","wrought iron","Wiener Secession"],"pass1":[{"kind":"say","lines":["사진 네 장이 있는 쪽이에요. 건물 외관, 창 아래 금속 패널, 바닥 카펫, 녹색 문이에요.","캡션은 '오토 바그너, 호프 파빌리온, 오스트리아 빈, 1898' 이에요.","곡선과 철, 유리를 쓴 **아르 누보(Art Nouveau)** 가 실제 건물에서 어떻게 보이는지 보여 줘요."]},{"kind":"analogy","head":"한 벌로 맞춘 옷","scene":"겉옷부터 단추, 양말까지 같은 무늬로 맞춰 입은 모습이에요.","map":[["겉옷","**호프 파빌리온** 의 외관"],["단추와 양말","창 아래 패널, 바닥 카펫, 문 유리"],["같은 무늬","어디를 봐도 반복되는 식물 곡선"]]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["설계자는 **오토 바그너(Otto Wagner)**, 건물은 **호프 파빌리온**, 오스트리아 빈, 1898 이에요.","직선과 각진 형태를 배제하고 완만한 곡선으로 식물, 잎, 소용돌이, 리본을 표현한 예예요.","새로운 재료로 등장한 철과 유리를 많이 썼어요. **단철(wrought iron)** 창살도 같은 이야기예요.","**오토 바그너(Otto Wagner)** 는 3강의 **빈 분리파(Wiener Secession)** 에서 다시 만나요. 여기서는 이름과 연도만 챙겨요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**호프 파빌리온**(1898)을 설계한 사람은 누구인가요?","choices":["**빅토르 오르타(Victor Horta)**","**오토 바그너(Otto Wagner)**","**엑토르 기마르(Hector Guimard)**"],"a":1,"why":"오스트리아 빈, 1898 이에요. **오토 바그너(Otto Wagner)** 는 3강에서 자세히 다뤄요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.04,0.92,0.19],"c":[0,0.024,1,0.222],"r":6.006,"img":"img/U2/walk/p008_21_01.jpg","say":"위 항목 두 개예요. 완만한 곡선 모티프, 그리고 새 재료인 철과 유리를 많이 쓴다는 줄이에요."},{"b":[0.04,0.27,0.34,0.39],"c":[0.023,0.2505,0.374,0.429],"r":1.1624,"img":"img/U2/walk/p008_21_02.jpg","say":"**호프 파빌리온** 외관이에요. 둥근 지붕과 벽에서 흘러내리는 곡선 난간을 보세요."},{"b":[0.05,0.68,0.38,0.05],"c":[0.031,0.65,0.418,0.11],"r":5.0667,"img":"img/U2/walk/p008_21_03.jpg","say":"캡션 줄이에요. **오토 바그너(Otto Wagner)**, **호프 파빌리온**, 오스트리아 빈, 1898."},{"b":[0.61,0.2,0.37,0.36],"c":[0.5915,0.182,0.407,0.396],"r":1.3704,"img":"img/U2/walk/p008_21_04.jpg","say":"창 아래 금속 패널이에요. 좌우로 펼쳐진 잎 무늬가 판에 찍혀 있어요."},{"b":[0.38,0.59,0.38,0.4],"c":[0.361,0.56,0.418,0.44],"r":1.2667,"img":"img/U2/walk/p008_21_05.jpg","say":"바닥이에요. 큰 꽃과 덩굴이 원을 그리며 깔려 있어요."},{"b":[0.77,0.59,0.21,0.4],"c":[0.758,0.56,0.234,0.44],"r":0.7091,"img":"img/U2/walk/p008_21_06.jpg","say":"녹색 문이에요. 유리 안에 가는 금속 선으로 무늬를 넣었어요."}]}},{"p":9,"title":"벨기에의 아르 누보, 빅토르 오르타","terms":["Art Nouveau","Victor Horta","오르타 저택","타셀 저택"],"pass1":[{"kind":"say","lines":["위에 항목 세 줄, 아래 왼쪽에 실내 사진 한 장, 오른쪽에 목록이 있어요.","사진은 **오르타 저택**, 벨기에 브뤼셀, 1911 이에요. 지금은 오르타 박물관이에요.","**빅토르 오르타(Victor Horta)** 는 벨기에 **아르 누보(Art Nouveau)** 의 대표 건축가예요."]},{"kind":"analogy","head":"집 전체가 한 작품","scene":"집주인이 벽지부터 숟가락까지 직접 고른 집이에요.","map":[["직접 고른 벽지","곡선 타일을 붙인 벽과 천장"],["맞춤 가구","붙박이 캐비닛과 나무 공예품"],["직접 만든 조명","매다는 전기 조명 기구"]]}],"pass2":[{"kind":"points","head":"**빅토르 오르타(Victor Horta)**, 1861-1947","items":["벽과 천장에 직접 그리거나 스텐실 처리한 컬러 패턴으로 흐르는 곡선을 발전시켰어요.","가는 금속 기둥을 실내 디테일을 위한 정당한 재료로 받아들였어요.","매다는 조명 기구로 그 당시에는 새로웠던 전기 조명의 가능성을 개척했어요.","**오르타 저택**(1911)에는 타일 벽과 천장, 붙박이 캐비닛, 스테인드글라스 나무 공예품, 조명과 가구를 전부 직접 디자인했어요."]},{"kind":"look","walked":1},{"kind":"bg","src":"기초 다지기: 스텐실이 뭔가요","lines":["스텐실은 무늬를 오려 낸 판을 벽에 대고 물감을 칠해 같은 무늬를 반복하는 방법이에요.","손으로 하나하나 그리는 것보다 빠르고, 긴 곡선 띠를 벽에 두르기 좋아요."]}],"pass3":[{"kind":"check","q":"**오르타 저택** 의 연도는 언제인가요?","choices":["1893","1898","1911"],"a":2,"why":"1911년이에요. 1893년은 **타셀 저택** 이에요. 남의 집이 먼저, 내 집이 나중이라고 외워요."},{"kind":"english","head":"논술 답안: 빅토르 오르타","en":"빅토르 오르타는 벨기에 아르 누보의 대표 건축가로 벽과 천장의 컬러 패턴으로 흐르는 곡선을 발전시키고 가는 금속 기둥을 실내 재료로 수용하였으며 매다는 전기 조명의 가능성을 개척하였다.","ko":"곡선 패턴, 가는 금속 기둥, 전기 조명 세 가지가 채점 항목이에요.","tip":"곡선, 금속 기둥, 전등 세 낱말만 기억하면 문장이 이어져요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.04,0.3,0.06],"c":[0.025,0.015,0.33,0.11],"r":4.0,"img":"img/U2/walk/p009_21_01.jpg","say":"제목이에요. 벨기에의 아르 누보."},{"b":[0.05,0.13,0.92,0.17],"c":[0,0.1128,1,0.2045],"r":6.52,"img":"img/U2/walk/p009_21_02.jpg","say":"항목 세 줄이에요. 흐르는 곡선, 가는 금속 기둥, 매다는 전기 조명."},{"b":[0.03,0.38,0.46,0.06],"c":[0.007,0.355,0.506,0.11],"r":6.1333,"img":"img/U2/walk/p009_21_03.jpg","say":"인물 표시예요. **빅토르 오르타(Victor Horta)**, 1861~1947."},{"b":[0.03,0.45,0.46,0.49],"c":[0.007,0.4255,0.506,0.539],"r":1.2517,"img":"img/U2/walk/p009_21_04.jpg","say":"**오르타 저택** 실내 사진이에요. 아치 천장과 양옆 스테인드글라스 문을 보세요."},{"b":[0.49,0.49,0.48,0.42],"c":[0.466,0.469,0.528,0.462],"r":1.5238,"img":"img/U2/walk/p009_21_05.jpg","say":"직접 디자인한 요소 목록이에요. 타일 벽, 캐비닛, 나무 공예품, 조명과 가구."},{"b":[0.04,0.945,0.4,0.045],"c":[0.02,0.89,0.44,0.11],"r":5.3333,"img":"img/U2/walk/p009_21_06.jpg","say":"캡션이에요. **오르타 저택**, 벨기에 브뤼셀, 1911."}]}},{"p":10,"title":"오르타 저택 실내, 브뤼셀, 1911","terms":["Victor Horta","오르타 저택","Art Nouveau"],"pass1":[{"kind":"say","lines":["사진 두 장뿐인 쪽이에요. 왼쪽은 식당, 오른쪽은 타일을 붙인 아치 공간이에요.","캡션은 '빅토르 오르타, 오르타 저택, 벨기에 브뤼셀, 1911' 이에요.","글이 없으니 사진에서 곡선이 어디에 들어갔는지를 찾는 쪽이에요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["왼쪽은 식당이에요. 천장에서 나무 곡선이 뻗어 나와 조명 기구로 이어져요.","식탁과 의자, 유리 캐비닛까지 같은 곡선 어휘로 맞춰 놓았어요. 가구도 **빅토르 오르타(Victor Horta)** 가 디자인했어요.","오른쪽은 타일을 붙인 아치 공간이에요. 벽과 천장을 작은 타일이 덮고 있어요.","양옆 문에 좁고 긴 스테인드글라스가 들어가 빛이 색으로 들어와요.","**오르타 저택** 은 1911년 브뤼셀에 지은 자택이고 지금은 오르타 박물관이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**오르타 저택** 에서 가구와 조명, 벽 타일을 디자인한 사람은 누구인가요?","choices":["집주인이 따로 고용한 공예가","**빅토르 오르타(Victor Horta)** 자신","제조 회사의 기성품"],"a":1,"why":"자기 집에 전부 직접 디자인한 요소를 도입했어요. 이런 태도가 뒤에 나올 총체예술로 이어져요."}],"walk":{"head":null,"parts":[{"b":[0.03,0.15,0.38,0.72],"c":[0.011,0.114,0.418,0.792],"r":0.7037,"img":"img/U2/walk/p010_21_01.jpg","say":"왼쪽 식당 사진이에요. 천장 가운데에서 곡선이 퍼져 조명으로 내려와요."},{"b":[0.42,0.2,0.54,0.62],"c":[0.393,0.169,0.594,0.682],"r":1.1613,"img":"img/U2/walk/p010_21_02.jpg","say":"오른쪽 사진이에요. 타일 아치가 이어지고 끝에 또 다른 방이 보여요."},{"b":[0.04,0.88,0.4,0.05],"c":[0.02,0.85,0.44,0.11],"r":5.3333,"img":"img/U2/walk/p010_21_03.jpg","say":"캡션이에요. **빅토르 오르타(Victor Horta)**, **오르타 저택**, 벨기에 브뤼셀, 1911."}]}},{"p":11,"title":"빅토르 오르타, 타셀 저택, 브뤼셀, 1893","terms":["Victor Horta","타셀 저택","오르타 저택","Art Nouveau"],"pass1":[{"kind":"say","lines":["왼쪽에 항목 네 줄, 오른쪽에 계단실 사진 두 장이에요.","캡션은 '빅토르 오르타(1861~1947), 타셀 저택, 벨기에 브뤼셀, 1893' 이에요.","**아르 누보(Art Nouveau)** 건축의 출발점으로 꼽히는 집이에요."]},{"kind":"analogy","head":"좁은 집에 빛 구멍","scene":"길쭉하고 좁은 집 가운데를 파내어 하늘을 들인 모습이에요.","map":[["파낸 구멍","평면의 일부를 파내어 만든 빈 곳"],["들어온 하늘빛","좁은 공간의 채광 해결"],["밝아진 가운데","밝고 가벼운 공간"]]}],"pass2":[{"kind":"points","head":"**타셀 저택**(1893)의 특징","items":["주택에 새로운 가능성이 있는 재료를 사용했어요. 가는 금속 기둥이 그 예예요.","1층 평면에 융통성을 부여했어요. 벽으로 딱딱하게 나누지 않았다는 뜻이에요.","평면의 일부를 파내어 좁은 공간의 채광을 해결했어요.","결과는 밝고 가벼운 공간이에요. 무겁게 돌로 막힌 집과 정반대예요."]},{"kind":"compare","head":"오르타의 두 집 구별하기","cols":["**타셀 저택**","**오르타 저택**"],"rows":[["1893년","1911년"],["남의 집, 의뢰받은 주택","자기 집, 지금의 오르타 박물관"],["평면을 파내 채광, 밝고 가벼운 공간","타일, 캐비닛, 조명, 가구까지 전부 직접 디자인"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**타셀 저택** 에서 좁은 공간의 채광을 해결한 방법은 무엇인가요?","choices":["평면의 일부를 파냄","지붕을 유리로 덮음","벽을 모두 유리로 바꿈"],"a":0,"why":"1층 평면에 융통성을 주고 평면 일부를 파내어 빛을 들였어요. 그래서 밝고 가벼운 공간이 됐어요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**타셀 저택** 1893, **오르타 저택** 1911. 숫자를 바꿔 쓰는 문제가 자주 나와요.","**빅토르 오르타(Victor Horta)** 의 생몰년 1861-1947 도 객관식 보기로 나와요."]},{"kind":"english","head":"논술 답안: 타셀 저택","en":"타셀 저택은 1893년 브뤼셀에 지어진 오르타의 주택으로 새로운 가능성의 재료를 사용하고 1층 평면에 융통성을 부여하였으며 평면의 일부를 파내어 좁은 공간의 채광을 해결한 밝고 가벼운 공간이다.","ko":"연도와 도시, 재료, 평면 융통성, 채광, 밝고 가벼운 공간 순서로 써요.","tip":"파낸 평면이 빛을 부른다고 그림으로 기억해요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.06,0.45,0.29],"c":[0.0275,0.044,0.495,0.322],"r":2.0497,"img":"img/U2/walk/p011_22_01.jpg","say":"왼쪽 항목 네 줄이에요. 새 재료, 평면의 융통성, 채광, 밝고 가벼운 공간."},{"b":[0.5,0.03,0.47,0.89],"c":[0.4765,0,0.517,0.979],"r":0.7041,"img":"img/U2/walk/p011_22_02.jpg","say":"오른쪽 큰 사진이에요. 가는 금속 기둥이 위에서 식물처럼 갈라져요."},{"b":[0.13,0.42,0.34,0.5],"c":[0.113,0.395,0.374,0.55],"r":0.9067,"img":"img/U2/walk/p011_22_03.jpg","say":"작은 사진이에요. 벽에 흐르는 곡선 무늬가 계단 난간과 이어져 보여요."},{"b":[0.41,0.94,0.56,0.05],"c":[0.382,0.8755,0.616,0.1245],"r":6.5971,"img":"img/U2/walk/p011_22_04.jpg","say":"캡션이에요. **빅토르 오르타(Victor Horta)**, **타셀 저택**, 벨기에 브뤼셀, 1893."}]}},{"p":12,"title":"프랑스의 아르누보, 엑토르 기마르","terms":["Art Nouveau","Hector Guimard","포르트 도핀 역 입구"],"pass1":[{"kind":"say","lines":["위에 항목 두 줄, 아래에 큰 사진 한 장이에요. 공원 안 지하철 입구예요.","캡션은 '엑토르 귀마르, 포르트 도핀(Porte Dauphine) 역 입구, 파리' 예요.","**엑토르 기마르(Hector Guimard)** 는 **아르 누보(Art Nouveau)** 를 지하철 입구에 들여온 사람이에요."]},{"kind":"analogy","head":"레고로 만든 입구","scene":"같은 블록을 몇 가지만 만들어 두고 자리마다 다르게 조립하는 방식이에요.","map":[["레고 블록","표준화된 금속 요소"],["조립 방법 바꾸기","다양한 크기와 형태의 키오스크"],["블록 무늬","자연과 연관된 곡선 디테일"]]}],"pass2":[{"kind":"points","head":"**엑토르 기마르(Hector Guimard)**, 1867-1942","items":["**아르 누보(Art Nouveau)** 양식을 지하철 입구 건축에 도입했어요.","파리 메트로 역 입구에서 조립을 통해 다양한 크기와 형태의 키오스크를 만들 수 있는 표준화된 금속 요소를 썼어요.","모든 것에서 자연과 연관된 형태를 가지는 곡선의 디테일을 썼어요.","**포르트 도핀 역 입구** 는 지붕이 부채처럼 펼쳐진 형태로 슬라이드에 실려 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**엑토르 기마르(Hector Guimard)** 가 파리 메트로 입구에 사용한 방법은 무엇인가요?","choices":["표준화된 금속 요소를 조립","대리석을 현장에서 깎음","벽돌 아치를 쌓음"],"a":0,"why":"표준화된 요소를 조립해서 자리마다 크기와 형태가 다른 키오스크를 만들었어요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.04,0.28,0.06],"c":[0.026,0.015,0.308,0.11],"r":3.7333,"img":"img/U2/walk/p012_21_01.jpg","say":"제목이에요. 프랑스의 아르누보."},{"b":[0.37,0.04,0.5,0.1],"c":[0.345,0.024,0.55,0.132],"r":5.5556,"img":"img/U2/walk/p012_21_02.jpg","say":"인물 표시와 한 줄 설명이에요. **엑토르 기마르(Hector Guimard)**, 1867-1942."},{"b":[0.04,0.19,0.92,0.15],"c":[0.0,0.1628,1,0.2045],"r":6.52,"img":"img/U2/walk/p012_21_03.jpg","say":"표준화된 금속 요소로 다양한 키오스크를 조립했다는 항목이에요."},{"b":[0.02,0.42,0.53,0.53],"c":[0,0.3935,0.583,0.583],"r":1.3333,"img":"img/U2/walk/p012_21_04.jpg","say":"**포르트 도핀 역 입구** 사진이에요. 부채꼴 유리 차양과 초록 금속 뼈대를 보세요."},{"b":[0.54,0.88,0.43,0.07],"c":[0.5185,0.86,0.473,0.11],"r":5.7333,"img":"img/U2/walk/p012_21_05.jpg","say":"캡션이에요. 포르트 도핀(Porte Dauphine) 역 입구, 파리."}]}},{"p":13,"title":"기마르, 바스티유 역 출입문과 카스텔 베랑제","terms":["Hector Guimard","카스텔 베랑제","바스티유 역 출입문","wrought iron"],"pass1":[{"kind":"say","lines":["그림 한 장과 사진 한 장이에요. 왼쪽은 지하철 출입문, 오른쪽은 건물 현관이에요.","캡션은 '바스티유 지하철 역 출입문, 프랑스 파리, c.1900' 과 '카스텔 베랑제 공동주택, 프랑스 파리, 1898' 이에요.","**엑토르 기마르(Hector Guimard)** 의 작품 두 개를 나란히 보여 주는 쪽이에요."]},{"kind":"analogy","head":"나뭇가지로 짠 대문","scene":"쇠막대를 나뭇가지처럼 휘어 엮어 만든 대문이에요.","map":[["휜 쇠막대","**단철(wrought iron)** 곡선"],["가지 사이 빈 곳","빛이 통하는 문살"],["나무처럼 보이는 문","자연과 연관된 형태의 디테일"]]}],"pass2":[{"kind":"points","head":"이 두 작품에서 볼 것","items":["**바스티유 역 출입문** 은 c.1900 파리예요. 차양이 물결처럼 휘고 가운데 METROPOLITAIN 간판이 붙어요.","**카스텔 베랑제** 는 1898년 파리의 공동주택이에요. 현관 홀 사진이 실려 있어요.","현관 문살이 **단철(wrought iron)** 을 휘어 만든 굵은 곡선이라 나뭇가지처럼 보여요.","두 작품 모두 **엑토르 기마르(Hector Guimard)** 가 곡선 디테일을 쇠로 뽑아낸 예예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**카스텔 베랑제** 공동주택의 연도와 도시는 무엇인가요?","choices":["파리, 1898","브뤼셀, 1893","글래스고, 1899"],"a":0,"why":"**엑토르 기마르(Hector Guimard)** 의 파리 공동주택, 1898 이에요."},{"kind":"english","head":"논술 답안: 엑토르 기마르","en":"엑토르 기마르는 아르 누보 양식을 지하철 입구 건축에 도입하여 파리 메트로에서 표준화된 금속 요소의 조립으로 다양한 키오스크를 만들었으며, 대표작으로 포르트 도핀 역 입구, 바스티유 역 출입문, 카스텔 베랑제 공동주택(1898)이 있다.","ko":"지하철 입구, 표준화 금속 요소, 작품 세 개가 채점 항목이에요.","tip":"지하철 입구 아저씨, 레고 조립, 카스텔 베랑제 1898 로 묶어요."}],"walk":{"head":null,"parts":[{"b":[0.02,0.28,0.55,0.52],"c":[0,0.254,0.605,0.572],"r":1.4103,"img":"img/U2/walk/p013_21_01.jpg","say":"왼쪽 그림이에요. **바스티유 역 출입문** 의 휘어 오른 차양과 아치를 보세요."},{"b":[0.18,0.8,0.4,0.06],"c":[0.16,0.775,0.44,0.11],"r":5.3333,"img":"img/U2/walk/p013_21_02.jpg","say":"왼쪽 캡션이에요. 바스티유 지하철 역 출입문, 프랑스 파리, c.1900."},{"b":[0.58,0.08,0.39,0.82],"c":[0.5605,0.039,0.429,0.902],"r":0.6341,"img":"img/U2/walk/p013_21_03.jpg","say":"오른쪽 사진이에요. **카스텔 베랑제** 현관 홀, 굵은 곡선 문살이 빛을 가로질러요."},{"b":[0.62,0.91,0.36,0.07],"c":[0.602,0.89,0.396,0.11],"r":4.8,"img":"img/U2/walk/p013_21_04.jpg","say":"오른쪽 캡션이에요. 카스텔 베랑제 공동주택, 프랑스 파리, 1898."}]}},{"p":14,"title":"맥킨토시의 아르누보","terms":["찰스 레니 매킨토시","Art Nouveau","Arts and Crafts Movement","Red House"],"pass1":[{"kind":"say","lines":["인물 표시 한 줄, 항목 두 줄, 그리고 초상 사진과 길쭉한 그래픽 한 장이에요.","**찰스 레니 매킨토시** 는 스코틀랜드의 건축가, 디자이너, 수채화 화가예요.","곡선에서 시작해 점점 사각형으로 넘어가는 사람이라 주문의 '정리' 자리에 가까워요."]},{"kind":"recap","items":["**아르 누보(Art Nouveau)** 는 꽃과 덩굴의 곡선이에요.","**찰스 레니 매킨토시** 는 그 곡선을 가늘고 길게 뽑다가 격자로 정리해요.","그래서 다음 쪽 **힐하우스** 에서 곡선보다 격자가 더 눈에 띄어요."]}],"pass2":[{"kind":"points","head":"**찰스 레니 매킨토시**, 1868-1928","items":["스코틀랜드의 건축가이자 디자이너, 수채화 화가예요.","과거의 예술적인 전통들을 모아 창조적으로 재해석했어요.","1강 **미술공예운동(Arts and Crafts Movement)** 의 **붉은 집(Red House)** 처럼 집 전체를 한 손으로 다루지만, 붉은 벽돌 대신 회색 회벽을 써요.","오른쪽 그래픽은 그의 포스터 디자인이에요. 가늘고 긴 선이 여러 번 휘어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**찰스 레니 매킨토시** 의 국적은 어디인가요?","choices":["스코틀랜드","벨기에","스페인"],"a":0,"why":"스코틀랜드의 건축가, 디자이너, 수채화 화가예요. 생몰년은 1868-1928 이에요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.04,0.28,0.06],"c":[0.026,0.015,0.308,0.11],"r":3.7333,"img":"img/U2/walk/p014_21_01.jpg","say":"제목이에요. 맥킨토시의 아르누보."},{"b":[0.04,0.17,0.66,0.05],"c":[0.007,0.1217,0.726,0.1467],"r":6.5985,"img":"img/U2/walk/p014_21_02.jpg","say":"인물 표시예요. **찰스 레니 매킨토시**(Charles Rennie Mackintosh, 1868~1928)."},{"b":[0.06,0.24,0.6,0.11],"c":[0.03,0.224,0.66,0.142],"r":6.1972,"img":"img/U2/walk/p014_21_03.jpg","say":"항목 두 줄이에요. 스코틀랜드의 건축가, 디자이너, 수채화 화가."},{"b":[0.27,0.42,0.23,0.53],"c":[0.258,0.3935,0.254,0.583],"r":0.5809,"img":"img/U2/walk/p014_21_04.jpg","say":"초상 사진이에요. 아래에 1868-1928 생몰년이 적혀 있어요."},{"b":[0.63,0.41,0.3,0.55],"c":[0.615,0.3825,0.33,0.605],"r":0.7273,"img":"img/U2/walk/p014_21_05.jpg","say":"포스터 그래픽이에요. 가늘고 긴 곡선과 네모 글자칸이 함께 있어요."}]}},{"p":15,"title":"찰스 레니 매킨토시, 힐하우스, 헬렌스버러, 1904","terms":["찰스 레니 매킨토시","힐하우스","Red House","Art Nouveau"],"pass1":[{"kind":"say","lines":["왼쪽에 평면도, 오른쪽에 외관 사진, 아래에 특징 목록이 있어요.","캡션은 '찰스 레니 매킨토시, 힐하우스, 영국 헬렌스버러, 1904' 예요.","**힐하우스** 는 회색 회벽에 급경사 지붕을 얹은 조용한 집이에요."]},{"kind":"analogy","head":"회색 종이로 접은 집","scene":"회색 도화지를 접어 세우고 위에 짙은 지붕만 얹은 모습이에요.","map":[["회색 도화지","회색의 회벽"],["얇게 접힌 끝","얕은 처마"],["덧붙인 원통","돌출된 반원형의 탑"]]}],"pass2":[{"kind":"points","head":"**힐하우스**(1904)의 특징","items":["평면의 주요 부분과 서비스 윙이 직각으로 배치돼요. 살림 공간과 부엌 쪽이 ㄱ 자로 꺾여요.","회색의 회벽이에요. 돌이나 벽돌 무늬가 보이지 않아요.","얕은 처마와 급경사의 슬레이트 지붕이에요. 지붕이 벽 밖으로 거의 나오지 않아요.","돌출된 반원형의 탑이 있어요. 벽에서 원통이 툭 튀어나와요.","그리드로 분할된 단순한 개구부예요. 창이 격자로 반듯하게 나뉘어요."]},{"kind":"compare","head":"**힐하우스** 와 **붉은 집(Red House)** 구별하기","cols":["**힐하우스**","**붉은 집(Red House)**"],"rows":[["1904년, 영국 헬렌스버러","1859년, 영국 벡슬리 히스"],["**찰스 레니 매킨토시**","필립 웹과 윌리엄 모리스"],["회색 회벽, 급경사 슬레이트 지붕, 반원형 탑","붉은 벽돌을 그대로 드러낸 벽"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**힐하우스** 의 위치와 연도는 무엇인가요?","choices":["영국 헬렌스버러, 1904","영국 글래스고, 1899","영국 벡슬리 히스, 1859"],"a":0,"why":"글래스고 예술학교가 1899년, **붉은 집(Red House)** 이 1859년이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["붉은 벽돌은 **붉은 집(Red House)** 의 특징이에요. **힐하우스** 는 회색 회벽이에요.","**힐하우스** 의 곡선은 반원형 탑 정도예요. 오르타 같은 흐르는 곡선을 기대하면 틀려요."]},{"kind":"english","head":"논술 답안: 힐하우스","en":"힐하우스는 1904년 영국 헬렌스버러에 지은 매킨토시의 주택으로 평면의 주요 부분과 서비스 윙이 직각으로 배치되며, 회색의 회벽, 얕은 처마와 급경사의 슬레이트 지붕, 돌출된 반원형의 탑, 그리드로 분할된 단순한 개구부를 특징으로 한다.","ko":"평면 직각 배치와 외관 네 가지가 채점 항목이에요.","tip":"회벽, 급경사 지붕, 반원 탑, 격자 창 네 개를 손가락으로 세어요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.06,0.12,0.05],"c":[0.0,0.03,0.2,0.11],"r":2.4242,"img":"img/U2/walk/p015_22_01.jpg","say":"왼쪽 위 제목이에요. 힐하우스."},{"b":[0.03,0.2,0.44,0.29],"c":[0.008,0.184,0.484,0.322],"r":2.0041,"img":"img/U2/walk/p015_22_02.jpg","say":"평면도예요. 긴 복도(CORRIDOR)를 사이에 두고 주요부와 서비스 윙이 직각으로 꺾여요."},{"b":[0.5,0.0,0.49,0.49],"c":[0.461,0,0.539,0.539],"r":1.3333,"img":"img/U2/walk/p015_22_03.jpg","say":"외관 사진이에요. 밝은 회벽, 짙은 급경사 지붕, 오른쪽의 원통형 탑을 보세요."},{"b":[0.49,0.5,0.45,0.05],"c":[0.4675,0.47,0.495,0.11],"r":6.0,"img":"img/U2/walk/p015_22_04.jpg","say":"캡션이에요. **찰스 레니 매킨토시**, **힐하우스**, 영국 헬렌스버러, 1904."},{"b":[0.06,0.58,0.62,0.37],"c":[0.029,0.5615,0.682,0.407],"r":2.2342,"img":"img/U2/walk/p015_22_05.jpg","say":"아래 특징 목록이에요. 회벽, 얕은 처마, 급경사 지붕, 반원형 탑, 격자 개구부."}]}},{"p":16,"title":"힐하우스의 침실과 실내","terms":["힐하우스","찰스 레니 매킨토시","Art Nouveau"],"pass1":[{"kind":"say","lines":["사진 세 장뿐인 쪽이에요. 위 흑백은 침실, 아래는 창가 거실, 오른쪽은 의자와 스탠드예요.","글은 '힐하우스의 침실' 한 줄뿐이에요.","**찰스 레니 매킨토시** 의 실내는 밝은 바탕에 가는 검은 선으로 정리돼 있어요."]},{"kind":"analogy","head":"흰 종이에 그은 검은 줄","scene":"흰 벽에 가는 검은 자를 대고 줄을 그은 모습이에요.","map":[["흰 종이","밝은 회벽과 흰 가구"],["검은 줄","가늘고 긴 세로선과 격자"],["작게 찍은 분홍 점","장미 무늬 같은 아주 적은 곡선 장식"]]}],"pass2":[{"kind":"points","head":"이 사진들에서 볼 것","items":["위 흑백 사진은 **힐하우스** 의 침실이에요. 붙박이장 문에 가늘고 긴 세로선이 들어가요.","벽에 붙은 긴 의자와 등받이가 아주 높은 검은 의자가 함께 보여요. 가구도 **찰스 레니 매킨토시** 가 디자인했어요.","아래 컬러 사진은 창가예요. 커튼과 창살이 모두 반듯한 격자로 나뉘어요.","오른쪽 사진은 벽에 두른 장미 무늬 띠와 스탠드예요. 곡선 장식이 아주 조금만 남아 있어요.","**아르 누보(Art Nouveau)** 의 흐르는 곡선이 여기서는 가는 직선과 작은 무늬로 줄어들었어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**힐하우스** 실내에서 **찰스 레니 매킨토시** 가 보여 주는 특징은 무엇인가요?","choices":["흐르는 곡선으로 벽 전체를 덮음","밝은 바탕에 가늘고 긴 직선과 격자","금과 은으로 된 화려한 부조"],"a":1,"why":"곡선에서 기하학적이고 간결한 쪽으로 옮겨 가는 중이라는 것을 실내에서 확인할 수 있어요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.03,0.52,0.45],"c":[0.024,0.0075,0.572,0.495],"r":1.5407,"img":"img/U2/walk/p016_21_01.jpg","say":"위 흑백 사진이에요. 붙박이장 문의 세로선과 높은 등받이 의자를 보세요."},{"b":[0.05,0.47,0.2,0.05],"c":[0.038,0.44,0.224,0.11],"r":2.7152,"img":"img/U2/walk/p016_21_02.jpg","say":"글 한 줄이에요. 힐하우스의 침실."},{"b":[0.04,0.53,0.55,0.45],"c":[0.0125,0.505,0.605,0.495],"r":1.6296,"img":"img/U2/walk/p016_21_03.jpg","say":"아래 컬러 사진이에요. 창살과 커튼이 격자로 나뉘고 흰색이 지배해요."},{"b":[0.61,0.22,0.36,0.48],"c":[0.592,0.196,0.396,0.528],"r":1.0,"img":"img/U2/walk/p016_21_04.jpg","say":"오른쪽 사진이에요. 벽 위쪽에 분홍 장미 무늬 띠가 한 줄 둘러져 있어요."}]}},{"p":17,"title":"House for an Art Lover, 글래스고, 1901","terms":["찰스 레니 매킨토시","House for an Art Lover","힐하우스","Arts and Crafts Movement"],"pass1":[{"kind":"say","lines":["그림 두 장, 사진 한 장, 설명 상자 하나가 있는 쪽이에요.","**House for an Art Lover** 는 독일 디자인 잡지 공모전에 낸 **찰스 레니 매킨토시** 의 주택안이에요.","실제 살려고 지은 집이 아니라 공모전에 낸 그림이라는 점이 시험에 나와요."]},{"kind":"analogy","head":"공모전에 낸 도면","scene":"실제로 짓지 않고 그림으로만 제출한 설계 대회 작품이에요.","map":[["대회 요강","진짜 독창적인 현대 디자인"],["함께 내는 팀","건축가와 장식 예술가가 공동으로 개발"],["제출물","리셉션룸과 다이닝룸 투시도"]]}],"pass2":[{"kind":"points","head":"**House for an Art Lover**(1901)의 기본 사실","items":["**찰스 레니 매킨토시**, 영국 글래스고, 1901 이에요.","독일 디자인 잡지 Zeitschrift Fur Innendekoration 이 주최한 Art Lovers House 공모전 참가작품이에요.","공모 지침은 진짜 독창적인 현대 디자인이었어요.","또 하나의 지침은 현대적 취향의 건축가와 장식 예술가가 공동으로 디자인을 개발하는 것이었어요."]},{"kind":"look","walked":1},{"kind":"bg","src":"기초 다지기: 왜 잡지가 공모전을 열었나요","lines":["1강의 **미술공예운동(Arts and Crafts Movement)** 이후 집 안 전체를 한 사람이 디자인하자는 생각이 퍼졌어요.","잡지는 건축가와 장식 예술가가 함께 만든 새 집을 찾고 싶어 공모전을 열었어요.","그래서 지침에 '공동으로 디자인을 개발' 이라는 말이 들어가요."]}],"pass3":[{"kind":"check","q":"**House for an Art Lover**(1901)는 무엇을 위한 작품인가요?","choices":["독일 디자인 잡지가 주최한 공모전 참가작","실제 거주용으로 지은 주택","박람회 전시관"],"a":0,"why":"Zeitschrift Fur Innendekoration 이 주최한 Art Lovers House 공모전 참가작품이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**House for an Art Lover** 는 1901년 글래스고, **힐하우스** 는 1904년 헬렌스버러예요.","연도와 도시를 서로 바꿔 놓는 객관식이 자주 나와요."]}],"walk":{"head":null,"parts":[{"b":[0.03,0.02,0.25,0.05],"c":[0.0175,0,0.275,0.11],"r":3.3333,"img":"img/U2/walk/p017_21_01.jpg","say":"맨 위 제목이에요. 'House for an Art Lover'."},{"b":[0.02,0.06,0.43,0.4],"c":[0,0.04,0.473,0.44],"r":1.4333,"img":"img/U2/walk/p017_21_02.jpg","say":"왼쪽 그림, 리셉션룸이에요. 바닥에서 천장까지 가는 기둥이 줄지어 서요."},{"b":[0.47,0.06,0.52,0.41],"c":[0.428,0.0395,0.572,0.451],"r":1.6911,"img":"img/U2/walk/p017_21_03.jpg","say":"오른쪽 그림, 다이닝룸이에요. 긴 식탁과 나무 패널 벽이 이어져요."},{"b":[0.02,0.53,0.51,0.41],"c":[0,0.5095,0.561,0.451],"r":1.6585,"img":"img/U2/walk/p017_21_04.jpg","say":"아래 사진이에요. 흰 벽에 길게 뻗은 지붕, 창이 격자로 반듯해요."},{"b":[0.53,0.55,0.42,0.35],"c":[0.509,0.5325,0.462,0.385],"r":1.6,"img":"img/U2/walk/p017_21_05.jpg","say":"오른쪽 설명 상자예요. 공모전 이름과 공모 지침 두 가지가 적혀 있어요."},{"b":[0.43,0.95,0.55,0.045],"c":[0.395,0.8778,0.605,0.1222],"r":6.6012,"img":"img/U2/walk/p017_21_06.jpg","say":"캡션이에요. **찰스 레니 매킨토시**, 'House for an Art Lover', 영국 글래스고, 1901."}]}},{"p":18,"title":"찰스 레니 매킨토시, 벽면 부조 디자인, 1906","terms":["찰스 레니 매킨토시","벽면 부조 디자인","Art Nouveau"],"pass1":[{"kind":"say","lines":["사진 두 장뿐인 쪽이에요. 큰 사진은 가까이서, 작은 사진은 멀리서 찍었어요.","캡션은 '찰스 레니 매킨토시, 벽면 부조 디자인, 1906' 이에요.","**벽면 부조 디자인** 은 벽 한 면을 장식으로 덮은 작품이에요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["**찰스 레니 매킨토시** 가 1906년에 만든 **벽면 부조 디자인** 이에요.","표면에 동그랗게 말린 장미 모양 덩어리가 여러 개 도드라져 있어요.","그 사이를 아주 가늘고 긴 선이 길게 가로지르며 잇고 있어요.","색은 연한 회색과 보라, 초록 점만 조금 쓰였어요. 화려한 색은 없어요.","**아르 누보(Art Nouveau)** 의 꽃 모티프가 남아 있지만 선이 훨씬 가늘고 곧아요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**벽면 부조 디자인**(1906)에서 반복되는 모양은 무엇인가요?","choices":["동그랗게 말린 장미 모양","번개와 지그재그","정사각 격자만"],"a":0,"why":"장미 모양 덩어리와 가는 선이 특징이에요. 번개와 지그재그는 뒤에 나올 **아르데코** 예요."}],"walk":{"head":null,"parts":[{"b":[0.02,0.02,0.66,0.66],"c":[0,0,0.726,0.726],"r":1.3333,"img":"img/U2/walk/p018_21_01.jpg","say":"큰 사진이에요. 말린 장미 덩어리와 그 사이를 잇는 가는 선을 보세요."},{"b":[0.57,0.51,0.41,0.39],"c":[0.549,0.4905,0.451,0.429],"r":1.4017,"img":"img/U2/walk/p018_21_02.jpg","say":"작은 사진이에요. 부조가 벽처럼 세워져 방 한쪽을 덮고 있어요."},{"b":[0.59,0.93,0.39,0.05],"c":[0.5705,0.89,0.429,0.11],"r":5.2,"img":"img/U2/walk/p018_21_03.jpg","say":"캡션이에요. **찰스 레니 매킨토시**, **벽면 부조 디자인**, 1906."}]}},{"p":19,"title":"찰스 레니 매킨토시, 글래스고 예술학교, 1899","terms":["찰스 레니 매킨토시","글래스고 예술학교","아르데코","Art Nouveau","힐하우스"],"pass1":[{"kind":"say","lines":["왼쪽에 제목, 오른쪽에 항목 네 줄, 아래에 사진 두 장이에요.","캡션은 '찰스 레니 매킨토시, 글래스고 예술학교, 영국 글래스고, 1899' 예요.","여기서 곡선이 줄고 커다란 유리면과 각진 형태가 앞으로 나와요."]},{"kind":"recap","items":["**아르 누보(Art Nouveau)** 는 꽃과 덩굴의 곡선이에요.","**글래스고 예술학교** 는 그 곡선을 줄이고 기하학으로 넘어가요.","주문으로 말하면 새 장식에서 정리로 넘어가는 자리예요."]}],"pass2":[{"kind":"points","head":"**글래스고 예술학교**(1899)의 특징","items":["가늘고 긴 곡선의 표현으로부터 훨씬 더 기하학적이고 간결한 양식으로 변화했어요.","**아르데코** 양식을 예견했고, **아르 누보(Art Nouveau)** 와 모던의 경계에 있어요.","커다란 유리면의 외관이에요. 벽보다 창이 더 크게 보여요.","예각 형태와 유연한 곡선의 조화예요. 뾰족한 각과 부드러운 곡선이 함께 있어요.","1909년에 도서관의 커튼월이 증축돼요. 다음 쪽에서 그 사진을 봐요."]},{"kind":"compare","head":"매킨토시의 두 작품 구별하기","cols":["**글래스고 예술학교**","**힐하우스**"],"rows":[["1899년, 영국 글래스고","1904년, 영국 헬렌스버러"],["학교 건물, 커다란 유리면","주택, 회색 회벽과 급경사 지붕"],["**아르데코** 를 예견, 모던의 경계","반원형 탑과 격자 개구부"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**아르 누보(Art Nouveau)** 와 모던의 경계에 있으며 **아르데코** 를 예견한 매킨토시의 1899년 작품은 무엇인가요?","choices":["**힐하우스**","**글래스고 예술학교**","**House for an Art Lover**"],"a":1,"why":"**글래스고 예술학교** 예요. 커다란 유리면과 예각 형태가 특징이에요."},{"kind":"english","head":"논술 답안: 글래스고 예술학교","en":"글래스고 예술학교는 1899년 매킨토시의 작품으로 가늘고 긴 곡선의 표현에서 훨씬 기하학적이고 간결한 양식으로 변화하였으며, 커다란 유리면의 외관과 예각 형태 및 유연한 곡선의 조화를 보여 아르데코를 예견한 아르 누보와 모던의 경계에 있는 건물이다.","ko":"곡선에서 기하학으로 변화, 유리면, 예각과 곡선, 아르데코 예견이 채점 항목이에요.","tip":"곡선이 각으로 바뀌는 학교라고 외워요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.06,0.19,0.05],"c":[0.028,0.03,0.214,0.11],"r":2.5939,"img":"img/U2/walk/p019_22_01.jpg","say":"왼쪽 제목이에요. 글래스고 예술학교."},{"b":[0.26,0.06,0.68,0.12],"c":[0.226,0.044,0.748,0.152],"r":6.5614,"img":"img/U2/walk/p019_22_02.jpg","say":"첫 항목이에요. 가늘고 긴 곡선에서 기하학적이고 간결한 양식으로 변화."},{"b":[0.26,0.19,0.68,0.16],"c":[0.226,0.174,0.748,0.192],"r":5.1944,"img":"img/U2/walk/p019_22_03.jpg","say":"나머지 항목이에요. **아르데코** 예견, 커다란 유리면, 예각과 곡선의 조화."},{"b":[0.07,0.36,0.35,0.58],"c":[0.0525,0.331,0.385,0.638],"r":0.8046,"img":"img/U2/walk/p019_22_04.jpg","say":"왼쪽 사진이에요. 큰 유리창이 벽을 채우고 현관 위에 곡선 철물이 걸려 있어요."},{"b":[0.44,0.36,0.49,0.51],"c":[0.4155,0.3345,0.539,0.561],"r":1.281,"img":"img/U2/walk/p019_22_05.jpg","say":"오른쪽 사진이에요. 거친 돌벽 옆에 검은 틀의 큰 격자 유리면이 붙어요."},{"b":[0.45,0.88,0.48,0.05],"c":[0.426,0.85,0.528,0.11],"r":6.4,"img":"img/U2/walk/p019_22_06.jpg","say":"캡션이에요. **글래스고 예술학교**, 영국 글래스고, 1899."}]}},{"p":20,"title":"글래스고 예술학교 도서관의 커튼월, 1909년 증축","terms":["글래스고 예술학교","찰스 레니 매킨토시","아르데코"],"pass1":[{"kind":"say","lines":["사진 두 장뿐인 쪽이에요. 왼쪽은 창을 올려다본 사진, 오른쪽은 도서관 안이에요.","캡션은 '찰스 레니 매킨토시, 글래스고 예술학교, 도서관의 커튼월, 1909년 증축' 이에요.","커튼월은 벽이 무게를 받지 않고 커튼처럼 매달린 유리면이에요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["**글래스고 예술학교** 의 도서관 커튼월이에요. 1909년 증축이에요.","왼쪽 사진은 아래에서 올려다본 모습이에요. 격자 유리가 위로 갈수록 좁아져요.","창틀 옆으로 색색 구슬 같은 장식이 줄지어 달려 있어요.","오른쪽 사진은 도서관 안이에요. 굵은 나무 기둥과 보가 직각으로 짜여요.","여기서는 곡선이 거의 없고 네모와 직선뿐이에요. 뒤에 올 **아르데코** 의 기하 감각과 이어져요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**글래스고 예술학교** 도서관의 커튼월이 증축된 해는 언제인가요?","choices":["1899","1904","1909"],"a":2,"why":"본관이 1899년, 도서관 커튼월 증축이 1909년이에요."}],"walk":{"head":null,"parts":[{"b":[0.01,0.12,0.48,0.76],"c":[0,0.082,0.528,0.836],"r":0.8421,"img":"img/U2/walk/p020_21_01.jpg","say":"왼쪽 사진이에요. 올려다본 커튼월. 유리 격자가 위로 모여 삼각처럼 보여요."},{"b":[0.03,0.9,0.47,0.07],"c":[0.0065,0.88,0.517,0.11],"r":6.2667,"img":"img/U2/walk/p020_21_02.jpg","say":"캡션이에요. **글래스고 예술학교**, 도서관의 커튼월, 1909년 증축."},{"b":[0.52,0.07,0.46,0.88],"c":[0.494,0.026,0.506,0.968],"r":0.697,"img":"img/U2/walk/p020_21_03.jpg","say":"오른쪽 사진이에요. 도서관 안. 굵은 나무 기둥과 보가 격자로 짜여 있어요."}]}},{"p":21,"title":"가우디의 아르누보, 안토니 가우디","terms":["안토니 가우디","사그라다 파밀리아","Art Nouveau"],"pass1":[{"kind":"say","lines":["왼쪽에 인물 소개, 오른쪽 위에 초상 사진, 오른쪽 아래에 조각 사진이에요.","**안토니 가우디**(1852-1926)는 스페인 바르셀로나에서 일한 건축가예요.","다른 사람들이 납작한 곡선을 그릴 때 가우디는 3차원 곡선을 만들어요."]},{"kind":"analogy","head":"찰흙으로 빚은 건물","scene":"종이를 오려 붙이지 않고 찰흙을 주물러 만든 모양이에요.","map":[["종이 오리기","평면에 그린 **아르 누보(Art Nouveau)** 의 곡선"],["찰흙 주무르기","**안토니 가우디** 의 흐르는 3차원 곡선"],["표면에 박은 조각","특이한 장식 디테일"]]}],"pass2":[{"kind":"points","head":"**안토니 가우디**, 1852-1926","items":["흐르는 곡선(3차원)들과 특이한 장식 디테일로 된 매우 개성 있는 표현 기법의 창시자예요.","중세건축에서 영향을 받았어요.","벽돌과 석재를 사용했어요. 철과 유리를 앞세운 다른 **아르 누보(Art Nouveau)** 작가와 다른 점이에요.","설득력이 강한 표현주의적 건축이에요.","초현실주의적 조각과 회화의 선조로 평가돼요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**안토니 가우디** 가 선조로 평가되는 예술 사조는 무엇인가요?","choices":["초현실주의 조각과 회화","입체파","팝아트"],"a":0,"why":"설득력이 강한 표현주의적 건축이며 초현실주의적 조각과 회화의 선조예요."},{"kind":"english","head":"논술 답안: 안토니 가우디","en":"안토니 가우디는 흐르는 3차원 곡선과 특이한 장식 디테일로 된 매우 개성 있는 표현 기법의 창시자로 중세건축의 영향을 받아 벽돌과 석재를 사용하였으며, 설득력이 강한 표현주의적 건축이자 초현실주의적 조각과 회화의 선조로 평가된다.","ko":"3차원 곡선, 중세건축, 벽돌과 석재, 표현주의, 초현실주의 다섯 개가 채점 항목이에요.","tip":"찰흙 아저씨, 중세, 벽돌, 표현주의, 초현실주의 순서로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.04,0.26,0.06],"c":[0.027,0.015,0.286,0.11],"r":3.4667,"img":"img/U2/walk/p021_21_01.jpg","say":"제목이에요. 가우디의 아르누보."},{"b":[0.04,0.16,0.45,0.05],"c":[0.0175,0.13,0.495,0.11],"r":6.0,"img":"img/U2/walk/p021_21_02.jpg","say":"인물 표시예요. 안토니 가우디(Antoni Gaudi, 1852-1926)."},{"b":[0.04,0.23,0.6,0.34],"c":[0.01,0.213,0.66,0.374],"r":2.3529,"img":"img/U2/walk/p021_21_03.jpg","say":"특징 다섯 줄이에요. 3차원 곡선, 중세건축, 벽돌과 석재, 표현주의, 초현실주의의 선조."},{"b":[0.66,0.05,0.23,0.46],"c":[0.648,0.027,0.254,0.506],"r":0.6693,"img":"img/U2/walk/p021_21_04.jpg","say":"가우디 초상 사진이에요."},{"b":[0.48,0.52,0.5,0.42],"c":[0.45,0.499,0.55,0.462],"r":1.5873,"img":"img/U2/walk/p021_21_05.jpg","say":"아래 사진이에요. **사그라다 파밀리아** 의 조각이 벽을 빽빽하게 덮고 있어요."},{"b":[0.46,0.95,0.52,0.045],"c":[0.428,0.8844,0.572,0.1156],"r":6.5975,"img":"img/U2/walk/p021_21_06.jpg","say":"캡션이에요. **안토니 가우디**, **사그라다 파밀리아**, 스페인 바르셀로나, 1882-현재."}]}},{"p":22,"title":"안토니 가우디, 카사 엘 카프리초, 꼬미야스, 1885","terms":["안토니 가우디","카사 엘 카프리초","Art Nouveau"],"pass1":[{"kind":"say","lines":["사진 한 장이 쪽을 가득 채워요. 아래 오른쪽에 캡션 한 줄만 있어요.","캡션은 '안토니 가우디, 카사 엘 카프리초, 스페인 꼬미야스, 1885' 예요.","**카사 엘 카프리초** 는 **안토니 가우디** 의 초기 작품이에요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["설계자는 **안토니 가우디**, 건물은 **카사 엘 카프리초**, 스페인 꼬미야스, 1885 예요.","벽이 평평하지 않고 원통 모양으로 둥글게 부풀어 있어요.","벽돌 사이사이에 초록과 붉은 타일 띠가 가로로 여러 줄 둘러져 있어요.","왼쪽에는 굵은 돌기둥 네 개가 받치는 현관이 있어요. 기둥머리에 잎 장식이 있어요.","**안토니 가우디** 가 벽돌과 석재를 쓴다는 설명이 이 사진에 그대로 보여요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**카사 엘 카프리초** 의 나라와 연도는 무엇인가요?","choices":["스페인, 1885","스페인, 1906","프랑스, 1898"],"a":0,"why":"스페인 꼬미야스, 1885 예요. 1906년은 **카사 바트요** 예요."}],"walk":{"head":null,"parts":[{"b":[0.03,0.18,0.93,0.71],"c":[0,0.1445,1,0.781],"r":1.7072,"img":"img/U2/walk/p022_21_01.jpg","say":"사진 전체예요. 원통형으로 부푼 벽과 가로로 두른 타일 띠를 보세요."},{"b":[0.05,0.2,0.3,0.5],"c":[0.035,0.175,0.33,0.55],"r":0.8,"img":"img/U2/walk/p022_21_02.jpg","say":"왼쪽 부분이에요. 굵은 돌기둥이 받치는 현관과 계단이에요."},{"b":[0.36,0.19,0.3,0.3],"c":[0.345,0.174,0.33,0.332],"r":1.3253,"img":"img/U2/walk/p022_21_03.jpg","say":"처마 아래예요. 초록과 붉은 타일이 촘촘하게 줄지어 있어요."},{"b":[0.5,0.91,0.46,0.05],"c":[0.477,0.88,0.506,0.11],"r":6.1333,"img":"img/U2/walk/p022_21_04.jpg","say":"캡션이에요. **안토니 가우디**, **카사 엘 카프리초**, 스페인 꼬미야스, 1885."}]}},{"p":23,"title":"카프리초의 해바라기 타일과 탑 (캡션 없는 쪽)","terms":["안토니 가우디","카사 엘 카프리초","Art Nouveau"],"pass1":[{"kind":"say","lines":["사진 두 장만 있고 글은 한 줄도 없는 쪽이에요.","앞 쪽 **카사 엘 카프리초** 와 같은 벽돌과 같은 타일 띠가 그대로 보여요.","슬라이드가 이름을 적어 주지 않았으니 여기서는 보이는 것만 읽어요."]}],"pass2":[{"kind":"points","head":"이 사진들에서 볼 것","items":["왼쪽은 가까이서 찍은 벽이에요. 계단처럼 한 칸씩 물려 올라간 모서리가 보여요.","그 벽면에 해바라기 한 송이씩 도드라진 네모 타일이 촘촘히 붙어 있어요.","사이사이에 초록 잎 무늬 타일이 섞여 있어 벽 전체가 꽃밭처럼 보여요.","오른쪽은 멀리서 찍은 모습이에요. 타일을 두른 원통형 탑이 지붕 위로 높이 솟아요.","탑 꼭대기에는 금속으로 짠 난간과 색 타일 장식이 얹혀 있어요.","꽃을 타일로 옮긴 이 방식이 **안토니 가우디** 식 **아르 누보(Art Nouveau)** 의 표면 처리예요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.09,0.09,0.36,0.85],"c":[0.072,0.0475,0.396,0.935],"r":0.5647,"img":"img/U2/walk/p023_21_01.jpg","say":"왼쪽 사진이에요. 계단처럼 물린 벽에 해바라기 타일이 한 장씩 붙어 있어요."},{"b":[0.5,0.09,0.42,0.85],"c":[0.479,0.0475,0.462,0.935],"r":0.6588,"img":"img/U2/walk/p023_21_02.jpg","say":"오른쪽 사진이에요. 타일을 두른 원통 탑과 아래 기둥 현관이 함께 보여요."},{"b":[0.5,0.09,0.42,0.25],"c":[0.479,0.074,0.462,0.282],"r":2.1844,"img":"img/U2/walk/p023_21_03.jpg","say":"탑 꼭대기예요. 금속 난간과 색 타일 장식이 얹혀 있어요."}]}},{"p":24,"title":"가구와 실내 사진 (캡션 없는 쪽)","terms":["안토니 가우디","카사 엘 카프리초","Arts and Crafts Movement"],"pass1":[{"kind":"say","lines":["사진 세 장만 있고 글이 없는 쪽이에요. 가구 두 장과 방 한 장이에요.","슬라이드가 작품 이름과 연도를 적어 주지 않았어요.","그래서 이 쪽은 사진에서 보이는 것만 읽고 넘어가요."]}],"pass2":[{"kind":"points","head":"이 사진들에서 볼 것","items":["위 사진은 나무판을 물결 모양으로 깎아 만든 벽걸이예요. 놋쇠 옷걸이가 달려 있어요.","아래 사진은 나무 벤치예요. 등받이와 앉는 면이 모두 둥글게 파여 있어요.","다리도 곧지 않고 바깥으로 휘어져요. 직선이 거의 없어요.","오른쪽 사진은 방 안이에요. 창이 위로 뾰족한 아치 모양이고 천장에 나무 띠가 둘러져요.","건물만이 아니라 가구까지 한 손으로 만드는 태도는 1강 **미술공예운동(Arts and Crafts Movement)** 부터 이어져요.","앞 쪽들과 같은 **카사 엘 카프리초** 이야기 속에 놓인 사진이지만, 캡션이 없으니 이름은 외우지 않아요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.1,0.18,0.4,0.35],"c":[0.08,0.1625,0.44,0.385],"r":1.5238,"img":"img/U2/walk/p024_21_01.jpg","say":"위 사진이에요. 물결 모양으로 깎은 나무판에 옷걸이가 달려 있어요."},{"b":[0.1,0.55,0.4,0.39],"c":[0.08,0.5305,0.44,0.429],"r":1.3675,"img":"img/U2/walk/p024_21_02.jpg","say":"아래 사진이에요. 등받이와 앉는 면이 곡선인 나무 벤치예요."},{"b":[0.52,0.06,0.45,0.89],"c":[0.4975,0.0155,0.495,0.979],"r":0.6742,"img":"img/U2/walk/p024_21_03.jpg","say":"오른쪽 사진이에요. 뾰족한 아치 창이 있는 방과 나무 의자들이에요."}]}},{"p":25,"title":"사그라다 파밀리아: 고딕 양식 + 아르누보 양식","terms":["안토니 가우디","사그라다 파밀리아","고딕 리바이벌","Art Nouveau"],"pass1":[{"kind":"say","lines":["제목 한 줄과 사진 두 장이에요. 왼쪽은 천장, 오른쪽은 바깥에서 본 첨탑이에요.","제목이 답을 바로 알려 줘요. **사그라다 파밀리아** 는 고딕 양식과 **아르 누보(Art Nouveau)** 의 결합이에요.","캡션은 '안토니 가우디, 사그라다 파밀리아, 스페인 바르셀로나, 1882-현재' 예요."]},{"kind":"analogy","head":"숲이 된 성당","scene":"높은 나무들이 위에서 가지를 뻗어 지붕을 만드는 숲이에요.","map":[["나무 줄기","기울어져 선 기둥"],["갈라지는 가지","위에서 갈라져 천장을 받치는 부분"],["잎 사이 햇빛","색유리를 통과해 들어오는 빛"]]}],"pass2":[{"kind":"points","head":"**사그라다 파밀리아** 의 기본 사실","items":["**안토니 가우디**, 스페인 바르셀로나, 1882년부터 현재까지 짓고 있어요.","고딕 양식과 **아르 누보(Art Nouveau)** 양식의 결합이라고 슬라이드가 적어 놓았어요.","고딕에서 온 것은 높이 솟는 첨탑과 수직으로 뻗는 느낌이에요.","**아르 누보(Art Nouveau)** 에서 온 것은 자연을 닮은 곡선과 빽빽한 장식이에요.","기둥이 위로 갈수록 갈라져서 나무처럼 천장을 받치는 것이 가장 큰 특징이에요."]},{"kind":"look","walked":1},{"kind":"bg","src":"기초 다지기: 고딕이 왜 또 나오나요","lines":["1강에서 옛 고딕을 다시 쓰자는 **고딕 리바이벌** 을 봤어요. 퓨진과 러스킨의 이야기예요.","**고딕 리바이벌** 은 옛 고딕을 그대로 흉내 내지만, 가우디는 고딕의 수직성만 가져와 새 곡선과 섞어요.","그래서 **사그라다 파밀리아** 는 **고딕 리바이벌** 이 아니라 고딕과 **아르 누보(Art Nouveau)** 의 결합이라고 불러요."]}],"pass3":[{"kind":"check","q":"**사그라다 파밀리아** 는 어떤 두 양식의 결합이라고 슬라이드가 말하나요?","choices":["고딕 양식과 **아르 누보(Art Nouveau)** 양식","르네상스와 바로크","**아르데코** 와 국제주의 양식"],"a":0,"why":"제목 줄에 고딕 양식+아르누보 양식이라고 그대로 적혀 있어요."},{"kind":"english","head":"논술 답안: 사그라다 파밀리아","en":"사그라다 파밀리아는 안토니 가우디가 1882년부터 스페인 바르셀로나에 짓기 시작하여 현재까지 건설 중인 성당으로 고딕 양식과 아르 누보 양식이 결합된 작품이다.","ko":"설계자, 도시, 1882-현재, 고딕과 아르 누보의 결합이 채점 항목이에요.","tip":"1882 는 아직도 짓는 중이라는 말과 함께 외워요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.05,0.45,0.05],"c":[0.0275,0.02,0.495,0.11],"r":6.0,"img":"img/U2/walk/p025_21_01.jpg","say":"제목이에요. 사그라다 파밀리아, 고딕 양식+아르누보 양식."},{"b":[0.05,0.12,0.4,0.77],"c":[0.03,0.0815,0.44,0.847],"r":0.6926,"img":"img/U2/walk/p025_21_02.jpg","say":"왼쪽 사진이에요. 기둥이 위에서 갈라져 별 모양 천장을 받쳐요."},{"b":[0.49,0.12,0.43,0.77],"c":[0.4685,0.0815,0.473,0.847],"r":0.7446,"img":"img/U2/walk/p025_21_03.jpg","say":"오른쪽 사진이에요. 옥수수처럼 오돌토돌한 첨탑이 솟고 크레인이 함께 보여요."},{"b":[0.42,0.91,0.56,0.07],"c":[0.384,0.8755,0.616,0.1245],"r":6.5971,"img":"img/U2/walk/p025_21_04.jpg","say":"캡션이에요. **안토니 가우디**, **사그라다 파밀리아**, 스페인 바르셀로나, 1882-현재."}]}},{"p":26,"title":"사그라다 파밀리아 내부 (캡션 없는 쪽)","terms":["사그라다 파밀리아","안토니 가우디","Art Nouveau"],"pass1":[{"kind":"say","lines":["사진 두 장만 있고 글이 한 줄도 없는 쪽이에요.","앞뒤 쪽과 같은 **사그라다 파밀리아** 내부 사진이지만 캡션은 붙어 있지 않아요.","그러니 이름을 외우기보다 눈으로 특징을 익히는 쪽으로 써요."]}],"pass2":[{"kind":"points","head":"이 사진들에서 볼 것","items":["왼쪽은 벽과 천장이 색색으로 물든 모습이에요. 왼쪽은 노랑, 오른쪽은 파랑이에요.","색유리를 지나온 빛이 돌 표면에 그대로 물드는 것이에요. 색을 칠한 것이 아니에요.","벽면은 종이를 접은 것처럼 여러 각으로 꺾여 있어요. 평평한 면이 거의 없어요.","오른쪽은 올려다본 천장이에요. 흰 기둥이 위에서 여러 갈래로 갈라져요.","갈라진 끝이 별 모양으로 모여 천장을 만들어요. 나무 숲을 닮은 구조예요.","**안토니 가우디** 가 말한 흐르는 3차원 곡선이 이 사진에서 가장 잘 보여요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.01,0.05,0.48,0.88],"c":[0,0.006,0.528,0.968],"r":0.7273,"img":"img/U2/walk/p026_21_01.jpg","say":"왼쪽 사진이에요. 색유리를 통과한 빛이 벽을 노랑과 파랑으로 물들여요."},{"b":[0.5,0.05,0.48,0.88],"c":[0.472,0.006,0.528,0.968],"r":0.7273,"img":"img/U2/walk/p026_21_02.jpg","say":"오른쪽 사진이에요. 흰 기둥이 위에서 가지처럼 갈라져 천장을 받쳐요."}]}},{"p":27,"title":"사그라다 파밀리아 전경과 본당","terms":["사그라다 파밀리아","안토니 가우디","고딕 리바이벌"],"pass1":[{"kind":"say","lines":["사진 세 장이 있는 쪽이에요. 전경, 올려다본 천장, 본당 내부예요.","캡션은 '안토니 가우디, 사그라다 파밀리아, 스페인 바르셀로나, 1882-현재' 예요.","밖에서는 고딕처럼 솟고, 안에서는 숲처럼 갈라져요."]}],"pass2":[{"kind":"points","head":"이 사진들에서 볼 것","items":["위 왼쪽은 멀리서 본 전경이에요. 뾰족탑 네 개가 나란히 솟아 있어요.","탑이 높이 솟는 모습은 고딕에서 왔어요. 1강 **고딕 리바이벌** 에서 본 수직성과 같은 뿌리예요.","아래 왼쪽은 올려다본 천장이에요. 양옆에 둥근 장미창이 보여요.","오른쪽은 본당 안이에요. 나무 같은 기둥이 줄지어 서고 양옆 벽이 색유리로 채워져 있어요.","바닥에서 천장까지 기둥이 한 번도 끊기지 않고 이어져요.","**안토니 가우디** 의 **사그라다 파밀리아** 는 1882년부터 지금까지 짓고 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**사그라다 파밀리아** 의 착공 연도는 언제인가요?","choices":["1882","1906","1914"],"a":0,"why":"1882년부터 현재까지 짓고 있어요. 1906년은 **카사 바트요** 예요."}],"walk":{"head":null,"parts":[{"b":[0.01,0.09,0.51,0.43],"c":[0,0.0685,0.561,0.473],"r":1.5814,"img":"img/U2/walk/p027_21_01.jpg","say":"위 왼쪽 사진이에요. 멀리서 본 전경, 뾰족탑 네 개가 솟아 있어요."},{"b":[0.01,0.53,0.51,0.4],"c":[0,0.51,0.561,0.44],"r":1.7,"img":"img/U2/walk/p027_21_02.jpg","say":"아래 왼쪽 사진이에요. 올려다본 천장과 양옆의 둥근 장미창이에요."},{"b":[0.53,0.02,0.45,0.69],"c":[0.505,0,0.495,0.759],"r":0.8696,"img":"img/U2/walk/p027_21_03.jpg","say":"오른쪽 사진이에요. 본당 안. 나무 같은 기둥과 색유리 창이 이어져요."},{"b":[0.53,0.86,0.44,0.07],"c":[0.508,0.84,0.484,0.11],"r":5.8667,"img":"img/U2/walk/p027_21_04.jpg","say":"캡션이에요. **사그라다 파밀리아**, 스페인 바르셀로나, 1882-현재."}]}},{"p":28,"title":"안토니 가우디, 구엘 공원, 바르셀로나, 1914","terms":["안토니 가우디","구엘 공원","Art Nouveau"],"pass1":[{"kind":"say","lines":["사진 네 장이 있는 쪽이에요. 벤치, 계단, 벤치 등받이, 도마뱀 분수예요.","캡션은 '안토니 가우디, 구엘 공원, 스페인 바르셀로나, 1914' 예요.","**구엘 공원** 은 깨진 타일 조각을 붙여 표면을 덮은 공원이에요."]},{"kind":"analogy","head":"깨진 접시로 만든 모자이크","scene":"깨진 그릇 조각을 모아 벽에 붙여 무늬를 만드는 일이에요.","map":[["깨진 조각","색색의 타일 파편"],["붙인 자리","벤치와 계단, 분수의 표면"],["완성된 무늬","표면 전체를 덮는 **아르 누보(Art Nouveau)** 식 장식"]]}],"pass2":[{"kind":"points","head":"이 사진들에서 볼 것","items":["설계자는 **안토니 가우디**, 장소는 **구엘 공원**, 스페인 바르셀로나, 1914 예요.","위 왼쪽은 벤치예요. 등받이가 뱀처럼 굽이치고 깨진 타일이 표면을 다 덮어요.","아래 왼쪽은 두 갈래 계단이에요. 가운데에 물길과 장식이 놓여 있어요.","오른쪽 위는 벤치 등받이를 가까이 찍은 것이에요. 부채 모양 무늬가 붙어 있어요.","오른쪽 아래는 타일로 덮인 도마뱀 분수예요. **구엘 공원** 에서 가장 유명한 장면이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**구엘 공원** 의 연도는 언제인가요?","choices":["1885","1898","1914"],"a":2,"why":"1914년이에요. 1885년은 **카사 엘 카프리초** 예요."}],"walk":{"head":null,"parts":[{"b":[0.03,0.02,0.46,0.42],"c":[0.007,0,0.506,0.462],"r":1.4603,"img":"img/U2/walk/p028_21_01.jpg","say":"위 왼쪽 사진이에요. 굽이치는 벤치를 깨진 타일 조각이 덮고 있어요."},{"b":[0.03,0.46,0.46,0.4],"c":[0.007,0.44,0.506,0.44],"r":1.5333,"img":"img/U2/walk/p028_21_02.jpg","say":"아래 왼쪽 사진이에요. 두 갈래로 갈라지는 계단과 가운데 물길이에요."},{"b":[0.56,0.18,0.33,0.31],"c":[0.5435,0.164,0.363,0.342],"r":1.4152,"img":"img/U2/walk/p028_21_03.jpg","say":"오른쪽 위 사진이에요. 벤치 등받이의 부채 모양 타일 무늬예요."},{"b":[0.56,0.51,0.33,0.35],"c":[0.5435,0.4925,0.363,0.385],"r":1.2571,"img":"img/U2/walk/p028_21_04.jpg","say":"오른쪽 아래 사진이에요. 타일로 덮인 도마뱀 분수예요."},{"b":[0.52,0.87,0.42,0.05],"c":[0.499,0.84,0.462,0.11],"r":5.6,"img":"img/U2/walk/p028_21_05.jpg","say":"캡션이에요. **안토니 가우디**, **구엘 공원**, 스페인 바르셀로나, 1914."}]}},{"p":29,"title":"구엘 공원의 기둥 홀과 도마뱀 분수","terms":["구엘 공원","안토니 가우디","Art Nouveau"],"pass1":[{"kind":"say","lines":["사진 두 장뿐인 쪽이에요. 왼쪽은 기둥이 늘어선 홀, 오른쪽은 계단과 분수예요.","캡션은 '안토니 가우디, 구엘 공원, 스페인 바르셀로나, 1914' 예요.","위층 광장을 아래에서 굵은 기둥들이 떠받치고 있어요."]}],"pass2":[{"kind":"points","head":"이 사진들에서 볼 것","items":["왼쪽은 **구엘 공원** 의 기둥 홀이에요. 굵은 돌기둥이 줄지어 서 있어요.","천장은 평평하지 않고 둥글게 부풀어 있어요. 거기에 둥근 모자이크 장식이 박혀 있어요.","기둥과 천장 표면도 작은 타일 조각으로 덮여 있어요.","오른쪽은 계단 쪽이에요. 위층에 기둥이 늘어선 모습과 아래 도마뱀 분수가 한 장면에 담겼어요.","**안토니 가우디** 는 벽돌과 석재를 쓰고 그 위를 타일로 덮는 방식을 즐겨 썼어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**구엘 공원** 의 표면을 덮은 재료는 무엇인가요?","choices":["깨뜨린 타일 조각","매끄럽게 간 대리석","노출 콘크리트"],"a":0,"why":"**안토니 가우디** 는 벽돌과 석재 위를 색색의 타일 조각으로 덮었어요."}],"walk":{"head":null,"parts":[{"b":[0.01,0.04,0.48,0.89],"c":[0,0,0.528,0.979],"r":0.7191,"img":"img/U2/walk/p029_21_01.jpg","say":"왼쪽 사진이에요. 굵은 기둥이 늘어선 홀과 천장의 둥근 모자이크예요."},{"b":[0.51,0.04,0.46,0.89],"c":[0.487,0,0.506,0.979],"r":0.6891,"img":"img/U2/walk/p029_21_02.jpg","say":"오른쪽 사진이에요. 위층 기둥과 아래 타일 도마뱀 분수가 같이 보여요."},{"b":[0.55,0.94,0.43,0.05],"c":[0.527,0.89,0.473,0.11],"r":5.7333,"img":"img/U2/walk/p029_21_03.jpg","say":"캡션이에요. **안토니 가우디**, **구엘 공원**, 스페인 바르셀로나, 1914."}]}},{"p":30,"title":"까사 바트요(Casa Batllo), 바르셀로나, 1906","terms":["안토니 가우디","카사 바트요","Art Nouveau"],"pass1":[{"kind":"say","lines":["제목 한 줄과 사진 두 장이에요. 왼쪽은 지붕, 오른쪽은 길에서 본 정면이에요.","캡션은 '안토니 가우디, 카사 바트요, 스페인 바르셀로나, 1906' 이에요.","**카사 바트요** 는 겉이 뼈와 비늘처럼 생긴 집이에요."]},{"kind":"analogy","head":"용의 등을 얹은 집","scene":"지붕이 물고기 비늘 같고 벽이 뼈처럼 생긴 모습이에요.","map":[["비늘 지붕","색 타일을 겹쳐 덮은 곡면 지붕"],["뼈 같은 기둥","1층과 2층의 굵은 돌기둥"],["눈처럼 뚫린 구멍","물결치는 발코니 난간"]]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["설계자는 **안토니 가우디**, 건물은 **카사 바트요**, 스페인 바르셀로나, 1906 이에요.","왼쪽 사진은 지붕이에요. 굽이치는 등줄기에 구슬 같은 타일이 줄지어 박혀 있어요.","지붕면은 물고기 비늘처럼 생긴 타일이 겹쳐 덮고 있어요.","가운데 굴뚝은 마늘 모양으로 부풀고 꼭대기에 꽃 같은 장식이 얹혀 있어요.","오른쪽 사진은 정면이에요. 벽면 전체가 반짝이는 색 타일 조각으로 덮여 있어요.","아래쪽 기둥은 뼈처럼 마디가 있고, 발코니 난간은 가면처럼 구멍이 뚫려 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**카사 바트요** 의 도시와 연도는 무엇인가요?","choices":["바르셀로나, 1906","꼬미야스, 1885","바르셀로나, 1914"],"a":0,"why":"1885년은 **카사 엘 카프리초**, 1914년은 **구엘 공원** 이에요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.04,0.25,0.05],"c":[0.0375,0.01,0.275,0.11],"r":3.3333,"img":"img/U2/walk/p030_21_01.jpg","say":"제목이에요. 까사 바트요(Casa Batllo)."},{"b":[0.08,0.13,0.4,0.78],"c":[0.06,0.091,0.44,0.858],"r":0.6838,"img":"img/U2/walk/p030_21_02.jpg","say":"왼쪽 사진이에요. 비늘 같은 지붕과 구슬 박힌 등줄기, 마늘 모양 굴뚝이에요."},{"b":[0.51,0.13,0.41,0.78],"c":[0.4895,0.091,0.451,0.858],"r":0.7009,"img":"img/U2/walk/p030_21_03.jpg","say":"오른쪽 사진이에요. 뼈처럼 생긴 기둥과 물결치는 발코니를 보세요."},{"b":[0.55,0.95,0.43,0.045],"c":[0.527,0.89,0.473,0.11],"r":5.7333,"img":"img/U2/walk/p030_21_04.jpg","say":"캡션이에요. **안토니 가우디**, **카사 바트요**, 스페인 바르셀로나, 1906."}]}},{"p":31,"title":"카사 바트요의 중앙 코트와 구부러진 벽","terms":["카사 바트요","안토니 가우디","Art Nouveau"],"pass1":[{"kind":"say","lines":["글 한 줄, 사진 두 장, 평면도 한 장이 있는 쪽이에요.","글은 '계단과 엘리베이터가 있는 중앙 코트가 있고, 많은 방들이 구부러진 벽에 의해 만들어진 형태' 예요.","**카사 바트요** 에서 시험에 가장 많이 나오는 문장이 바로 이 한 줄이에요."]},{"kind":"analogy","head":"가운데가 뚫린 집","scene":"집 한가운데를 위아래로 뚫어 빛이 떨어지게 만든 통로예요.","map":[["뚫린 통로","중앙 코트"],["통로에 넣은 것","계단과 엘리베이터"],["통로 둘레의 방","구부러진 벽이 만든 방들"]]}],"pass2":[{"kind":"points","head":"**카사 바트요**(1906)의 평면과 공간","items":["계단과 엘리베이터가 있는 중앙 코트가 있어요. 집 가운데가 위아래로 뚫려 있어요.","많은 방들이 구부러진 벽에 의해 만들어진 형태예요. 벽이 곧은 자가 아니라 곡선이에요.","평면도를 보면 방 경계선이 물결처럼 휘어 있어요. 직각으로 만나는 구석이 거의 없어요.","중앙 코트의 벽은 파란 타일로 덮여 있어요. 위로 갈수록 색이 진해져요.","**안토니 가우디** 의 곡선은 겉모습만이 아니라 평면에도 들어가 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**카사 바트요** 의 평면 특징으로 옳은 것은 무엇인가요?","choices":["계단과 엘리베이터가 있는 중앙 코트, 구부러진 벽이 만든 방들","주요부와 서비스 윙이 직각 배치","정사각형 격자 파사드"],"a":0,"why":"주요부와 서비스 윙의 직각 배치는 **힐하우스** 의 특징이에요."},{"kind":"english","head":"논술 답안: 카사 바트요","en":"카사 바트요는 1906년 안토니 가우디가 스페인 바르셀로나에 지은 작품으로 계단과 엘리베이터가 있는 중앙 코트를 두고 많은 방들이 구부러진 벽에 의해 만들어진 형태를 가진다.","ko":"설계자, 도시, 연도, 중앙 코트, 구부러진 벽 다섯 가지를 넣어요.","tip":"중앙 코트와 구부러진 벽 두 마디만 붙잡으면 돼요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.04,0.9,0.12],"c":[0.005,0,0.99,0.2],"r":6.6,"img":"img/U2/walk/p031_21_01.jpg","say":"맨 위 글이에요. 중앙 코트와 구부러진 벽이 만든 방들."},{"b":[0.06,0.27,0.37,0.63],"c":[0.0415,0.2385,0.407,0.693],"r":0.7831,"img":"img/U2/walk/p031_21_02.jpg","say":"왼쪽 사진이에요. 뼈 모양 기둥과 가면 같은 발코니를 가까이서 찍었어요."},{"b":[0.46,0.12,0.52,0.29],"c":[0.428,0.104,0.572,0.322],"r":2.3685,"img":"img/U2/walk/p031_21_03.jpg","say":"평면도예요. 방 경계선이 곧지 않고 구불구불하게 휘어 있어요."},{"b":[0.46,0.44,0.52,0.47],"c":[0.428,0.4165,0.572,0.517],"r":1.4752,"img":"img/U2/walk/p031_21_04.jpg","say":"오른쪽 아래 사진이에요. 파란 타일로 덮인 중앙 코트를 올려다본 모습이에요."},{"b":[0.55,0.95,0.43,0.045],"c":[0.527,0.89,0.473,0.11],"r":5.7333,"img":"img/U2/walk/p031_21_05.jpg","say":"캡션이에요. **안토니 가우디**, **카사 바트요**, 스페인 바르셀로나, 1906."}]}},{"p":32,"title":"까사 바트요 실내","terms":["카사 바트요","안토니 가우디","Art Nouveau"],"pass1":[{"kind":"say","lines":["사진 세 장과 '까사 바트요 실내' 라는 글 한 줄만 있는 쪽이에요.","벽, 천장, 문틀까지 곧은 선이 거의 없어요.","**카사 바트요** 의 구부러진 벽이 실내에서 어떤 느낌인지 보여 주는 쪽이에요."]}],"pass2":[{"kind":"points","head":"이 사진들에서 볼 것","items":["위 사진은 벽난로가 있는 방이에요. 벽이 움푹 파이고 그 안에 앉는 자리가 들어가 있어요.","벽과 천장이 만나는 부분이 둥글게 말려 있어요. 모서리가 없어요.","아래 왼쪽 사진은 문들이 늘어선 복도예요. 문틀이 물결처럼 휘고 둥근 유리가 박혀 있어요.","아래 가운데 사진은 문 하나를 가까이 찍은 것이에요. 파란 색유리가 꽃처럼 들어가 있어요.","오른쪽 벽에는 눈 모양으로 생긴 곡선 창이 뚫려 있어요.","**안토니 가우디** 는 이렇게 문과 가구까지 같은 곡선 어휘로 맞추었어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**카사 바트요** 실내에서 공통으로 보이는 특징은 무엇인가요?","choices":["곧은 모서리 없이 둥글게 이어지는 벽과 문틀","정사각형 격자로 나뉜 벽","번개와 지그재그 무늬"],"a":0,"why":"구부러진 벽이 방을 만든다는 설명이 실내 사진에서 그대로 확인돼요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**안토니 가우디** 의 곡선은 3차원이에요. 벽 자체가 휘어요.","**아르 누보(Art Nouveau)** 의 다른 작가들은 주로 평평한 면 위에 곡선 무늬를 그려요."]}],"walk":{"head":null,"parts":[{"b":[0.48,0.02,0.48,0.36],"c":[0.456,0.002,0.528,0.396],"r":1.7778,"img":"img/U2/walk/p032_21_01.jpg","say":"위 사진이에요. 벽난로가 벽에 파묻힌 방, 벽과 천장이 둥글게 이어져요."},{"b":[0.01,0.39,0.34,0.55],"c":[0,0.3625,0.374,0.605],"r":0.8242,"img":"img/U2/walk/p032_21_02.jpg","say":"아래 왼쪽 사진이에요. 물결치는 문틀과 둥근 유리가 박힌 문들이에요."},{"b":[0.36,0.4,0.35,0.54],"c":[0.3425,0.373,0.385,0.594],"r":0.8642,"img":"img/U2/walk/p032_21_03.jpg","say":"아래 가운데 사진이에요. 파란 색유리가 든 곡선 문과 눈 모양 창이에요."},{"b":[0.78,0.95,0.2,0.045],"c":[0.768,0.89,0.224,0.11],"r":2.7152,"img":"img/U2/walk/p032_21_04.jpg","say":"글 한 줄이에요. 까사 바트요 실내."}]}},{"p":33,"title":"까사 밀라(Casa Mila), 바르셀로나, 1912","terms":["안토니 가우디","카사 밀라","카사 바트요","Art Nouveau"],"pass1":[{"kind":"say","lines":["제목 한 줄, 사진 한 장, 평면도 한 장, 모형 사진 한 장이 있는 쪽이에요.","캡션은 '안토니 가우디, 카사 밀라, 스페인 바르셀로나, 1912' 예요.","**카사 밀라** 는 돌벽 전체가 파도처럼 굽이치는 공동주택이에요."]},{"kind":"analogy","head":"돌로 만든 파도","scene":"바닷가 바위가 파도에 깎여 층층이 물결치는 모습이에요.","map":[["물결치는 바위층","층마다 굽이치는 돌 외벽"],["바위에 붙은 해초","검은 철제 발코니 난간"],["바위에 뚫린 구멍","평면에 뚫린 두 개의 중정"]]}],"pass2":[{"kind":"points","head":"**카사 밀라**(1912)에서 볼 것","items":["설계자는 **안토니 가우디**, 스페인 바르셀로나, 1912 예요.","외벽이 층마다 파도처럼 굽이쳐요. 곧은 수평선이 한 줄도 없어요.","발코니 난간은 검은 철을 엉킨 해초처럼 구부려 만들었어요.","평면도를 보면 둥근 중정 구멍이 두 개 뚫려 있어요. 방들이 그 둘레를 감싸요.","모형 사진을 보면 건물 전체가 한 덩어리 바위처럼 보여요."]},{"kind":"compare","head":"가우디의 두 공동주택","cols":["**카사 바트요**","**카사 밀라**"],"rows":[["1906년","1912년"],["색 타일로 덮인 표면, 뼈 모양 기둥","색을 쓰지 않은 돌 표면, 물결치는 벽"],["중앙 코트 하나","둥근 중정 두 개"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**카사 밀라** 의 연도는 언제인가요?","choices":["1906","1912","1914"],"a":1,"why":"1906년은 **카사 바트요**, 1914년은 구엘 공원이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**카사 바트요** 는 색 타일이 반짝이고, **카사 밀라** 는 색 없는 돌 표면이에요.","둘 다 바르셀로나이고 둘 다 **안토니 가우디** 라서 연도로 구별해야 해요."]}],"walk":{"head":null,"parts":[{"b":[0.08,0.04,0.2,0.05],"c":[0.068,0.01,0.224,0.11],"r":2.7152,"img":"img/U2/walk/p033_22_01.jpg","say":"제목이에요. 까사 밀라(Casa Mila)."},{"b":[0.11,0.09,0.42,0.81],"c":[0.089,0.0495,0.462,0.891],"r":0.6914,"img":"img/U2/walk/p033_22_02.jpg","say":"왼쪽 사진이에요. 물결치는 돌 외벽과 검은 철제 발코니를 보세요."},{"b":[0.53,0.02,0.45,0.32],"c":[0.505,0.004,0.495,0.352],"r":1.875,"img":"img/U2/walk/p033_22_03.jpg","say":"오른쪽 위 평면도예요. 흰 구멍 두 개가 중정이에요."},{"b":[0.52,0.37,0.41,0.53],"c":[0.4995,0.3435,0.451,0.583],"r":1.0314,"img":"img/U2/walk/p033_22_04.jpg","say":"오른쪽 아래 모형이에요. 층마다 벽이 파도치듯 앞뒤로 움직여요."},{"b":[0.55,0.95,0.43,0.045],"c":[0.527,0.89,0.473,0.11],"r":5.7333,"img":"img/U2/walk/p033_22_05.jpg","say":"캡션이에요. **안토니 가우디**, **카사 밀라**, 스페인 바르셀로나, 1912."}]}},{"p":34,"title":"카사 밀라의 중정과 옥상","terms":["카사 밀라","안토니 가우디","카사 바트요"],"pass1":[{"kind":"say","lines":["사진 두 장뿐인 쪽이에요. 왼쪽은 중정을 올려다본 모습, 오른쪽은 옥상 쪽이에요.","캡션은 '안토니 가우디, 카사 밀라, 스페인 바르셀로나, 1912' 예요.","**카사 밀라** 의 곡선이 안쪽과 지붕에서도 그대로 이어져요."]}],"pass2":[{"kind":"points","head":"이 사진들에서 볼 것","items":["왼쪽은 중정을 아래에서 올려다본 모습이에요. 층마다 창과 발코니가 둥글게 휘어요.","중정 벽에 옅은 색 무늬가 칠해져 있고 가운데로 하늘이 열려 있어요.","오른쪽은 옥상 가까이 찍은 사진이에요. 처마 선이 파도처럼 오르내려요.","옥상 위에는 투구를 쓴 사람처럼 생긴 굴뚝이 서 있어요.","벽에 난 창 아래로 검은 철제 장식이 엉킨 덩굴처럼 붙어 있어요.","**안토니 가우디** 는 **카사 바트요** 에서처럼 여기서도 굴뚝까지 조각으로 다뤘어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**카사 밀라** 의 옥상에서 조각처럼 다뤄진 요소는 무엇인가요?","choices":["굴뚝","엘리베이터 기계실","물탱크"],"a":0,"why":"투구를 쓴 사람처럼 생긴 굴뚝이 옥상에 줄지어 서 있어요."}],"walk":{"head":null,"parts":[{"b":[0.03,0.05,0.45,0.81],"c":[0.0075,0.0095,0.495,0.891],"r":0.7407,"img":"img/U2/walk/p034_21_01.jpg","say":"왼쪽 사진이에요. 중정을 올려다본 모습, 층마다 곡선 발코니가 돌아가요."},{"b":[0.51,0.05,0.46,0.81],"c":[0.487,0.0095,0.506,0.891],"r":0.7572,"img":"img/U2/walk/p034_21_02.jpg","say":"오른쪽 사진이에요. 물결치는 처마와 투구 모양 굴뚝을 보세요."},{"b":[0.55,0.93,0.43,0.05],"c":[0.527,0.89,0.473,0.11],"r":5.7333,"img":"img/U2/walk/p034_21_03.jpg","say":"캡션이에요. **안토니 가우디**, **카사 밀라**, 스페인 바르셀로나, 1912."}]}},{"p":35,"title":"독일의 유겐트슈틸","terms":["Jugendstil","Art Nouveau","페터 베렌스","아르데코"],"pass1":[{"kind":"say","lines":["항목 세 줄과 그림 두 장이 있는 쪽이에요. 왼쪽은 그래픽, 오른쪽은 전시 포스터예요.","**유겐트슈틸(Jugendstil)** 은 독일어로 젊은 양식이라는 뜻이에요.","1896년 같은 이름의 잡지가 나오면서 새 예술운동이 싹텄어요."]},{"kind":"analogy","head":"번역된 이름","scene":"같은 책을 나라마다 다른 제목으로 내는 일과 비슷해요.","map":[["원래 제목","**아르 누보(Art Nouveau)**, 새로운 미술"],["독일어 제목","**유겐트슈틸(Jugendstil)**, 젊은 양식"],["번역하며 바뀐 내용","곡선을 기하학으로 정리한 독일만의 노선"]]}],"pass2":[{"kind":"points","head":"**유겐트슈틸(Jugendstil)** 의 기본 사실","items":["독일에서는 같은 시기 1896년에 유겐트슈틸이라는 이름의 잡지 발간과 함께 새 예술운동이 싹텄어요.","**유겐트슈틸(Jugendstil)** 은 **아르 누보(Art Nouveau)** 를 독일어로 직역한 용어이고 그 영향을 받았어요.","하지만 프랑스나 벨기에의 **아르 누보(Art Nouveau)** 와는 결이 다른 노선을 취했어요.","20세기 이후 독일만의 양식으로 자리 잡았어요.","첫 사례는 **페터 베렌스** 가 1898년에 디자인한 유겐트슈틸 그래픽디자인이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**유겐트슈틸(Jugendstil)** 의 뜻은 무엇인가요?","choices":["젊은 양식","새로운 미술","분리"],"a":0,"why":"새로운 미술은 **아르 누보(Art Nouveau)**, 분리는 제체시온의 뜻이에요."},{"kind":"check","q":"**유겐트슈틸(Jugendstil)** 잡지가 창간된 해는 언제인가요?","choices":["1890","1896","1901"],"a":1,"why":"1896년이에요. 첫 사례는 **페터 베렌스** 의 1898년 그래픽디자인이에요."},{"kind":"english","head":"논술 답안: 독일의 유겐트슈틸","en":"유겐트슈틸은 1896년 같은 이름의 잡지 발간과 함께 시작된 독일의 새 예술운동으로 아르 누보를 독일어로 직역한 용어이며, 프랑스나 벨기에의 아르 누보와는 결이 다른 노선을 취하여 20세기 이후 독일만의 양식으로 자리 잡았다.","ko":"1896년 잡지, 직역된 이름, 다른 노선, 독일만의 양식이 채점 항목이에요.","tip":"잡지 이름이 곧 양식 이름이라고 외워요. 뒤에 나올 **아르데코** 와도 헷갈리지 않아요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.04,0.28,0.05],"c":[0.026,0.01,0.308,0.11],"r":3.7333,"img":"img/U2/walk/p035_21_01.jpg","say":"제목이에요. 독일의 유겐트슈틸."},{"b":[0.05,0.11,0.92,0.13],"c":[0,0.0728,1,0.2045],"r":6.52,"img":"img/U2/walk/p035_21_02.jpg","say":"첫 항목이에요. 1896년 잡지 발간과 함께 새 예술운동이 싹텄어요."},{"b":[0.05,0.23,0.9,0.06],"c":[0.005,0.16,0.99,0.2],"r":6.6,"img":"img/U2/walk/p035_21_03.jpg","say":"둘째 항목이에요. 아르 누보를 독일어로 직역한 용어예요."},{"b":[0.05,0.3,0.92,0.1],"c":[0,0.2478,1,0.2045],"r":6.52,"img":"img/U2/walk/p035_21_04.jpg","say":"셋째 항목이에요. 프랑스, 벨기에와 결이 다르고 20세기에 독일만의 양식이 돼요."},{"b":[0.06,0.39,0.55,0.53],"c":[0.0325,0.3635,0.605,0.583],"r":1.3836,"img":"img/U2/walk/p035_21_05.jpg","say":"그림 두 장이에요. 왼쪽은 머리카락이 소용돌이처럼 얽힌 그래픽, 오른쪽은 DARMSTADT 1901 전시 포스터예요."},{"b":[0.14,0.93,0.49,0.06],"c":[0.1155,0.89,0.539,0.11],"r":6.5333,"img":"img/U2/walk/p035_21_06.jpg","say":"캡션이에요. **페터 베렌스** 가 1898년 디자인한 유겐트슈틸 그래픽디자인."}]}},{"p":36,"title":"마틸덴회헤, 독일 다름슈타트, 1901","terms":["마틸덴회헤","Jugendstil","요제프 마리아 올브리히"],"pass1":[{"kind":"say","lines":["사진 한 장이 쪽을 가득 채우고 아래에 캡션 한 줄이 있어요.","캡션은 '마틸넨회헤, 독일 다름슈타트, 1901' 이에요.","**마틸덴회헤** 는 **유겐트슈틸(Jugendstil)** 이 펼쳐진 무대예요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["**마틸덴회헤** 는 독일 다름슈타트에 있는 장소이고 연도는 1901 이에요.","왼쪽에 붉은 벽돌 탑이 서 있어요. 꼭대기가 손가락 다섯처럼 둥글게 솟아 있어요.","탑 윗부분은 초록색 지붕이라 벽돌의 붉은색과 크게 대비돼요.","오른쪽에는 금빛 양파 모양 지붕을 얹은 예배당이 함께 서 있어요.","**요제프 마리아 올브리히** 가 이곳의 주요 건물들을 지었고 다음 쪽에서 이어서 봐요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**마틸덴회헤** 가 있는 도시와 연도는 무엇인가요?","choices":["독일 다름슈타트, 1901","오스트리아 빈, 1898","영국 글래스고, 1899"],"a":0,"why":"**유겐트슈틸(Jugendstil)** 의 무대가 된 독일 다름슈타트의 장소예요."}],"walk":{"head":null,"parts":[{"b":[0.03,0.02,0.93,0.92],"c":[0,0,1,1],"r":1.3333,"img":"img/U2/walk/p036_21_01.jpg","say":"사진 전체예요. 언덕 위에 여러 건물이 모여 있는 **마틸덴회헤** 예요."},{"b":[0.12,0.18,0.14,0.5],"c":[0.0831,0.155,0.2139,0.55],"r":0.5185,"img":"img/U2/walk/p036_21_02.jpg","say":"왼쪽 벽돌 탑이에요. 꼭대기가 손가락 다섯처럼 둥글게 솟아 있어요."},{"b":[0.5,0.13,0.3,0.55],"c":[0.485,0.1025,0.33,0.605],"r":0.7273,"img":"img/U2/walk/p036_21_03.jpg","say":"오른쪽이에요. 금빛 양파 지붕을 얹은 예배당이에요."},{"b":[0.55,0.95,0.42,0.04],"c":[0.529,0.89,0.462,0.11],"r":5.6,"img":"img/U2/walk/p036_21_04.jpg","say":"캡션이에요. 마틸넨회헤, 독일 다름슈타트, 1901."}]}},{"p":37,"title":"올브리히, 예술가회관(1901)과 결혼기념탑(1905)","terms":["요제프 마리아 올브리히","예술가회관","결혼기념탑","마틸덴회헤"],"pass1":[{"kind":"say","lines":["사진 두 장과 캡션 두 줄이 있는 쪽이에요.","왼쪽은 **결혼기념탑**(1905), 오른쪽은 **예술가회관**(1901)이에요.","둘 다 **요제프 마리아 올브리히** 가 독일 다름슈타트에 지었어요."]},{"kind":"analogy","head":"손가락 다섯 개","scene":"손을 들어 다섯 손가락을 붙여 세운 모습이에요.","map":[["붙인 다섯 손가락","**결혼기념탑** 꼭대기의 다섯 개 둥근 봉우리"],["손바닥","네모난 벽돌 탑 몸통"],["반지","탑 허리를 두른 밝은 띠와 시계"]]}],"pass2":[{"kind":"points","head":"두 건물의 기본 사실","items":["**예술가회관** 은 에른스트 루드비히하우스라고도 하고, 독일 다름슈타트, 1901 이에요.","**예술가회관** 현관은 커다란 반원 아치예요. 아치 안쪽에 금색 무늬가 빽빽해요.","아치 양옆에 사람 모양 큰 조각이 하나씩 서 있어요.","계단은 파랑과 갈색 벽돌을 번갈아 깔아 줄무늬로 보여요.","**결혼기념탑** 은 독일 다름슈타트, 1905 예요. 벽돌 탑 꼭대기가 다섯 봉우리로 갈라져요.","두 건물 모두 **마틸덴회헤** 에 있고 **요제프 마리아 올브리히** 의 작품이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**결혼기념탑** 의 연도는 언제인가요?","choices":["1901","1905","1911"],"a":1,"why":"**예술가회관** 1901, **결혼기념탑** 1905, 그로세스 글뤼커트 주택 1911 순서예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**요제프 마리아 올브리히** 의 작품 순서는 분리파 전시관(1898), **예술가회관**(1901), **결혼기념탑**(1905) 이에요.","연도만 바꿔 놓은 객관식이 잘 나오니 순서로 외워요."]}],"walk":{"head":null,"parts":[{"b":[0.03,0.03,0.4,0.93],"c":[0.01,0,0.44,1],"r":0.5867,"img":"img/U2/walk/p037_21_01.jpg","say":"왼쪽 사진이에요. **결혼기념탑**. 꼭대기 다섯 봉우리와 초록 지붕을 보세요."},{"b":[0.44,0.21,0.54,0.56],"c":[0.406,0.182,0.594,0.616],"r":1.2857,"img":"img/U2/walk/p037_21_02.jpg","say":"오른쪽 사진이에요. **예술가회관** 현관. 큰 아치와 양옆 조각이에요."},{"b":[0.46,0.78,0.5,0.07],"c":[0.435,0.7594,0.55,0.1111],"r":6.6007,"img":"img/U2/walk/p037_21_03.jpg","say":"오른쪽 캡션이에요. **예술가회관**(에른스트 루드비히하우스), 독일 다름슈타트, 1901."},{"b":[0.45,0.95,0.52,0.045],"c":[0.424,0.8844,0.572,0.1156],"r":6.5975,"img":"img/U2/walk/p037_21_04.jpg","say":"아래 캡션이에요. **결혼기념탑**, 독일 다름슈타트, 1905."}]}},{"p":38,"title":"올브리히, 그로세스 글뤼커트 주택, 다름슈타트, 1911","terms":["요제프 마리아 올브리히","그로세스 글뤼커트 주택","Jugendstil","오메가 형태"],"pass1":[{"kind":"say","lines":["제목, 설명 한 줄, 인용 한 줄, 사진 두 장이 있는 쪽이에요.","캡션은 '요제프 마리아 올브리히, 그로세스 글뤼커트 주택, 독일 다름슈타트, 1911' 이에요.","겉은 곡선, 속은 직선. 이 한 줄이 이 집의 전부예요."]},{"kind":"analogy","head":"겉은 파도, 속은 자","scene":"밖에서는 파도치는 담요 같고 안에서는 반듯한 자 같은 집이에요.","map":[["파도치는 담요","외부의 요철, 곡선, 파동"],["반듯한 자","내부의 직선과 기하학적 요소"],["둘을 붙인 이유","선과 장식, 색채, 재료에서 오는 희열"]]}],"pass2":[{"kind":"points","head":"**그로세스 글뤼커트 주택**(1911)의 핵심","items":["설계자는 **요제프 마리아 올브리히**, 독일 다름슈타트, 1911 이에요.","외부의 요철, 곡선, 파동으로부터 결정된 형태와 내부의 직선, 기하학적 요소를 결합했어요.","비토리오 람푸냐니는 이 둘의 공통점이 선, 장식, 형태, 색채, 재료의 사용에서 오는 희열이라고 했어요.","사진을 보면 앞쪽 벽과 지붕이 한 덩어리로 이어지며 파도처럼 굽어요.","그 곡선 위에 소용돌이 같은 무늬가 얕게 새겨져 있어요. **오메가 형태** 와 함께 다음 쪽에서 봐요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**그로세스 글뤼커트 주택** 이 결합한 두 가지는 무엇인가요?","choices":["외부의 곡선과 내부의 직선","철골과 유리","벽돌과 석재"],"a":0,"why":"외부의 요철, 곡선, 파동과 내부의 직선, 기하학적 요소를 결합했어요."},{"kind":"english","head":"논술 답안: 그로세스 글뤼커트 주택","en":"그로세스 글뤼커트 주택은 1911년 올브리히가 독일 다름슈타트에 지은 주택으로 외부의 요철과 곡선, 파동으로부터 결정된 형태와 내부의 직선 및 기하학적 요소를 결합한 작품이다.","ko":"설계자, 도시, 연도, 외부 곡선과 내부 직선의 결합이 채점 항목이에요.","tip":"겉은 파도, 속은 자. 이 한 마디로 기억해요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.05,0.24,0.04],"c":[0.028,0.015,0.264,0.11],"r":3.2,"img":"img/U2/walk/p038_21_01.jpg","say":"제목이에요. 그로세스 글뤼커트 주택."},{"b":[0.06,0.1,0.88,0.07],"c":[0.016,0.0372,0.968,0.1956],"r":6.5985,"img":"img/U2/walk/p038_21_02.jpg","say":"설명 한 줄이에요. 외부의 요철, 곡선, 파동 + 내부의 직선과 기하학적 요소."},{"b":[0.06,0.17,0.88,0.1],"c":[0.016,0.1222,0.968,0.1956],"r":6.5985,"img":"img/U2/walk/p038_21_03.jpg","say":"인용이에요. 비토리오 람푸냐니의 희열이라는 평가예요."},{"b":[0.02,0.27,0.5,0.67],"c":[0,0.2365,0.55,0.737],"r":0.995,"img":"img/U2/walk/p038_21_04.jpg","say":"왼쪽 사진이에요. 벽과 지붕이 하나로 이어지며 파도처럼 굽어 있어요."},{"b":[0.51,0.42,0.45,0.47],"c":[0.4875,0.3965,0.495,0.517],"r":1.2766,"img":"img/U2/walk/p038_21_05.jpg","say":"오른쪽 사진이에요. 옆에서 보면 앞면만 곡선이고 뒤쪽은 평범한 박공 지붕이에요."},{"b":[0.4,0.95,0.58,0.045],"c":[0.362,0.8711,0.638,0.1289],"r":6.5994,"img":"img/U2/walk/p038_21_06.jpg","say":"캡션이에요. **요제프 마리아 올브리히**, **그로세스 글뤼커트 주택**, 독일 다름슈타트, 1911."}]}},{"p":39,"title":"오메가 형태와 장식물이 아닌 치장","terms":["요제프 마리아 올브리히","그로세스 글뤼커트 주택","오메가 형태","ornament","decoration","Art Nouveau","Jugendstil"],"pass1":[{"kind":"say","lines":["항목이 위아래로 나뉘어 있고 오른쪽에 현관 사진 한 장이 있어요.","이 쪽은 2강에서 시험에 가장 많이 나오는 쪽 가운데 하나예요.","핵심은 두 가지. **오메가 형태** 와, **장식물(ornament)** 이 아니라 **치장(decoration)** 이라는 것이에요."]},{"kind":"compare","head":"곡선의 출신이 다르다","cols":["**아르 누보(Art Nouveau)** 의 곡선","**오메가 형태** 의 곡선"],"rows":[["꽃과 덩굴에서 따온 자유 곡선","타원의 일부를 잘라낸 기하학적 곡선"],["손으로 자유롭게 그린 선","기하학 도형으로부터 도출한 선"],["대표는 오르타와 가우디","대표는 **요제프 마리아 올브리히**"]]}],"pass2":[{"kind":"points","head":"**그로세스 글뤼커트 주택** 의 조형","items":["전체적으로 기하학적이고 간결한 조형적 형태예요.","입면은 **요제프 마리아 올브리히** 만의 독창적 **유겐트슈틸(Jugendstil)** 곡면으로 치장했어요.","내외부의 형태와 장식에 **오메가 형태** 를 적용했어요. 올브리히만의 조형 어휘예요.","**오메가 형태** 는 **아르 누보(Art Nouveau)** 의 자유 곡선과 뚜렷한 차이가 있어요.","타원의 일부를 잘라낸 입면의 곡선과 입체적인 **오메가 형태** 는 모두 기하학적 도형으로부터 도출했어요."]},{"kind":"points","head":"**장식물(ornament)** 과 **치장(decoration)** 의 차이","items":["**장식물(ornament)** 은 벽 자체가 조각으로서 기능하는 바로크적 접근방식이에요.","**치장(decoration)** 은 밋밋한 벽에 이차원의 장식 마감재를 덧입히는 방식이에요.","올브리히는 벽면의 디자인 수단으로 **장식물(ornament)** 이 아니라 면 처리로서의 **치장(decoration)** 을 택했어요.","그래서 벽이 두껍게 파이지 않고 표면에 얇은 무늬만 남아요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"올브리히가 벽면의 디자인 수단으로 택한 것은 무엇인가요?","choices":["**장식물(ornament)**","**치장(decoration)**","노출 콘크리트"],"a":1,"why":"벽 자체를 조각하는 바로크식 **장식물(ornament)** 이 아니라 면 처리로서의 **치장(decoration)** 이에요."},{"kind":"check","q":"**오메가 형태** 가 **아르 누보(Art Nouveau)** 의 자유 곡선과 다른 점은 무엇인가요?","choices":["기하학적 도형으로부터 도출된 곡선","곡선이 아예 없음","곡선이 더 자유로움"],"a":0,"why":"타원의 일부를 잘라낸 곡선이에요. 자로 그릴 수 있는 곡선이라는 뜻이에요."},{"kind":"english","head":"논술 답안: 올브리히의 조형 어휘","en":"올브리히는 자신만의 조형 어휘인 오메가 형태를 적용하였고 이는 기하학적 도형에서 도출되어 아르 누보의 자유 곡선과 뚜렷이 다르며, 벽면의 디자인 수단으로 장식물이 아니라 면 처리로서의 치장을 택하였다.","ko":"오메가 형태, 기하학 도출, 자유 곡선과의 차이, 장식물이 아닌 치장이 채점 항목이에요.","tip":"오메가는 자로 그린 곡선, 치장은 벽에 붙이는 얇은 무늬로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.03,0.13,0.5,0.12],"c":[0.005,0.114,0.55,0.152],"r":4.8246,"img":"img/U2/walk/p039_22_01.jpg","say":"위 항목이에요. 기하학적이고 간결한 형태, 올브리히만의 곡면으로 치장."},{"b":[0.03,0.3,0.5,0.33],"c":[0.005,0.2835,0.55,0.363],"r":2.0202,"img":"img/U2/walk/p039_22_02.jpg","say":"**오메가 형태** 항목이에요. 자유 곡선과의 차이와 기하학 도형에서의 도출이에요."},{"b":[0.52,0.19,0.46,0.42],"c":[0.494,0.169,0.506,0.462],"r":1.4603,"img":"img/U2/walk/p039_22_03.jpg","say":"오른쪽 사진이에요. 반원 아치 현관 둘레에 작은 삼각 무늬가 줄지어 찍혀 있어요."},{"b":[0.08,0.78,0.88,0.1],"c":[0.032,0.7322,0.968,0.1956],"r":6.5985,"img":"img/U2/walk/p039_22_04.jpg","say":"아래 첫 항목이에요. 바로크식으로 벽을 조각하지 않고 2차원 마감재를 덧입혀요."},{"b":[0.08,0.88,0.88,0.11],"c":[0.032,0.8044,0.968,0.1956],"r":6.5985,"img":"img/U2/walk/p039_22_05.jpg","say":"아래 둘째 항목이에요. **장식물(ornament)** 이 아니라 **치장(decoration)** 을 택했어요."}]}},{"p":40,"title":"그로세스 글뤼커트 주택 실내, 1911","terms":["그로세스 글뤼커트 주택","요제프 마리아 올브리히","decoration"],"pass1":[{"kind":"say","lines":["사진 두 장뿐인 쪽이에요. 왼쪽은 흑백, 오른쪽은 컬러예요.","캡션은 '요제프 마리아 올브리히, 그로세스 글뤼커트 주택, 독일 다름슈타트, 1911' 이에요.","겉은 파도였지만 안은 직선과 기하학이라는 말을 눈으로 확인하는 쪽이에요."]}],"pass2":[{"kind":"points","head":"이 사진들에서 볼 것","items":["왼쪽은 두 층 높이의 홀이에요. 위층 발코니 난간이 세로 막대로 촘촘히 짜여 있어요.","벽에는 둥근 점무늬가 규칙적으로 찍혀 있어요. 벽을 파낸 것이 아니라 표면에 넣은 **치장(decoration)** 이에요.","가구는 곧은 나무 상자 모양이에요. 곡선 가구가 아니에요.","오른쪽은 벽난로가 있는 방이에요. 아치 둘레를 파랑과 흰색 체크 띠가 두르고 있어요.","벽난로 위에는 초록과 주황으로 그린 큰 꽃 무늬가 벽에 붙어 있어요.","**요제프 마리아 올브리히** 의 **그로세스 글뤼커트 주택** 은 이렇게 안과 밖의 느낌이 달라요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**그로세스 글뤼커트 주택** 의 실내에서 두드러지는 것은 무엇인가요?","choices":["직선과 기하학적 요소","흐르는 3차원 곡선","노출된 철골"],"a":0,"why":"외부는 곡선과 파동, 내부는 직선과 기하학적 요소라는 설명 그대로예요."}],"walk":{"head":null,"parts":[{"b":[0.07,0.05,0.42,0.86],"c":[0.049,0.007,0.462,0.946],"r":0.6512,"img":"img/U2/walk/p040_21_01.jpg","say":"왼쪽 사진이에요. 두 층 높이 홀, 세로 막대 난간과 점무늬 벽이에요."},{"b":[0.53,0.04,0.43,0.89],"c":[0.5085,0,0.473,0.979],"r":0.6442,"img":"img/U2/walk/p040_21_02.jpg","say":"오른쪽 사진이에요. 체크 띠를 두른 아치와 벽난로 위 꽃 무늬예요."},{"b":[0.14,0.95,0.58,0.045],"c":[0.111,0.8711,0.638,0.1289],"r":6.5994,"img":"img/U2/walk/p040_21_03.jpg","say":"캡션이에요. **요제프 마리아 올브리히**, **그로세스 글뤼커트 주택**, 독일 다름슈타트, 1911."}]}},{"p":41,"title":"총체예술(Total Art)","terms":["Total Art","요제프 마리아 올브리히","Arts and Crafts Movement","William Morris"],"pass1":[{"kind":"say","lines":["제목 한 줄, 항목 여러 줄, 오른쪽에 식당 사진 한 장이 있는 쪽이에요.","**총체예술(Total Art)** 은 건축, 회화, 조각 등의 예술 사이의 상호작용을 추구하는 개념이에요.","쉽게 말하면 건물부터 숟가락까지 한 사람이 한 스타일로 다 만드는 것이에요."]},{"kind":"analogy","head":"한 사람이 다 만든 집","scene":"집도 짓고 가구도 짜고 접시까지 그리는 한 사람이에요.","map":[["집","건축"],["가구와 조명","인테리어"],["접시와 숟가락","생활물품"],["모두 같은 스타일","**총체예술(Total Art)**"]]}],"pass2":[{"kind":"points","head":"**총체예술(Total Art)** 의 내용","items":["실용성과 동시에 장식성과 상징성의 조화를 추구해요.","생활과 예술이 어우러지는, 모든 예술이 삶을 위해 봉사한다는 인식이에요.","근대적 시민계급이 등장하면서 통일되고 일관된 공간 디자인에 대한 요구가 생겼어요.","아늑하고 고귀한 가정적인 분위기와 취향을 드러내는 실내장식이 각광을 받기 시작했어요.","건축과 통합된 인테리어의 개념이 등장했어요.","이때부터 가구 등 생활물품을 만드는 사람이 장인이나 공예가를 넘어 예술가적 지위를 얻게 돼요."]},{"kind":"look","walked":1},{"kind":"bg","src":"기초 다지기: 1강과 이어 보기","lines":["1강 **미술공예운동(Arts and Crafts Movement)** 에서 **윌리엄 모리스(William Morris)** 도 집과 가구를 함께 만들었어요.","다른 점은 **미술공예운동(Arts and Crafts Movement)** 이 손으로 만들기를 앞세웠다는 것이에요.","**총체예술(Total Art)** 은 만드는 방법보다 '전체가 하나로 보이는가' 를 앞세워요."]}],"pass3":[{"kind":"check","q":"**총체예술(Total Art)** 이 추구하는 것은 무엇인가요?","choices":["건축, 회화, 조각 등 예술 사이의 상호작용","기계 생산의 효율","역사 양식의 정확한 복원"],"a":0,"why":"실용성과 장식성, 상징성의 조화를 함께 추구하는 개념이에요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.06,0.75,0.05],"c":[0.0025,0.0017,0.825,0.1667],"r":6.5987,"img":"img/U2/walk/p041_21_01.jpg","say":"제목이에요. 총체예술(Total Art), 건축, 회화, 조각 등 예술 사이의 상호작용."},{"b":[0.05,0.17,0.58,0.17],"c":[0.021,0.154,0.638,0.202],"r":4.2112,"img":"img/U2/walk/p041_21_02.jpg","say":"앞 두 항목이에요. 실용성과 장식성, 상징성의 조화, 모든 예술이 삶을 위해 봉사한다는 인식이에요."},{"b":[0.05,0.35,0.58,0.27],"c":[0.021,0.334,0.638,0.302],"r":2.8168,"img":"img/U2/walk/p041_21_03.jpg","say":"근대적 시민계급의 등장과 실내장식이 각광받기 시작한 이야기예요."},{"b":[0.05,0.62,0.58,0.16],"c":[0.021,0.604,0.638,0.192],"r":4.4306,"img":"img/U2/walk/p041_21_04.jpg","say":"건축과 통합된 인테리어 개념의 등장, 그리고 그것이 건축가에게 매우 중요한 작업이었다는 줄이에요."},{"b":[0.05,0.79,0.58,0.17],"c":[0.021,0.774,0.638,0.202],"r":4.2112,"img":"img/U2/walk/p041_21_05.jpg","say":"마지막 항목이에요. 가구 제작자가 예술가적 지위를 얻게 돼요."},{"b":[0.61,0.16,0.38,0.72],"c":[0.582,0.124,0.418,0.792],"r":0.7037,"img":"img/U2/walk/p041_21_06.jpg","say":"오른쪽 사진이에요. 네모 유리 조각을 매단 조명과 나무 식기장, 차려진 식탁이에요."}]}},{"p":42,"title":"그로세스 글뤼커트 주택의 현관과 평면","terms":["그로세스 글뤼커트 주택","요제프 마리아 올브리히","Total Art"],"pass1":[{"kind":"say","lines":["사진 두 장과 평면도 한 장이 있는 쪽이에요. 캡션은 한 줄이에요.","캡션은 '요제프 마리아 올브리히, 그로세스 글뤼커트 주택, 독일 다름슈타트, 1911' 이에요.","**총체예술(Total Art)** 이 실제 집에서 어떻게 보이는지 확인하는 쪽이에요."]}],"pass2":[{"kind":"points","head":"이 사진들에서 볼 것","items":["왼쪽은 현관 홀이에요. 천장 가장자리를 삼각 무늬 띠가 한 줄 두르고 있어요.","그 띠에 맞춰 조명 기구도 삼각과 원을 섞은 모양으로 매달려 있어요.","가구와 거울, 바닥 카펫 무늬까지 같은 기하학 어휘로 맞춰져 있어요.","오른쪽 위는 평면도예요. 가운데 큰 홀(HALLE)을 방들이 둘러싸고 있어요.","오른쪽 아래는 계단 쪽이에요. 벽에 커다란 반원 아치가 뚫려 있고 그 안에 계단이 들어가요.","**요제프 마리아 올브리히** 가 **그로세스 글뤼커트 주택** 의 구석까지 직접 맞춘 결과예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"현관 홀에서 천장 띠와 조명 기구가 같은 모양을 쓰는 이유는 무엇인가요?","choices":["**총체예술(Total Art)** 로 전체를 하나의 앙상블로 맞추기 때문","재료를 아끼기 위해서","구조를 튼튼하게 하려고"],"a":0,"why":"외관과 인테리어 요소가 하나의 통일된 앙상블을 이루어야 한다는 원칙이에요."}],"walk":{"head":null,"parts":[{"b":[0.02,0.08,0.48,0.83],"c":[0,0.0385,0.528,0.913],"r":0.7711,"img":"img/U2/walk/p042_21_01.jpg","say":"왼쪽 사진이에요. 현관 홀. 천장 띠의 삼각 무늬와 매다는 조명을 보세요."},{"b":[0.54,0.04,0.35,0.3],"c":[0.5225,0.024,0.385,0.332],"r":1.5462,"img":"img/U2/walk/p042_21_02.jpg","say":"오른쪽 위 평면도예요. 가운데 홀(HALLE)을 방들이 둘러싸요."},{"b":[0.54,0.37,0.43,0.56],"c":[0.5185,0.342,0.473,0.616],"r":1.0238,"img":"img/U2/walk/p042_21_03.jpg","say":"오른쪽 아래 사진이에요. 큰 반원 아치 안에 계단이 들어가고 옆에 벽난로가 있어요."},{"b":[0.14,0.95,0.56,0.045],"c":[0.112,0.8755,0.616,0.1245],"r":6.5971,"img":"img/U2/walk/p042_21_04.jpg","say":"캡션이에요. **그로세스 글뤼커트 주택**, 독일 다름슈타트, 1911."}]}},{"p":43,"title":"라움쿤스트와 올브리히의 유겐트슈틸 실내디자인","terms":["Total Art","Raumkunst","Raumplan","요제프 마리아 올브리히","Jugendstil","Arts and Crafts Movement","William Morris"],"pass1":[{"kind":"say","lines":["항목 네 줄과 사진 네 장이 있는 쪽이에요. 침실, 꽃병 둘, 문손잡이예요.","**총체예술(Total Art)** 의 목표가 **라움쿤스트(Raumkunst)**, 곧 공간이 예술이 되는 수준이에요.","문손잡이까지 같은 스타일이어야 한다는 원칙이 여기에 나와요."]},{"kind":"analogy","head":"정해진 자리에 놓인 물건","scene":"무대 위 소품처럼 물건마다 자리가 정해져 있는 방이에요.","map":[["무대","방 하나"],["소품의 자리","특별히 정해진 목적과 장소"],["완성된 무대","**라움쿤스트(Raumkunst)**, 공간이 예술이 되는 수준"]]}],"pass2":[{"kind":"points","head":"**라움쿤스트(Raumkunst)** 로 가는 원칙","items":["외관과 인테리어 요소들이 하나의 통일된 앙상블을 이루어야 한다는 원칙이에요.","파사드나 가구, 문손잡이에 이르기까지 모든 대상이 시대의 양식을 표현해야 해요.","동시에 그 창작자의 개인적 개성을 드러내야 한다는 개념이에요.","**총체예술(Total Art)** 은 공간이 예술이 되는 **라움쿤스트(Raumkunst)** 수준에 도달하는 것을 목표로 해요.","통일된 관점에서 미학적으로 완벽하게 조화된 공간을 완성하는 것이에요.","주방 집기나 소품까지 정해진 목적을 갖고 특정 장소에 놓아 아름답게 보이도록 했어요."]},{"kind":"look","walked":1},{"kind":"bg","src":"기초 다지기: 1강 인물과 이어 보기","lines":["**윌리엄 모리스(William Morris)** 도 벽지, 가구, 책까지 같은 손으로 만들었어요.","**미술공예운동(Arts and Crafts Movement)** 의 그 태도가 독일에서는 **총체예술(Total Art)** 로 이름을 바꿔 이어져요.","차이는 목표예요. **미술공예운동(Arts and Crafts Movement)** 은 손으로 만들기, 독일은 **라움쿤스트(Raumkunst)** 예요."]}],"pass3":[{"kind":"check","q":"**총체예술(Total Art)** 의 목표로 슬라이드가 든 것은 무엇인가요?","choices":["**라움쿤스트(Raumkunst)**","**라움플란(Raumplan)**","프리패브"],"a":0,"why":"공간이 예술이 되는 수준, **라움쿤스트(Raumkunst)**, Space Art 예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**라움쿤스트(Raumkunst)** 는 공간이 예술이 되는 수준, **총체예술(Total Art)** 의 목표예요.","**라움플란(Raumplan)** 은 3강에 나오는 로스의 공간 설계법이에요. 이름만 비슷하고 전혀 달라요.","**라움쿤스트(Raumkunst)** 는 Space Art, **라움플란(Raumplan)** 은 공간 계획으로 붙여 외워요."]},{"kind":"english","head":"논술 답안: 총체예술과 라움쿤스트","en":"총체예술은 건축과 회화, 조각 등의 예술 사이의 상호작용을 추구하여 파사드부터 가구와 문손잡이에 이르기까지 모든 요소가 하나의 통일된 앙상블을 이루어야 한다는 원칙이며, 공간이 예술이 되는 라움쿤스트의 수준에 도달하는 것을 목표로 한다.","ko":"상호작용, 통일된 앙상블, 문손잡이까지, 라움쿤스트가 채점 항목이에요.","tip":"문손잡이까지 같은 스타일이라는 문장을 꼭 넣어요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.04,0.92,0.14],"c":[0,0.0078,1,0.2045],"r":6.52,"img":"img/U2/walk/p043_21_01.jpg","say":"첫 항목이에요. 파사드, 가구, 문손잡이까지 하나의 통일된 앙상블."},{"b":[0.05,0.2,0.92,0.1],"c":[0,0.1478,1,0.2045],"r":6.52,"img":"img/U2/walk/p043_21_02.jpg","say":"둘째 항목이에요. 총체예술의 목표는 라움쿤스트(Raumkunst, Space Art)."},{"b":[0.05,0.32,0.92,0.15],"c":[0,0.2928,1,0.2045],"r":6.52,"img":"img/U2/walk/p043_21_03.jpg","say":"셋째, 넷째 항목이에요. 완벽하게 조화된 공간, 모든 사물을 정해진 자리에."},{"b":[0.05,0.52,0.34,0.42],"c":[0.033,0.499,0.374,0.462],"r":1.0794,"img":"img/U2/walk/p043_21_04.jpg","say":"왼쪽 사진이에요. 흰 침대와 격자 무늬가 들어간 머리판이에요."},{"b":[0.42,0.52,0.56,0.42],"c":[0.384,0.499,0.616,0.462],"r":1.7778,"img":"img/U2/walk/p043_21_05.jpg","say":"오른쪽 사진들이에요. 붉은 도자기 꽃병과 초록 유리 꽃병, 그리고 금속 문손잡이 판이에요."},{"b":[0.03,0.93,0.45,0.06],"c":[0.0075,0.89,0.495,0.11],"r":6.0,"img":"img/U2/walk/p043_21_06.jpg","say":"캡션이에요. **요제프 마리아 올브리히** 의 유겐트슈틸 실내디자인."}]}},{"p":44,"title":"페터 베렌스, 베렌스 주택, 다름슈타트, 1911","terms":["페터 베렌스","베렌스 주택","Jugendstil","Total Art"],"pass1":[{"kind":"say","lines":["제목 두 줄과 사진 두 장이 있는 쪽이에요.","캡션은 '페터 베렌스, 베렌스 주택, 독일 다름슈타트, 1911' 이에요.","**페터 베렌스**(1868-1940)는 **유겐트슈틸(Jugendstil)** 의 첫 사례를 만든 사람이에요."]},{"kind":"analogy","head":"눈썹 모양 박공","scene":"집 앞면 삼각 지붕 선을 진한 색으로 굵게 그린 모습이에요.","map":[["진한 눈썹 선","박공을 두른 짙은 타일 띠"],["하얀 얼굴","흰 회벽"],["눈","그 안에 들어간 넓은 창"]]}],"pass2":[{"kind":"points","head":"**베렌스 주택**(1911)에서 볼 것","items":["설계자는 **페터 베렌스**, 독일 다름슈타트, 1911 이에요.","박공 끝이 뾰족하게 솟고 그 둘레를 짙은 색 타일 띠가 굵게 두르고 있어요.","띠는 곡선으로 휘어져 내려와요. 위는 뾰족하고 아래는 둥글게 벌어져요.","벽은 흰 회벽이고, 띠와의 대비가 아주 강해요.","그 안에 창이 여러 칸으로 나뉘어 넓게 들어가 있어요.","**베렌스 주택** 은 현관부터 식기까지 통합해 디자인한 **총체예술(Total Art)** 의 사례예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**베렌스 주택** 의 설계자와 연도는 무엇인가요?","choices":["**페터 베렌스**, 1911","**요제프 마리아 올브리히**, 1905","**안토니 가우디**, 1912"],"a":0,"why":"독일 다름슈타트, 1911 이에요. **페터 베렌스** 는 1898년 유겐트슈틸 그래픽으로도 나와요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.07,0.12,0.04],"c":[0.0,0.035,0.2,0.11],"r":2.4242,"img":"img/U2/walk/p044_21_01.jpg","say":"왼쪽 위 제목이에요. 베렌스 주택."},{"b":[0.03,0.14,0.44,0.05],"c":[0.008,0.11,0.484,0.11],"r":5.8667,"img":"img/U2/walk/p044_21_02.jpg","say":"인물 표시예요. 페터 베렌스(Peter Behrens, 1868-1940)."},{"b":[0.02,0.47,0.44,0.46],"c":[0,0.447,0.484,0.506],"r":1.2754,"img":"img/U2/walk/p044_21_03.jpg","say":"왼쪽 사진이에요. 길에서 본 전체 모습. 흰 벽과 짙은 띠가 대비돼요."},{"b":[0.48,0.23,0.5,0.71],"c":[0.45,0.1945,0.55,0.781],"r":0.939,"img":"img/U2/walk/p044_21_04.jpg","say":"오른쪽 사진이에요. 박공 둘레를 두른 짙은 타일 띠를 가까이서 보세요."},{"b":[0.51,0.95,0.42,0.045],"c":[0.489,0.89,0.462,0.11],"r":5.6,"img":"img/U2/walk/p044_21_05.jpg","say":"캡션이에요. **페터 베렌스**, **베렌스 주택**, 독일 다름슈타트, 1911."}]}},{"p":45,"title":"현관문과 철제 대문 (캡션 없는 쪽)","terms":["베렌스 주택","Jugendstil","페터 베렌스"],"pass1":[{"kind":"say","lines":["사진 두 장만 있고 글이 한 줄도 없는 쪽이에요.","슬라이드가 이름과 연도를 적어 주지 않았어요.","그래서 여기서는 사진에서 보이는 것만 읽고 넘어가요."]}],"pass2":[{"kind":"points","head":"이 사진들에서 볼 것","items":["왼쪽은 현관문이에요. 양옆에 초록 타일을 세로로 쌓아 만든 기둥이 서 있어요.","문 위 반원 유리에는 가는 금속 선으로 만든 무늬가 들어가 있어요.","문 가운데에는 부채처럼 펼쳐진 금속 장식이 붙어 있고 아래로 긴 선이 내려와요.","바닥에는 네모를 겹친 모자이크 무늬가 깔려 있어요.","오른쪽은 철제 대문이에요. 곧은 세로 살들 위에 굵은 곡선 띠가 겹쳐져요.","곡선이 있지만 좌우가 딱 맞게 대칭이에요. **유겐트슈틸(Jugendstil)** 의 정리된 곡선이에요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.03,0.08,0.44,0.88],"c":[0.008,0.032,0.484,0.968],"r":0.6667,"img":"img/U2/walk/p045_21_01.jpg","say":"왼쪽 사진이에요. 현관문과 양옆의 초록 타일 기둥이에요."},{"b":[0.17,0.12,0.16,0.3],"c":[0.15,0.104,0.2,0.332],"r":0.8032,"img":"img/U2/walk/p045_21_02.jpg","say":"문 위 반원 유리예요. 가는 금속 선으로 무늬가 짜여 있어요."},{"b":[0.19,0.32,0.13,0.4],"c":[0.155,0.3,0.2,0.44],"r":0.6061,"img":"img/U2/walk/p045_21_03.jpg","say":"문 가운데예요. 부채처럼 펼쳐진 금속 장식이 붙어 있어요."},{"b":[0.49,0.16,0.49,0.63],"c":[0.461,0.1285,0.539,0.693],"r":1.037,"img":"img/U2/walk/p045_21_04.jpg","say":"오른쪽 사진이에요. 곧은 세로 살과 굵은 곡선 띠가 겹친 철제 대문이에요."}]}},{"p":46,"title":"베렌스 주택의 현관과 뮤직룸","terms":["베렌스 주택","페터 베렌스","Total Art"],"pass1":[{"kind":"say","lines":["사진 세 장과 짧은 글 두 줄이 있는 쪽이에요.","글은 '베렌스 주택의 _현관' 과 '베렌스 주택의 _뮤직룸' 이에요.","**페터 베렌스** 가 방마다 다른 분위기를 같은 어휘로 만들어요."]}],"pass2":[{"kind":"points","head":"이 사진들에서 볼 것","items":["왼쪽 위는 **베렌스 주택** 의 현관이에요. 계단이 정면에 놓이고 양옆에 격자 나무 칸막이가 있어요.","칸막이 위쪽에 삼각과 마름모를 섞은 무늬가 뚫려 있어요.","왼쪽 아래는 뮤직룸이에요. 검은 벽과 가운데 큰 그림, 그리고 피아노가 놓여 있어요.","천장에도 나무 띠가 격자로 짜여 있어 벽과 같은 무늬가 이어져요.","오른쪽은 금색 금속 패널 두 장과 가죽 의자예요. 패널에 뾰족한 삼각 무늬가 대칭으로 새겨져 있어요.","건물, 가구, 금속 장식이 같은 어휘로 묶인 **총체예술(Total Art)** 의 사례예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**베렌스 주택** 의 현관과 뮤직룸에서 공통으로 보이는 것은 무엇인가요?","choices":["삼각과 격자를 반복하는 같은 무늬 어휘","흐르는 꽃 덩굴 곡선","노출 벽돌 벽"],"a":0,"why":"방이 달라도 같은 기하학 무늬로 묶여 있어요. **페터 베렌스** 의 통합 디자인이에요."}],"walk":{"head":null,"parts":[{"b":[0.08,0.03,0.31,0.47],"c":[0.0645,0.0065,0.341,0.517],"r":0.8794,"img":"img/U2/walk/p046_21_01.jpg","say":"왼쪽 위 사진이에요. 현관. 계단과 격자 나무 칸막이를 보세요."},{"b":[0.41,0.5,0.17,0.04],"c":[0.395,0.465,0.2,0.11],"r":2.4242,"img":"img/U2/walk/p046_21_02.jpg","say":"글 한 줄이에요. 베렌스 주택의 _현관."},{"b":[0.08,0.55,0.39,0.42],"c":[0.0605,0.529,0.429,0.462],"r":1.2381,"img":"img/U2/walk/p046_21_03.jpg","say":"왼쪽 아래 사진이에요. 뮤직룸. 검은 벽과 그림, 피아노예요."},{"b":[0.49,0.88,0.19,0.04],"c":[0.478,0.845,0.214,0.11],"r":2.5939,"img":"img/U2/walk/p046_21_04.jpg","say":"글 한 줄이에요. 베렌스 주택의 _뮤직룸."},{"b":[0.58,0.1,0.38,0.75],"c":[0.561,0.0625,0.418,0.825],"r":0.6756,"img":"img/U2/walk/p046_21_05.jpg","say":"오른쪽 사진이에요. 삼각 무늬가 새겨진 금색 패널과 가죽 의자예요."}]}},{"p":47,"title":"베렌스 주택의 식당과 식기 디자인","terms":["베렌스 주택","페터 베렌스","Total Art","Raumkunst","Arts and Crafts Movement","William Morris"],"pass1":[{"kind":"say","lines":["사진 세 장과 글 한 줄이 있는 쪽이에요. 은식기, 커피 세트, 식당이에요.","글은 '베렌스 주택의 식당과 식기 디자인' 이에요.","숟가락까지 디자인했다는 말이 사진으로 증명되는 쪽이에요."]},{"kind":"recap","items":["**총체예술(Total Art)** 은 건물부터 식기까지 하나로 묶는 것이에요.","목표는 공간이 예술이 되는 **라움쿤스트(Raumkunst)** 예요.","**베렌스 주택** 은 그 예로 슬라이드가 든 집이에요."]}],"pass2":[{"kind":"points","head":"이 사진들에서 볼 것","items":["왼쪽은 은식기예요. 숟가락, 포크, 나이프 손잡이 끝에 같은 네모 무늬가 새겨져 있어요.","가운데는 커피 세트예요. 주전자와 잔이 모두 육각형이고 초록 선 무늬가 같아요.","받침 접시까지 육각형이라 한 벌로 보여요.","오른쪽은 식당이에요. 천장에 리본처럼 얽힌 곡선 띠가 크게 그려져 있어요.","창가를 따라 흰 의자가 둘러서고 가운데 둥근 식탁이 놓여 있어요.","**페터 베렌스** 가 **베렌스 주택** 에서 식기까지 디자인한 것이 **총체예술(Total Art)** 의 대표 장면이에요."]},{"kind":"look","walked":1},{"kind":"bg","src":"기초 다지기: 왜 식기까지 디자인하나요","lines":["1강 **미술공예운동(Arts and Crafts Movement)** 의 **윌리엄 모리스(William Morris)** 도 같은 일을 했어요.","독일에서는 그것이 **총체예술(Total Art)** 과 **라움쿤스트(Raumkunst)** 라는 이름과 목표를 얻어요.","시험에서는 '현관, 뮤직룸, 식당과 식기까지 통합' 이라는 표현이 그대로 나와요."]}],"pass3":[{"kind":"check","q":"**베렌스 주택** 에서 통합 디자인의 범위로 슬라이드가 든 것은 어디까지인가요?","choices":["현관, 뮤직룸, 식당과 식기까지","외관과 구조까지","정원과 담장까지"],"a":0,"why":"숟가락과 커피 잔까지 같은 어휘로 디자인했어요."},{"kind":"english","head":"논술 답안: 베렌스 주택","en":"베렌스 주택은 1911년 페터 베렌스가 독일 다름슈타트에 지은 주택으로 현관과 뮤직룸, 식당과 식기 디자인에 이르기까지 통합적으로 디자인된 총체예술의 사례이다.","ko":"설계자, 도시, 연도, 통합 범위, 총체예술이 채점 항목이에요.","tip":"숟가락까지 같은 사람이 만들었다는 문장으로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.01,0.29,0.34,0.43],"c":[0,0.2685,0.374,0.473],"r":1.0543,"img":"img/U2/walk/p047_21_01.jpg","say":"왼쪽 사진이에요. 은식기. 손잡이 끝의 네모 무늬가 모두 같아요."},{"b":[0.35,0.24,0.29,0.52],"c":[0.3355,0.214,0.319,0.572],"r":0.7436,"img":"img/U2/walk/p047_21_02.jpg","say":"가운데 사진이에요. 육각형 주전자와 잔, 초록 선 무늬가 한 벌이에요."},{"b":[0.65,0.21,0.31,0.55],"c":[0.6345,0.1825,0.341,0.605],"r":0.7515,"img":"img/U2/walk/p047_21_03.jpg","say":"오른쪽 사진이에요. 식당. 천장에 리본 모양 곡선 띠가 그려져 있어요."},{"b":[0.63,0.94,0.28,0.05],"c":[0.616,0.89,0.308,0.11],"r":3.7333,"img":"img/U2/walk/p047_21_04.jpg","say":"글 한 줄이에요. 베렌스 주택의 식당과 식기 디자인."}]}},{"p":48,"title":"아르데코","terms":["아르데코","뉴 빅토리아 시네마","Art Nouveau"],"pass1":[{"kind":"say","lines":["제목 한 줄, 항목 여러 줄, 오른쪽에 극장 내부 사진 한 장이 있어요.","**아르데코** 는 1925년 파리 국제 근대산업 장식예술 박람회의 이름에서 유래했어요.","**아르 누보(Art Nouveau)** 가 꽃이라면 **아르데코** 는 번개와 지그재그예요.","오른쪽 사진은 Trent and Lewis 의 **뉴 빅토리아 시네마**, 영국 런던, 1929 예요."]},{"kind":"analogy","head":"꽃에서 번개로","scene":"부드러운 꽃 무늬를 지우고 번쩍이는 번개 무늬를 그리는 일이에요.","map":[["꽃과 덩굴","**아르 누보(Art Nouveau)** 의 모티프"],["번개와 지그재그","**아르데코** 의 모티프"],["반짝이는 금속 표면","광택 있는 값비싼 재료"]]}],"pass2":[{"kind":"points","head":"**아르데코** 의 기본 사실","items":["1925년 파리 국제 근대산업 장식예술 박람회의 이름에서 유래했어요.","1920년대 후반부터 30년대 파리의 현대적 양식을 대표해요.","바우하우스보다 부드럽고 대중적이에요."]},{"kind":"points","head":"**아르데코** 의 특징","items":["고전적 영감, 매끄러운 표면의 사용, 이국적 표현이에요.","값비싼 재료를 써요. 광택 있는 금속, 흑단, 래커칠된 목재, 매끄럽게 다듬은 돌, 유리, 플라스틱이에요.","반복되는 동적인 기하학적 주제를 써요. 번개, 지그재그, 햇살모양이에요.","아프리카 동물무늬도 써요. 얼룩말, 표범무늬예요.","패션과 예술이 실내디자인에 참여해요.","슬라이드가 든 사례는 **뉴 빅토리아 시네마**, Trent and Lewis, 영국 런던, 1929 예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**아르데코** 라는 이름이 유래한 것은 무엇인가요?","choices":["1925년 파리 국제 근대산업 장식예술 박람회","1851년 런던 만국박람회","1896년 독일 잡지"],"a":0,"why":"1920년대 후반부터 30년대 파리의 현대적 양식을 대표해요."},{"kind":"check","q":"**아르데코** 의 기하학적 주제가 아닌 것은 무엇인가요?","choices":["번개","지그재그","식물 덩굴"],"a":2,"why":"식물 덩굴은 **아르 누보(Art Nouveau)** 의 모티프예요. 이 대비가 시험에 자주 나와요."},{"kind":"english","head":"논술 답안: 아르데코","en":"아르데코는 1925년 파리 국제 근대산업 장식예술 박람회의 이름에서 유래한 양식으로 바우하우스보다 부드럽고 대중적이며, 매끄러운 표면과 값비싼 재료, 번개와 지그재그 같은 반복되는 기하학적 주제를 특징으로 한다.","ko":"유래, 시기, 바우하우스와의 비교, 특징 다섯 가지가 채점 항목이에요.","tip":"1925 파리, 번개와 지그재그, 값비싼 재료 세 덩어리로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.06,0.13,0.05],"c":[0.005,0.03,0.2,0.11],"r":2.4242,"img":"img/U2/walk/p048_22_01.jpg","say":"제목이에요. 아르데코."},{"b":[0.03,0.16,0.65,0.14],"c":[0,0.144,0.715,0.172],"r":5.5426,"img":"img/U2/walk/p048_22_02.jpg","say":"위 두 항목이에요. 1925년 파리 박람회 이름에서 유래, 1920년대 후반부터 30년대 파리 대표."},{"b":[0.03,0.29,0.55,0.03],"c":[0.0025,0.2439,0.605,0.1222],"r":6.6012,"img":"img/U2/walk/p048_22_03.jpg","say":"셋째 항목이에요. 바우하우스보다 부드럽고 대중적."},{"b":[0.05,0.4,0.53,0.3],"c":[0.0235,0.384,0.583,0.332],"r":2.3414,"img":"img/U2/walk/p048_22_04.jpg","say":"특징 앞부분이에요. 고전적 영감, 매끄러운 표면, 이국적 표현, 값비싼 재료."},{"b":[0.05,0.7,0.53,0.23],"c":[0.0235,0.684,0.583,0.262],"r":2.9669,"img":"img/U2/walk/p048_22_05.jpg","say":"특징 뒷부분이에요. 번개와 지그재그, 아프리카 동물무늬, 패션과 예술의 참여."},{"b":[0.58,0.21,0.4,0.79],"c":[0.56,0.131,0.44,0.869],"r":0.6751,"img":"img/U2/walk/p048_22_06.jpg","say":"오른쪽 사진과 캡션이에요. Trent & Lewis, **뉴 빅토리아 시네마**, 영국 런던, 1929. 천장에 별 모양 조명이 달려 있어요."}]}},{"p":49,"title":"윌리엄 밴 앨런, 크라이슬러 빌딩, 뉴욕, 1930","terms":["아르데코","크라이슬러 빌딩","Art Nouveau"],"pass1":[{"kind":"say","lines":["왼쪽에 큰 사진, 오른쪽에 항목 두 줄과 책 표지 사진이 있는 쪽이에요.","캡션은 '윌리엄, 반 알렌, 크라이슬러 빌딩, 미국 뉴욕, 1930' 이에요.","**크라이슬러 빌딩** 은 **아르데코** 마천루의 가장 드라마틱한 예예요."]},{"kind":"analogy","head":"계단처럼 쌓은 첨탑","scene":"접시를 크기 순서로 겹쳐 쌓고 꼭대기에 바늘을 꽂은 모습이에요.","map":[["크기가 줄어드는 접시","계단식으로 물려서 쌓은 부채꼴 지붕"],["반짝이는 접시","스테인레스 스틸 표면"],["꼭대기 바늘","뾰족하게 솟은 첨탑"]]}],"pass2":[{"kind":"points","head":"**크라이슬러 빌딩**(1930)에서 볼 것","items":["**아르데코** 양식은 마천루 건축으로부터 형태들을 빌어 왔어요.","동시에 건축가들은 그들의 빌딩과 **아르데코** 의 장식적인 요소들을 결합했어요.","스테인레스 스틸로 만들어진 뾰족한 부분에 이르기까지 계단식으로 물려서 쌓은 형태예요.","장식적인 디테일이 있는 이런 양식의 마천루 건축 가운데 가장 드라마틱한 예예요.","설계자는 윌리엄 밴 앨런, 미국 뉴욕, 1930 이에요."]},{"kind":"compare","head":"곡선에서 번개로","cols":["**아르 누보(Art Nouveau)**","**아르데코**"],"rows":[["꽃과 덩굴의 자유 곡선","번개, 지그재그, 햇살 모양"],["1890-1910","1920년대 후반에서 30년대"],["단철 창살과 색유리","스테인레스 스틸과 광택 금속"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**크라이슬러 빌딩** 의 설계자와 도시, 연도는 무엇인가요?","choices":["윌리엄 밴 앨런, 뉴욕, 1930","다니엘 번햄, 시카고, 1895","존 루트, 시카고, 1893"],"a":0,"why":"스테인레스 스틸 첨탑까지 계단식으로 쌓은 **아르데코** 마천루의 대표예요."},{"kind":"english","head":"논술 답안: 크라이슬러 빌딩","en":"크라이슬러 빌딩은 1930년 윌리엄 밴 앨런이 미국 뉴욕에 지은 건물로 스테인레스 스틸의 뾰족한 부분에 이르기까지 계단식으로 물려 쌓은 형태와 장식적 디테일을 지닌 아르데코 마천루의 대표작이다.","ko":"설계자, 도시, 연도, 계단식 형태, 스테인레스 첨탑이 채점 항목이에요.","tip":"접시를 쌓고 바늘을 꽂았다고 그림으로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.06,0.0,0.29,0.98],"c":[0,0,0.4192,1],"r":0.5589,"img":"img/U2/walk/p049_22_01.jpg","say":"왼쪽 사진이에요. **크라이슬러 빌딩** 전체. 꼭대기 첨탑이 하늘을 찔러요."},{"b":[0.36,0.03,0.6,0.16],"c":[0.33,0.014,0.66,0.192],"r":4.5833,"img":"img/U2/walk/p049_22_02.jpg","say":"첫 항목이에요. 마천루 형태를 빌려 오고 **아르데코** 장식 요소를 결합해요."},{"b":[0.36,0.2,0.6,0.2],"c":[0.33,0.184,0.66,0.232],"r":3.7931,"img":"img/U2/walk/p049_22_03.jpg","say":"둘째 항목이에요. 스테인레스 스틸 첨탑까지 계단식으로 물려 쌓았어요."},{"b":[0.55,0.41,0.3,0.53],"c":[0.535,0.3835,0.33,0.583],"r":0.7547,"img":"img/U2/walk/p049_22_04.jpg","say":"책 표지 사진이에요. 첨탑을 가까이서 보면 부채꼴이 겹겹이 올라가요."},{"b":[0.53,0.95,0.44,0.045],"c":[0.508,0.89,0.484,0.11],"r":5.8667,"img":"img/U2/walk/p049_22_05.jpg","say":"캡션이에요. 윌리엄 밴 앨런, **크라이슬러 빌딩**, 미국 뉴욕, 1930."}]}},{"p":50,"title":"데일리 익스프레스 빌딩, 런던, 1931","terms":["데일리 익스프레스 빌딩","아르데코"],"pass1":[{"kind":"say","lines":["사진 두 장과 항목 세 줄이 있는 쪽이에요.","캡션은 '앨리스 & 클락과 오웬 윌리엄스, 데일리 익스프레스 빌딩, 영국 런던, 1931' 이에요.","**데일리 익스프레스 빌딩** 은 신문사 건물이고 실내가 **아르데코** 의 교과서예요."]},{"kind":"analogy","head":"반짝이는 로비","scene":"검은 돌과 은색 금속이 번갈아 빛나는 현관이에요.","map":[["검은 돌","블랙 대리석 벽"],["은색 금속","크롬 도금의 철재"],["물결치는 바닥","파도형으로 깐 탄성고무"]]}],"pass2":[{"kind":"points","head":"**데일리 익스프레스 빌딩**(1931)의 실내","items":["설계자는 앨리스 앤 클락과 오웬 윌리엄스, 영국 런던, 1931 이에요.","테라조 마감의 철근 콘크리트 계단이 1층의 현관 홀과 상층의 사무공간을 다이나믹하게 연결해요.","청색, 블랙, 녹색의 탄성고무를 파도형으로 사용한 바닥 디자인이에요.","벽면은 블랙 대리석, 흑단 및 크롬 도금의 철재를 썼어요.","천장에는 부채살처럼 퍼지는 금속 장식과 지그재그 띠가 보여요."]},{"kind":"look","walked":1},{"kind":"bg","src":"기초 다지기: 테라조가 뭔가요","lines":["테라조는 잘게 부순 돌을 시멘트에 섞어 굳힌 뒤 표면을 갈아 매끈하게 만든 마감이에요.","돌처럼 보이면서 어떤 모양으로든 부어 만들 수 있어 계단에 많이 써요.","**아르데코** 가 좋아하는 '매끄러운 표면' 이 바로 이런 재료예요."]}],"pass3":[{"kind":"check","q":"**데일리 익스프레스 빌딩** 의 바닥 디자인은 무엇인가요?","choices":["청색, 블랙, 녹색의 탄성고무를 파도형으로 사용","깨진 타일 모자이크","나무 쪽매"],"a":0,"why":"벽면은 블랙 대리석, 흑단, 크롬 도금의 철재를 썼어요."}],"walk":{"head":null,"parts":[{"b":[0.02,0.05,0.43,0.83],"c":[0,0.0085,0.473,0.913],"r":0.6908,"img":"img/U2/walk/p050_21_01.jpg","say":"왼쪽 사진이에요. 현관 홀. 천장의 부채꼴 장식과 지그재그 띠를 보세요."},{"b":[0.05,0.89,0.35,0.06],"c":[0.0325,0.865,0.385,0.11],"r":4.6667,"img":"img/U2/walk/p050_21_02.jpg","say":"캡션이에요. 앨리스 & 클락과 오웬 윌리엄스, **데일리 익스프레스 빌딩**, 영국 런던, 1931."},{"b":[0.48,0.05,0.48,0.32],"c":[0.456,0.034,0.528,0.352],"r":2.0,"img":"img/U2/walk/p050_21_03.jpg","say":"오른쪽 위 사진이에요. 뱀 모양으로 휘어 오른 금속 난간과 금색 부조예요."},{"b":[0.5,0.49,0.16,0.04],"c":[0.48,0.455,0.2,0.11],"r":2.4242,"img":"img/U2/walk/p050_21_04.jpg","say":"소제목이에요. 데일리 익스프레스 빌딩."},{"b":[0.48,0.55,0.49,0.33],"c":[0.4555,0.5335,0.539,0.363],"r":1.9798,"img":"img/U2/walk/p050_21_05.jpg","say":"항목 세 줄이에요. 테라조 계단, 파도형 탄성고무 바닥, 블랙 대리석 벽이에요."}]}},{"p":51,"title":"데일리 익스프레스 빌딩의 천장과 뮤즈 장식","terms":["데일리 익스프레스 빌딩","아르데코"],"pass1":[{"kind":"say","lines":["사진 두 장과 항목 두 줄이 있는 쪽이에요.","캡션은 '앨리스, 클락, 오웬 윌리엄스, 데일리 익스프레스 빌딩, 영국 런던, 1931' 이에요.","천장 장식이 '별의 폭발' 을 형상화한 silver 장식이에요."]},{"kind":"analogy","head":"터지는 별","scene":"가운데 한 점에서 빛줄기가 사방으로 뻗어 나가는 모양이에요.","map":[["가운데 점","천장 가운데에 매달린 금속 덩어리"],["뻗어 나간 빛줄기","부챗살처럼 퍼지는 은색 면"],["빛이 닿은 가장자리","지그재그로 꺾인 테두리"]]}],"pass2":[{"kind":"points","head":"이 사진들에서 볼 것","items":["천정 장식은 '별의 폭발' 을 형상화한 silver 장식이에요.","서측 벽에는 대영제국을 수호하는 뮤즈를 표현했고 금과 은으로 장식했어요.","바닥은 파도 무늬가 길게 이어져 홀 끝까지 흘러가요.","천장 테두리는 지그재그로 꺾여 있어요. **아르데코** 의 기하학적 주제 그대로예요.","**데일리 익스프레스 빌딩** 은 이렇게 천장, 벽, 바닥이 모두 장식 대상이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**데일리 익스프레스 빌딩** 의 천장 장식이 형상화한 것은 무엇인가요?","choices":["별의 폭발","파도","덩굴"],"a":0,"why":"silver 장식이에요. 서측 벽에는 대영제국을 수호하는 뮤즈를 금과 은으로 표현했어요."},{"kind":"english","head":"논술 답안: 데일리 익스프레스 빌딩","en":"데일리 익스프레스 빌딩은 1931년 영국 런던에 지어졌으며 테라조 마감의 철근 콘크리트 계단, 파도형 탄성고무 바닥, 블랙 대리석 벽, 별의 폭발을 형상화한 은색 천장 장식을 갖는다.","ko":"연도와 도시, 계단, 바닥, 벽, 천장 네 가지 재료가 채점 항목이에요.","tip":"계단, 바닥, 벽, 천장 순서로 하나씩 떠올려요."}],"walk":{"head":null,"parts":[{"b":[0.01,0.15,0.43,0.75],"c":[0,0.1125,0.473,0.825],"r":0.7644,"img":"img/U2/walk/p051_21_01.jpg","say":"왼쪽 사진이에요. 홀 전체. 별 폭발 모양 은색 천장과 파도 무늬 바닥이에요."},{"b":[0.02,0.91,0.35,0.07],"c":[0.0025,0.89,0.385,0.11],"r":4.6667,"img":"img/U2/walk/p051_21_02.jpg","say":"캡션이에요. **데일리 익스프레스 빌딩**, 영국 런던, 1931."},{"b":[0.46,0.16,0.5,0.51],"c":[0.435,0.1345,0.55,0.561],"r":1.3072,"img":"img/U2/walk/p051_21_03.jpg","say":"오른쪽 사진이에요. 천장 장식을 가까이서. 부챗살이 사방으로 뻗어요."},{"b":[0.48,0.73,0.48,0.2],"c":[0.456,0.714,0.528,0.232],"r":3.0345,"img":"img/U2/walk/p051_21_04.jpg","say":"항목 두 줄이에요. 별의 폭발 silver 장식, 서측 벽의 뮤즈를 금과 은으로 장식."}]}},{"p":52,"title":"시카고 학파의 시작","terms":["시카고 학파","시카고 대화재","시카고 워터타워","cast iron","steel"],"pass1":[{"kind":"say","lines":["제목, 항목 네 줄, 사진 두 장이 있는 쪽이에요.","**시카고 학파** 는 1871년 **시카고 대화재** 뒤에 도시를 새로 지으며 생긴 흐름이에요.","주문이 여기서 다시 바뀌어요. 장식보다 높이와 큰 창이 먼저가 돼요."]},{"kind":"analogy","head":"불탄 도시에 새로 짓기","scene":"도시 전체를 한 번에 새로 짓게 된 특별한 기회예요.","map":[["불탄 자리","**시카고 대화재**(1871)로 사라진 상업지구"],["새 기술","**철골(강철)** 골조와 엘리베이터"],["새로 생긴 것","고층 사무소 건물, 곧 마천루"]]}],"pass2":[{"kind":"points","head":"**시카고 학파** 가 생긴 조건","items":["**시카고 대화재**(1871)로 도시를 새로 건설했어요. 상업지구 전체와 주거지의 3분의 1이 불탔어요.","상업용 건축이 발달하고 마천루가 등장해요.","**주철(cast iron)** 골조는 1850년, 증기 엘리베이터는 1864년, 수력 엘리베이터는 1867년에 개발됐어요.","**철골(강철)** 구조로 고층화가 가능해졌고, 백화점과 사무실을 위한 큰 창이 필요했어요.","시카고 금속산업이 팽창한 것도 배경이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**시카고 대화재** 가 일어난 해는 언제인가요?","choices":["1851","1871","1893"],"a":1,"why":"1871년이에요. 상업지구 전체와 주거지의 3분의 1이 불탔어요."},{"kind":"check","q":"사진 속 **시카고 워터타워** 는 어떤 건물인가요?","choices":["화재에서 살아남은 1869년 건물","화재 뒤에 새로 지은 철골 건물","설리번의 백화점"],"a":0,"why":"Chicago Water Tower and Pumping Station, 1869 이에요."},{"kind":"english","head":"논술 답안: 시카고 학파의 배경","en":"시카고 학파는 1871년 시카고 대화재로 도시를 새로 건설하면서 형성되었으며, 주철 골조와 엘리베이터의 개발, 강철구조에 의한 고층화, 큰 창의 요구, 시카고 금속산업의 팽창을 배경으로 한다.","ko":"화재 연도, 기술 개발, 고층화, 금속산업 네 가지가 채점 항목이에요.","tip":"불이 나서, 철이 있어서, 엘리베이터가 있어서 높아졌다고 이어 외워요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.04,0.17,0.05],"c":[0.025,0.01,0.2,0.11],"r":2.4242,"img":"img/U2/walk/p052_21_01.jpg","say":"제목이에요. 시카고 학파."},{"b":[0.04,0.11,0.92,0.18],"c":[0.0,0.094,1,0.212],"r":6.2893,"img":"img/U2/walk/p052_21_02.jpg","say":"위 두 항목이에요. **시카고 대화재**(1871), 주철 골조 1850, 증기 엘리베이터 1864, 수력 엘리베이터 1867."},{"b":[0.04,0.29,0.92,0.12],"c":[0.0,0.2478,1,0.2045],"r":6.52,"img":"img/U2/walk/p052_21_03.jpg","say":"아래 두 항목이에요. 강철구조로 고층화, 백화점과 사무실의 큰 창, 시카고 금속산업의 팽창."},{"b":[0.08,0.44,0.31,0.54],"c":[0.0645,0.406,0.341,0.594],"r":0.7654,"img":"img/U2/walk/p052_21_04.jpg","say":"왼쪽 사진이에요. **시카고 워터타워**. 돌로 쌓아 성처럼 생긴 탑이에요."},{"b":[0.43,0.44,0.46,0.41],"c":[0.407,0.4195,0.506,0.451],"r":1.4959,"img":"img/U2/walk/p052_21_05.jpg","say":"오른쪽 사진이에요. 같은 탑을 올려다본 모습. 뒤에 유리 고층건물이 서 있어요."},{"b":[0.43,0.91,0.42,0.08],"c":[0.409,0.888,0.462,0.112],"r":5.5,"img":"img/U2/walk/p052_21_06.jpg","say":"오른쪽 캡션이에요. Chicago Water Tower and Pumping Station, 1869, 화재에서 살아남은 건물."}]}},{"p":53,"title":"릴라이언스 빌딩과 뉴욕 플랫아이언 빌딩","terms":["리라이언스 빌딩","플랫아이언 빌딩","시카고 학파"],"pass1":[{"kind":"say","lines":["사진 한 장과 캡션 두 줄만 있는 쪽이에요.","캡션은 '릴라이언스 빌딩, 1895, 16층' 과 '뉴욕 플랫아이언 빌딩, 1902, 22층' 이에요.","높이가 몇 층까지 올라갔는지를 숫자로 보여 주는 쪽이에요."]},{"kind":"recap","items":["**시카고 대화재** 뒤에 **철골(강철)** 과 엘리베이터가 고층화를 열었어요.","**리라이언스 빌딩** 은 1895년에 16층, **플랫아이언 빌딩** 은 1902년에 22층이에요.","7년 사이에 6개 층이 더 올라갔다는 이야기예요."]}],"pass2":[{"kind":"points","head":"이 쪽에서 챙길 숫자","items":["**리라이언스 빌딩** 은 1895년, 16층이에요.","**플랫아이언 빌딩** 은 뉴욕, 1902년, 22층이에요.","사진은 눈 내린 시카고 강변이에요. 오래된 돌 마감 건물과 유리 건물이 섞여 있어요.","오른쪽에 시계탑이 달린 흰 건물이 크게 보여요.","**시카고 학파** 의 고층 건물들이 실제 도시에서 어떻게 모여 서는지 보여 주는 사진이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**플랫아이언 빌딩** 의 연도와 층수는 무엇인가요?","choices":["1895년, 16층","1902년, 22층","1893년, 11층"],"a":1,"why":"1895년 16층은 **리라이언스 빌딩** 이에요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.02,0.89,0.88],"c":[0.0055,0,0.979,0.968],"r":1.3485,"img":"img/U2/walk/p053_21_01.jpg","say":"사진 전체예요. 눈 내린 강변에 고층건물이 빽빽하게 모여 있어요."},{"b":[0.1,0.33,0.13,0.55],"c":[0.0474,0.3025,0.2353,0.605],"r":0.5186,"img":"img/U2/walk/p053_21_02.jpg","say":"왼쪽 무리예요. 돌로 마감한 오래된 고층건물이 줄지어 서 있어요."},{"b":[0.6,0.05,0.12,0.7],"c":[0.5103,0.015,0.2995,0.77],"r":0.5186,"img":"img/U2/walk/p053_21_03.jpg","say":"오른쪽이에요. 꼭대기에 시계가 달린 흰 탑이 높이 솟아 있어요."},{"b":[0.05,0.91,0.4,0.08],"c":[0.03,0.888,0.44,0.112],"r":5.2381,"img":"img/U2/walk/p053_21_04.jpg","say":"캡션 두 줄이에요. **리라이언스 빌딩** 1895년 16층, **플랫아이언 빌딩** 1902년 22층."}]}},{"p":54,"title":"마샬 필드 스토어, 오디토리엄 빌딩, 홈 인슈어런스 빌딩","terms":["마샬 필드 스토어","오디토리엄 빌딩","홈 인슈어런스 빌딩","curtain wall","steel","Louis Sullivan"],"pass1":[{"kind":"say","lines":["사진 세 장과 설명 글이 있는 쪽이에요. 한 쪽에 건물 세 채가 들어 있어요.","왼쪽 위는 **마샬 필드 스토어**(1887), 오른쪽 위는 **오디토리엄 빌딩**(1889)이에요.","왼쪽 아래는 **홈 인슈어런스 빌딩**(1885)이에요."]},{"kind":"analogy","head":"옷걸이가 된 뼈대","scene":"옷걸이에 옷을 걸듯 철골에 얇은 벽을 걸어 두는 방식이에요.","map":[["옷걸이","**철골(강철)** 골조"],["걸린 옷","**커튼월(curtain wall)**, 무게를 받지 않는 바깥 벽"],["가벼워진 옷","벽이 얇아지고 창이 넓어짐"]]}],"pass2":[{"kind":"points","head":"세 건물의 기본 사실","items":["**마샬 필드 스토어** 는 헨리 홉슨 리처드슨, 미국 시카고, 1887 이에요.","**오디토리엄 빌딩** 은 아들러 앤드 설리번, 미국 시카고, 1889 예요. **루이스 설리번(Louis Sullivan)** 의 초기 작품이에요.","**오디토리엄 빌딩** 은 오피스, 호텔, 오페라 극장의 복합건물이고 음향설계와 냉방장치를 갖췄어요.","**홈 인슈어런스 빌딩** 은 William Jenney, 1885 이고 1931년에 철거됐어요.","**홈 인슈어런스 빌딩** 은 **철골(강철)** 조와 **커튼월(curtain wall)** 로 만들어진, 높이 제한 없는 대표적 초기 철골조 건물이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**오디토리엄 빌딩**(1889)이 한 건물에 담은 기능은 무엇인가요?","choices":["오피스, 호텔, 오페라 극장","백화점과 호텔","공장과 창고"],"a":0,"why":"음향설계와 냉방장치까지 갖춘 복합건물이에요. 설계는 아들러 앤드 설리번이에요."},{"kind":"check","q":"**홈 인슈어런스 빌딩** 이 중요한 이유는 무엇인가요?","choices":["**철골(강철)** 조와 **커튼월(curtain wall)** 로 만든 대표적 초기 철골조 건물이라서","세계에서 가장 높은 건물이라서","장식이 가장 화려해서"],"a":0,"why":"William Jenney, 1885 이고 1931년에 철거됐어요. 높이 제한이 없어진 것이 핵심이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**마샬 필드 스토어** 는 리처드슨(1887), **오디토리엄 빌딩** 은 아들러 앤드 설리번(1889) 이에요.","**홈 인슈어런스 빌딩** 은 제니(1885) 이고 지금은 없는 건물이에요."]}],"walk":{"head":null,"parts":[{"b":[0.05,0.02,0.36,0.4],"c":[0.032,0,0.396,0.44],"r":1.2,"img":"img/U2/walk/p054_21_01.jpg","say":"왼쪽 위 사진이에요. **마샬 필드 스토어**. 거친 돌에 큰 아치 창이 반복돼요."},{"b":[0.03,0.44,0.46,0.05],"c":[0.007,0.41,0.506,0.11],"r":6.1333,"img":"img/U2/walk/p054_21_02.jpg","say":"캡션이에요. 헨리 홉슨 리처드슨, **마샬 필드 스토어**, 미국 시카고, 1887."},{"b":[0.5,0.02,0.47,0.41],"c":[0.4765,0,0.517,0.451],"r":1.5285,"img":"img/U2/walk/p054_21_03.jpg","say":"오른쪽 위 사진이에요. **오디토리엄 빌딩**. 크고 무거운 덩어리에 아치 창이 나요."},{"b":[0.53,0.45,0.45,0.05],"c":[0.505,0.42,0.495,0.11],"r":6.0,"img":"img/U2/walk/p054_21_04.jpg","say":"캡션이에요. 아들러 앤드 설리번, **오디토리엄 빌딩**, 미국 시카고, 1889."},{"b":[0.05,0.5,0.45,0.49],"c":[0.0275,0.461,0.495,0.539],"r":1.2245,"img":"img/U2/walk/p054_21_05.jpg","say":"왼쪽 아래 그림과 캡션이에요. **홈 인슈어런스 빌딩**, William Jenney, 1885, 1931년 철거됐어요."},{"b":[0.52,0.53,0.46,0.33],"c":[0.494,0.5135,0.506,0.363],"r":1.8586,"img":"img/U2/walk/p054_21_06.jpg","say":"오른쪽 글이에요. 오디토리엄의 복합 기능과 Home Insurance Building 의 철골조 설명이에요."}]}},{"p":55,"title":"존 루트, 모나드녹 빌딩, 시카고, 1893","terms":["모나드녹 빌딩","시카고 학파","steel"],"pass1":[{"kind":"say","lines":["사진 세 장, 평면도 한 장, 항목 세 줄, 인용 한 줄이 있는 쪽이에요.","캡션은 '존 루트, Monadnock building, 미국 시카고, 1893' 이에요.","**모나드녹 빌딩** 은 장식을 뺀 대신 벽을 아주 두껍게 만든 건물이에요."]},{"kind":"analogy","head":"두꺼운 성벽","scene":"높이 올리려고 아래를 두껍게 쌓은 성벽 같은 벽이에요.","map":[["두꺼운 아랫부분","1층 벽두께 1.8m 의 조적조"],["얇아지는 윗부분","위로 갈수록 얇아지는 벽"],["장식 없는 표면","간결하고 비장식적인 형태적 해결"]]}],"pass2":[{"kind":"points","head":"**모나드녹 빌딩**(1893)의 특징","items":["설계자는 존 루트, 미국 시카고, 1893 이에요.","조적조예요. 1층 벽두께가 1.8m 나 돼요. 벽돌을 쌓아 무게를 받는 방식이에요.","중앙 복도 주변에 부분적으로 **철골(강철)** 을 사용했어요.","간결하고 비장식적이며 형태적 해결로 승부한 건물이에요.","존 루트의 말이 아래에 인용돼 있어요. 장식을 다용하는 것은 불필요하며 악덕이라는 내용이에요.","건물은 매스와 비례에 의하여 현대 문명의 힘의 개념을 전달해야 한다고 했어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**모나드녹 빌딩** 의 1층 벽두께는 얼마인가요?","choices":["0.8m","1.8m","2.8m"],"a":1,"why":"조적조라 아래를 아주 두껍게 쌓아야 했어요. 중앙 복도 주변에만 철골을 부분적으로 썼어요."},{"kind":"english","head":"논술 답안: 모나드녹 빌딩","en":"모나드녹 빌딩은 1893년 존 루트가 시카고에 지은 조적조 건물로 1층 벽두께가 1.8m에 이르며 중앙 복도 주변에 부분적으로 철골을 사용하였고, 간결하고 비장식적인 형태적 해결을 보여 준다.","ko":"설계자, 연도, 조적조, 벽두께, 부분 철골, 비장식이 채점 항목이에요.","tip":"장식을 뺀 대신 벽을 두껍게 했다고 한 문장으로 기억해요."}],"walk":{"head":null,"parts":[{"b":[0.02,0.03,0.58,0.54],"c":[0,0.003,0.638,0.594],"r":1.4321,"img":"img/U2/walk/p055_21_01.jpg","say":"왼쪽과 가운데 사진이에요. 벽돌 벽에 장식이 없고 창이 반원으로 불룩 튀어나와요."},{"b":[0.62,0.03,0.35,0.35],"c":[0.6025,0.0125,0.385,0.385],"r":1.3333,"img":"img/U2/walk/p055_21_02.jpg","say":"오른쪽 위 사진이에요. 1층 입구. MONADNOCK 글자만 돌에 새겨져 있어요."},{"b":[0.62,0.39,0.35,0.21],"c":[0.6025,0.374,0.385,0.242],"r":2.1212,"img":"img/U2/walk/p055_21_03.jpg","say":"오른쪽 아래 평면도예요. 중앙 복도 양쪽으로 사무실이 늘어서 있어요."},{"b":[0.03,0.59,0.42,0.06],"c":[0.009,0.565,0.462,0.11],"r":5.6,"img":"img/U2/walk/p055_21_04.jpg","say":"캡션이에요. 존 루트, Monadnock building, 미국 시카고, 1893."},{"b":[0.44,0.64,0.52,0.23],"c":[0.414,0.624,0.572,0.262],"r":2.9109,"img":"img/U2/walk/p055_21_05.jpg","say":"소제목과 항목이에요. 조적조 1층 벽두께 1.8m, 부분적 철골, 비장식적 해결."},{"b":[0.05,0.87,0.92,0.12],"c":[0,0.7955,1,0.2045],"r":6.52,"img":"img/U2/walk/p055_21_06.jpg","say":"아래 인용이에요. 장식을 다용하는 것은 불필요하며 악덕이고, 매스와 비례로 힘을 전달해야 해요."}]}},{"p":56,"title":"다니엘 번햄, 리라이언스 빌딩, 시카고, 1895","terms":["리라이언스 빌딩","시카고 학파","steel","모나드녹 빌딩"],"pass1":[{"kind":"say","lines":["항목 세 줄, 사진 한 장, 평면도 한 장이 있는 쪽이에요.","캡션은 '다니엘 번햄, 리라이언스빌딩, 미국 시카고, 1895 (현재 철거)' 예요.","**리라이언스 빌딩** 은 **시카고 학파** 정신의 상징과 같은 건물이에요."]},{"kind":"analogy","head":"뼈대를 그대로 보여 주기","scene":"옷을 얇게 입어 몸의 뼈대가 그대로 드러나는 모습이에요.","map":[["드러난 뼈대","외관에 그대로 표현한 **철골(강철)** 골조"],["얇은 옷","백색 유약 타일로 덮은 얇은 외벽"],["넓게 뚫린 부분","벽보다 훨씬 넓은 창"]]}],"pass2":[{"kind":"points","head":"**리라이언스 빌딩**(1895)의 특징","items":["설계자는 다니엘 번햄, 미국 시카고, 1895, 16층이고 현재는 철거됐어요.","외관을 강철 골조로 표현했어요. 구조 뼈대가 그대로 겉으로 드러나요.","저층부의 석재와 유리, 그리고 백색의 유약 타일로 이루어진 상부가 대비를 이뤄요.","**시카고 학파** 정신의 상징과 같은 건물이에요.","**모나드녹 빌딩** 이 두꺼운 벽이라면 **리라이언스 빌딩** 은 얇은 벽과 넓은 창이에요."]},{"kind":"compare","head":"두 건물의 방법이 정반대","cols":["**모나드녹 빌딩**(1893)","**리라이언스 빌딩**(1895)"],"rows":[["조적조, 1층 벽두께 1.8m","**철골(강철)** 골조를 외관에 표현"],["벽이 두껍고 창이 작음","벽이 얇고 창이 넓음"],["존 루트","다니엘 번햄"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**리라이언스 빌딩** 의 외관 특징은 무엇인가요?","choices":["외관을 강철 골조로 표현","1층 벽두께 1.8m 의 조적조","깨진 타일 모자이크"],"a":0,"why":"저층부의 석재, 유리와 상부의 백색 유약 타일이 대비를 이뤄요."},{"kind":"english","head":"논술 답안: 리라이언스 빌딩","en":"리라이언스 빌딩은 1895년 다니엘 번햄이 시카고에 지은 16층 건물로 외관을 강철 골조로 표현하고 저층부의 석재와 유리, 백색 유약 타일로 이루어진 상부의 대비를 보여 주는 시카고파 정신의 상징이다.","ko":"설계자, 연도, 층수, 강철 골조 표현, 대비가 채점 항목이에요.","tip":"뼈대를 그대로 보여 준 건물이라고 외워요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.22,0.16,0.05],"c":[0.02,0.19,0.2,0.11],"r":2.4242,"img":"img/U2/walk/p056_22_01.jpg","say":"왼쪽 제목이에요. 리라리언스 빌딩."},{"b":[0.05,0.32,0.33,0.35],"c":[0.0335,0.3025,0.363,0.385],"r":1.2571,"img":"img/U2/walk/p056_22_02.jpg","say":"항목 세 줄이에요. 강철 골조로 표현, 저층과 상부의 대비, 시카고파 정신의 상징."},{"b":[0.38,0.15,0.19,0.71],"c":[0.3231,0.1145,0.3037,0.781],"r":0.5185,"img":"img/U2/walk/p056_22_03.jpg","say":"사진이에요. 창이 벽보다 훨씬 넓고 가로 띠가 층마다 반복돼요."},{"b":[0.7,0.26,0.25,0.49],"c":[0.6875,0.2355,0.275,0.539],"r":0.6803,"img":"img/U2/walk/p056_22_04.jpg","say":"평면도예요. 가운데 계단과 엘리베이터 둘레로 사무실이 배치돼요."},{"b":[0.38,0.9,0.52,0.08],"c":[0.354,0.8822,0.572,0.1156],"r":6.5975,"img":"img/U2/walk/p056_22_05.jpg","say":"캡션이에요. 다니엘 번햄, **리라이언스 빌딩**, 미국 시카고, 1895, 현재 철거."}]}},{"p":57,"title":"루이스 설리번 1단계, 웨인라이트 빌딩, 1891","terms":["Louis Sullivan","웨인라이트 빌딩","시카고 학파","steel"],"pass1":[{"kind":"say","lines":["왼쪽에 항목과 사진, 오른쪽에 인물 소개와 초상이 있는 쪽이에요.","**루이스 설리번(Louis Sullivan)**(1856-1924)은 **시카고 학파** 의 대표 건축가예요.","**웨인라이트 빌딩**(1891)은 그의 1단계 작품이에요."]},{"kind":"analogy","head":"세로줄이 끌어 올리는 눈","scene":"줄무늬 옷을 세로로 입으면 키가 커 보이는 것과 같아요.","map":[["세로 줄무늬","수직의 조적조 붙임벽(pilaster)"],["커 보이는 키","강조된 수직성"],["옷단","우아한 코니스"]]}],"pass2":[{"kind":"points","head":"**루이스 설리번(Louis Sullivan)**, 1856-1924","items":["저서는 '예술적인 고층 사무소 건축' 이에요.","건축에 대한 인본주의적 접근방식을 가졌어요.","기능적 건축과 유기적 건축을 함께 추구했어요."]},{"kind":"points","head":"1단계 **웨인라이트 빌딩**(1891)","items":["미국 세인트루이스, 1891, 11층의 철골구조예요.","**철골(강철)** 에 테라코타 외벽(spandrel)을 붙였어요.","수직의 조적조 붙임벽(pilaster)이 수직성을 강조해요(mullion).","격자 파사드 구성이에요. 세로선과 가로선이 그물처럼 짜여요.","우아한 코니스가 맨 위를 덮고, 프리캐스트 테라코타 장식을 썼어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**웨인라이트 빌딩** 의 도시와 연도, 층수는 무엇인가요?","choices":["미국 세인트루이스, 1891, 11층","미국 버팔로, 1895, 13층","미국 시카고, 1896, 12층"],"a":0,"why":"설리번 1단계 작품이에요. 버팔로 1895는 **개런티 트러스트 빌딩** 이에요."},{"kind":"english","head":"논술 답안: 웨인라이트 빌딩","en":"웨인라이트 빌딩은 1891년 루이스 설리번이 세인트루이스에 지은 11층 철골구조 건물로 철골에 테라코타 외벽을 두르고 수직의 조적조 붙임벽으로 수직성을 강조한 격자 파사드를 구성하였다.","ko":"연도, 도시, 층수, 철골, 수직성, 격자 파사드가 채점 항목이에요.","tip":"1단계는 세로줄로 키 크게 보이기라고 외워요."}],"walk":{"head":null,"parts":[{"b":[0.06,0.06,0.2,0.05],"c":[0.048,0.03,0.224,0.11],"r":2.7152,"img":"img/U2/walk/p057_22_01.jpg","say":"왼쪽 제목이에요. 1단계 웨인라이트빌딩."},{"b":[0.05,0.12,0.6,0.34],"c":[0.02,0.103,0.66,0.374],"r":2.3529,"img":"img/U2/walk/p057_22_02.jpg","say":"항목 여섯 줄이에요. 11층 철골, 테라코타 외벽, 수직성 강조, 격자 파사드, 코니스, 장식."},{"b":[0.51,0.06,0.47,0.05],"c":[0.483,0.03,0.517,0.11],"r":6.2667,"img":"img/U2/walk/p057_22_03.jpg","say":"오른쪽 제목이에요. 루이스 설리번(Louis Sullivan, 1856-1924)."},{"b":[0.72,0.1,0.21,0.45],"c":[0.708,0.0775,0.234,0.495],"r":0.6303,"img":"img/U2/walk/p057_22_04.jpg","say":"설리번의 초상 사진이에요."},{"b":[0.61,0.63,0.38,0.18],"c":[0.582,0.614,0.418,0.212],"r":2.6289,"img":"img/U2/walk/p057_22_05.jpg","say":"오른쪽 항목이에요. 저서, 인본주의적 접근, 기능적 건축과 유기적 건축."},{"b":[0.08,0.47,0.49,0.51],"c":[0.0555,0.439,0.539,0.561],"r":1.281,"img":"img/U2/walk/p057_22_06.jpg","say":"왼쪽 아래 사진이에요. 세로줄이 끝없이 이어지고 그 사이에 잎 무늬 장식이 있어요."}]}},{"p":58,"title":"루이스 설리번 2단계, 개런티 트러스트 빌딩, 1895","terms":["Louis Sullivan","개런티 트러스트 빌딩","3단구성법","웨인라이트 빌딩"],"pass1":[{"kind":"say","lines":["왼쪽에 사진, 오른쪽에 평면 두 장과 항목이 있는 쪽이에요.","캡션은 '루이스 설리번, 개런티 트러스트 빌딩, 미국 버팔로, 1895' 예요.","여기서 **3단구성법** 이 나와요. base, shaft, attic 세 덩어리예요."]},{"kind":"analogy","head":"기둥처럼 읽는 건물","scene":"그리스 기둥의 주춧돌, 몸통, 머리를 건물 전체로 키운 모습이에요.","map":[["주춧돌","중후한 저층부(base)"],["기둥 몸통","수직성의 높은 중간층(shaft)"],["기둥 머리","기계설비가 들어가는 지붕층(attic)"]]}],"pass2":[{"kind":"points","head":"2단계 **개런티 트러스트 빌딩**(1895)","items":["**루이스 설리번(Louis Sullivan)**, 미국 버팔로, 1895 예요.","형태적으로 연속적인 상층부와 대비적인 저층의 두 개 층 구성이에요.","1단계 **웨인라이트 빌딩** 보다 기술적, 미적 완성도가 높아요.","중근동과 이슬람의 장식에 영감을 받아 전 표면에 적용했어요.","**3단구성법** 은 중후한 저층부(base), 수직성의 높은 중간층(shaft), 기계설비가 들어가는 지붕층(attic)이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**3단구성법** 의 세 부분을 바르게 짝지은 것은 무엇인가요?","choices":["base, shaft, attic","base, body, cornice","base, wall, roof"],"a":0,"why":"중후한 저층부(base), 수직성의 높은 중간층(shaft), 기계설비가 들어가는 지붕층(attic)이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**3단구성법** 은 설리번의 base, shaft, attic 이에요.","**시카고 학파** 일반론의 3부분 분할은 베이스, 바디, 코니스예요. 이름이 다르니 섞지 않아요."]}],"walk":{"head":null,"parts":[{"b":[0.04,0.06,0.41,0.83],"c":[0.0195,0.0185,0.451,0.913],"r":0.6586,"img":"img/U2/walk/p058_21_01.jpg","say":"왼쪽 사진이에요. 저층 두 개 층 위로 가는 기둥이 끝까지 이어져 올라가요."},{"b":[0.04,0.9,0.42,0.07],"c":[0.019,0.88,0.462,0.11],"r":5.6,"img":"img/U2/walk/p058_21_02.jpg","say":"캡션이에요. **루이스 설리번(Louis Sullivan)**, **개런티 트러스트 빌딩**, 미국 버팔로, 1895."},{"b":[0.46,0.08,0.46,0.37],"c":[0.437,0.0615,0.506,0.407],"r":1.6577,"img":"img/U2/walk/p058_21_03.jpg","say":"평면도 두 장이에요. 왼쪽이 기준층, 오른쪽이 1층 평면이에요."},{"b":[0.46,0.49,0.25,0.05],"c":[0.4475,0.46,0.275,0.11],"r":3.3333,"img":"img/U2/walk/p058_21_04.jpg","say":"소제목이에요. 2단계 개런티 트러스트 빌딩."},{"b":[0.46,0.55,0.51,0.25],"c":[0.4345,0.534,0.561,0.282],"r":2.6525,"img":"img/U2/walk/p058_21_05.jpg","say":"항목이에요. 연속적인 상층부, 대비적인 저층 두 개 층, 이슬람 장식의 전면 적용."},{"b":[0.46,0.82,0.51,0.16],"c":[0.4345,0.804,0.561,0.192],"r":3.8958,"img":"img/U2/walk/p058_21_06.jpg","say":"마지막 항목이에요. **3단구성법**, base, shaft, attic 이에요."}]}},{"p":59,"title":"개런티 트러스트 빌딩의 형태와 설리번의 말","terms":["개런티 트러스트 빌딩","Louis Sullivan","3단구성법"],"pass1":[{"kind":"say","lines":["글만 있는 쪽이에요. 항목 일곱 줄과 아래에 인용 한 줄이 있어요.","**개런티 트러스트 빌딩** 의 형태를 더 깊이 설명하는 쪽이에요.","핵심 한 줄은 '애틱 하부까지 아치를 밀어올려 수직성을 강조' 예요."]},{"kind":"analogy","head":"천장까지 끌어올린 아치","scene":"낮게 걸려 있던 아치를 천장 가까이까지 밀어 올린 모습이에요.","map":[["낮은 아치","보통 건물의 창 위 아치"],["밀어 올린 아치","애틱 하부까지 올라간 아치"],["길어 보이는 기둥","강조된 수직성"]]}],"pass2":[{"kind":"points","head":"**개런티 트러스트 빌딩** 의 형태","items":["르네상스 궁전형태로까지 그 원초적 형태를 찾을 수 있어요.","안전에 대한 인간의 뿌리 깊은 욕구를 미국적인 확신으로 구현했어요.","애틱 하부까지 아치를 밀어올려 수직성을 강조하고 스팬드럴(spandrel)은 후퇴시켰어요.","부재의 3차원적 분절이에요. 기둥과 띠가 앞뒤로 다른 깊이에 놓여요.","모서리 기둥이 건물 전체의 볼륨을 한정하고 상부의 코니스까지 연장돼요.","모서리 기둥과 그 사이에 채워진 기둥들이 대비를 이루고, 인간을 추상화한 유기적 형태를 이뤄요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**개런티 트러스트 빌딩** 에서 수직성을 강조한 방법은 무엇인가요?","choices":["애틱 하부까지 아치를 밀어올림","수평 띠를 굵게 둘러침","지붕을 낮게 누름"],"a":0,"why":"동시에 스팬드럴(spandrel)은 뒤로 물러나게 해서 세로선이 더 살아나요."},{"kind":"english","head":"논술 답안: 개런티 트러스트 빌딩","en":"개런티 트러스트 빌딩은 1895년 설리번이 버팔로에 지은 건물로 애틱 하부까지 아치를 밀어올려 수직성을 강조하고 스팬드럴을 후퇴시켰으며, base와 shaft, attic의 3단구성법을 보여 준다.","ko":"연도, 도시, 수직성 강조 방법, 3단구성법이 채점 항목이에요.","tip":"아치를 위로 밀어 올렸다는 한마디를 꼭 넣어요."}],"walk":{"head":null,"parts":[{"b":[0.09,0.08,0.2,0.05],"c":[0.078,0.05,0.224,0.11],"r":2.7152,"img":"img/U2/walk/p059_21_01.jpg","say":"제목이에요. 개런티 트러스트 빌딩."},{"b":[0.09,0.19,0.8,0.12],"c":[0.05,0.1611,0.88,0.1778],"r":6.5992,"img":"img/U2/walk/p059_21_02.jpg","say":"앞 두 줄이에요. 르네상스 궁전형태, 안전에 대한 욕구를 미국적 확신으로 구현."},{"b":[0.09,0.31,0.83,0.1],"c":[0.0485,0.2678,0.913,0.1845],"r":6.598,"img":"img/U2/walk/p059_21_03.jpg","say":"셋째 줄이에요. 애틱 하부까지 아치를 밀어올려 수직성 강조, 스팬드럴은 후퇴."},{"b":[0.09,0.42,0.75,0.18],"c":[0.0525,0.404,0.825,0.212],"r":5.1887,"img":"img/U2/walk/p059_21_04.jpg","say":"나머지 줄이에요. 3차원적 분절, 모서리 기둥, 인간을 추상화한 유기적 형태."},{"b":[0.09,0.68,0.7,0.06],"c":[0.055,0.6322,0.77,0.1556],"r":6.5981,"img":"img/U2/walk/p059_21_05.jpg","say":"아래 인용이에요. 강하고 단순한 근육적 형태에 시적 상상력이라는 옷을 입혀야 한다."}]}},{"p":60,"title":"루이스 설리번 3단계, 카슨 피리 스콧 백화점, 1896","terms":["Louis Sullivan","Carson Pirie Scott","cast iron","개런티 트러스트 빌딩","Art Nouveau"],"pass1":[{"kind":"say","lines":["항목 두 묶음과 사진 한 장이 있는 쪽이에요.","캡션은 '루이스 설리번, Carson Pirie Scott 백화점, 미국 시카고, 1896' 이에요.","3단계에서는 장식이 다소 줄어들어요."]},{"kind":"recap","items":["1단계 **웨인라이트 빌딩**(1891)은 세로줄로 수직성을 강조했어요.","2단계 **개런티 트러스트 빌딩**(1895)은 전 표면에 이슬람풍 장식을 깔았어요.","3단계 **카슨 피리 스콧 백화점(Carson Pirie Scott)**(1896)은 장식이 줄어들어요."]}],"pass2":[{"kind":"points","head":"3단계 **카슨 피리 스콧 백화점(Carson Pirie Scott)**(1896)","items":["미국 시카고, 1896 이에요. 테라코타로 덮인 골조예요.","가로 레벨에서 연속적으로 장식된 2층 높이의 **주철(cast iron)** 파사드 구성이에요.","코너의 원주형 기둥은 모서리의 장소성을 강조하고 공공성의 이미지를 확보해요.","상부에는 소용돌이 문양의 장식 릴리프를 배치했어요.","장식이 다소 줄어드는 단계예요."]},{"kind":"points","head":"설리번이 장식을 대하는 태도","items":["장식으로부터 건물의 신비적인 힘이 나타나는 것으로 이해했어요.","장식은 건물의 기능적, 유기적 표현이에요.","예를 들어 **개런티 트러스트 빌딩** 의 코니스 장식은 설비 배관과 엘리베이터의 톱니바퀴를 암시해요.","그래서 설리번은 장식을 없애자는 쪽이 아니에요. 장식이 기능을 말해야 한다는 쪽이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**카슨 피리 스콧 백화점(Carson Pirie Scott)** 의 저층부 파사드는 무엇으로 이루어졌나요?","choices":["2층 높이의 **주철(cast iron)** 파사드","1층 높이의 유리 커튼월","3층 높이의 석재 아케이드"],"a":0,"why":"가로 레벨에서 연속적으로 장식된 2층 높이의 주철 파사드예요."},{"kind":"check","q":"설리번이 장식을 대하는 태도로 맞는 것은 무엇인가요?","choices":["장식은 죄악이므로 없애야 한다","장식이 건물의 기능적, 유기적 표현이다","장식은 옛 양식을 그대로 옮기는 것이다"],"a":1,"why":"장식은 죄악이라는 말은 3강의 **아르 누보(Art Nouveau)** 이후 로스의 주장이에요. 설리번과 헷갈리지 않아요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.06,0.33,0.05],"c":[0.0335,0.03,0.363,0.11],"r":4.4,"img":"img/U2/walk/p060_22_01.jpg","say":"제목이에요. 3단계 Carson Pirie Scott 백화점."},{"b":[0.05,0.12,0.5,0.16],"c":[0.025,0.104,0.55,0.192],"r":3.8194,"img":"img/U2/walk/p060_22_02.jpg","say":"앞 항목이에요. 테라코타로 덮인 골조, 2층 높이의 주철 파사드 구성."},{"b":[0.05,0.29,0.5,0.23],"c":[0.025,0.274,0.55,0.262],"r":2.799,"img":"img/U2/walk/p060_22_03.jpg","say":"뒤 항목이에요. 코너의 원주형 기둥, 소용돌이 릴리프, 장식이 줄어드는 단계."},{"b":[0.05,0.58,0.3,0.05],"c":[0.035,0.55,0.33,0.11],"r":4.0,"img":"img/U2/walk/p060_22_04.jpg","say":"소제목이에요. 설리번이 장식을 대하는 태도."},{"b":[0.05,0.64,0.5,0.26],"c":[0.025,0.624,0.55,0.292],"r":2.5114,"img":"img/U2/walk/p060_22_05.jpg","say":"아래 항목이에요. 장식에서 신비적인 힘, 기능적 유기적 표현이에요."},{"b":[0.6,0.17,0.38,0.81],"c":[0.581,0.109,0.418,0.891],"r":0.6255,"img":"img/U2/walk/p060_22_06.jpg","say":"오른쪽 사진과 캡션이에요. **루이스 설리번(Louis Sullivan)**, Carson Pirie Scott 백화점, 미국 시카고, 1896."}]}},{"p":61,"title":"카슨 피리 스콧 백화점의 주철 장식과 시카고 창","terms":["Carson Pirie Scott","Louis Sullivan","cast iron","시카고 창","Art Nouveau"],"pass1":[{"kind":"say","lines":["사진 네 장이 있는 쪽이에요. 전경, 시카고 창, 모서리 입구, 장식 가까이예요.","글은 '루이스 설리번의 아르누보풍 주철 장식모티프' 와 '시카고 창' 이에요.","**루이스 설리번(Louis Sullivan)** 의 장식이 **아르 누보(Art Nouveau)** 풍이라는 점이 여기 나와요."]},{"kind":"analogy","head":"검은 덩굴이 감은 입구","scene":"쇠로 만든 덩굴이 문 둘레를 휘감은 모습이에요.","map":[["쇠 덩굴","**주철(cast iron)** 로 뜬 곡선 장식"],["감긴 자리","모서리의 둥근 기둥과 입구 둘레"],["위층의 맨 얼굴","장식 없는 흰 격자 창"]]}],"pass2":[{"kind":"points","head":"이 사진들에서 볼 것","items":["왼쪽 위는 **카슨 피리 스콧 백화점(Carson Pirie Scott)** 전경이에요. 위층은 흰 격자 창이 반듯하게 이어져요.","왼쪽 아래는 **시카고 창** 을 가까이 찍은 것이에요. 가운데 큰 고정 창과 양옆 좁은 창으로 나뉘어요.","**시카고 창** 은 3개로 나뉘고 격자이며 돌출된 창이에요.","오른쪽 위는 모서리 입구예요. 둥근 기둥 둘레를 검은 장식이 감고 있어요.","오른쪽 아래는 그 장식을 가까이서 본 것이에요. 덩굴 같은 곡선이 빽빽하게 얽혀 있어요.","이것이 **루이스 설리번(Louis Sullivan)** 의 **아르 누보(Art Nouveau)** 풍 **주철(cast iron)** 장식모티프예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**시카고 창** 의 특징으로 맞는 것은 무엇인가요?","choices":["3개로 나뉘고 격자이며 돌출된 창","원형으로 뚫린 창","바닥부터 천장까지 통유리"],"a":0,"why":"가운데 큰 고정 창과 양옆의 좁은 창으로 나뉘어요."},{"kind":"english","head":"논술 답안: 카슨 피리 스콧 백화점","en":"카슨 피리 스콧 백화점은 1896년 설리번의 3단계 작품으로 테라코타로 덮인 골조에 2층 높이의 주철 파사드를 두르고 코너의 원주형 기둥으로 모서리의 장소성을 강조하였으며 장식이 다소 줄어든다.","ko":"연도, 3단계, 주철 파사드, 코너 기둥, 장식 감소가 채점 항목이에요.","tip":"아래는 덩굴 장식, 위는 맨 얼굴 격자 창으로 그림처럼 외워요."}],"walk":{"head":null,"parts":[{"b":[0.06,0.03,0.39,0.59],"c":[0.0405,0.0005,0.429,0.649],"r":0.8814,"img":"img/U2/walk/p061_21_01.jpg","say":"왼쪽 위 사진이에요. 백화점 전경. 위층의 흰 격자 창이 끝없이 반복돼요."},{"b":[0.06,0.64,0.4,0.05],"c":[0.04,0.61,0.44,0.11],"r":5.3333,"img":"img/U2/walk/p061_21_02.jpg","say":"캡션이에요. **루이스 설리번(Louis Sullivan)**, Carson Pirie Scott 백화점, 1896."},{"b":[0.06,0.69,0.39,0.3],"c":[0.0405,0.668,0.429,0.332],"r":1.7229,"img":"img/U2/walk/p061_21_03.jpg","say":"왼쪽 아래 사진이에요. **시카고 창**. 가운데 큰 판과 양옆 좁은 창이 보여요."},{"b":[0.55,0.04,0.4,0.35],"c":[0.53,0.0225,0.44,0.385],"r":1.5238,"img":"img/U2/walk/p061_21_04.jpg","say":"오른쪽 위 사진이에요. 모서리 입구. 둥근 기둥 둘레를 검은 장식이 감아요."},{"b":[0.56,0.4,0.39,0.45],"c":[0.5405,0.3775,0.429,0.495],"r":1.1556,"img":"img/U2/walk/p061_21_05.jpg","say":"오른쪽 아래 사진이에요. 주철 장식을 가까이서. 덩굴 같은 곡선이 빽빽해요."},{"b":[0.71,0.88,0.27,0.08],"c":[0.6965,0.864,0.297,0.112],"r":3.5357,"img":"img/U2/walk/p061_21_06.jpg","say":"글이에요. 루이스 설리번의 아르누보풍 주철 장식모티프."}]}},{"p":62,"title":"시카고 트리뷴 신문사 사옥 설계 국제공모전","terms":["트리뷴 타워","Adolf Loos","시카고 학파"],"pass1":[{"kind":"say","lines":["제목 한 줄과 그림 세 장이 있는 쪽이에요.","왼쪽은 **아돌프 로스(Adolf Loos)** 의 1922년 제출안이에요.","가운데와 오른쪽이 당선작인 **트리뷴 타워** 예요."]},{"kind":"analogy","head":"기둥 하나가 건물","scene":"그리스 신전의 기둥 하나를 크게 키워 그대로 건물로 만든 것이에요.","map":[["그리스 기둥","거대한 도리아식 기둥"],["기둥을 받치는 단","아래의 낮은 사무소 덩어리"],["만든 사람","**아돌프 로스(Adolf Loos)**, 1922년 제출안"]]}],"pass2":[{"kind":"points","head":"공모전의 기본 사실","items":["시카고 트리뷴 신문사 사옥 설계 국제공모전이에요.","**아돌프 로스(Adolf Loos)** 의 제출안(1922)은 거대한 도리아식 기둥 형태였어요.","당선작은 레이먼드 후드와 존 미들 하우얼스의 안이에요.","**트리뷴 타워** 로 1925년에 완공됐어요. 미국 시카고예요.","당선작 꼭대기는 고딕 성당처럼 여러 갈래로 갈라져 있어요.","**아돌프 로스(Adolf Loos)** 는 3강에서 '장식은 죄악' 아저씨로 다시 만나요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"시카고 트리뷴 사옥 공모전의 당선작과 완공 연도는 무엇인가요?","choices":["**아돌프 로스(Adolf Loos)** 안, 1922","후드와 하우얼스 안, 1925","번햄 안, 1895"],"a":1,"why":"**트리뷴 타워** 로 1925년에 완공됐어요. 로스의 1922년 안은 거대한 도리아식 기둥이었어요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["1922는 **아돌프 로스(Adolf Loos)** 의 제출안, 1925는 **트리뷴 타워** 완공이에요.","로스가 당선된 것이 아니에요. 제출만 했어요."]}],"walk":{"head":null,"parts":[{"b":[0.25,0.03,0.5,0.05],"c":[0.225,0,0.55,0.1111],"r":6.6007,"img":"img/U2/walk/p062_21_01.jpg","say":"제목이에요. 시카고 트리뷴 신문사 사옥 설계 국제공모전."},{"b":[0.03,0.08,0.25,0.77],"c":[0,0.0415,0.3294,0.847],"r":0.5185,"img":"img/U2/walk/p062_21_02.jpg","say":"왼쪽 그림이에요. 거대한 도리아식 기둥 하나가 그대로 건물이 돼요."},{"b":[0.31,0.08,0.28,0.77],"c":[0.2853,0.0415,0.3294,0.847],"r":0.5185,"img":"img/U2/walk/p062_21_03.jpg","say":"가운데 그림이에요. 당선작. 꼭대기가 고딕 성당처럼 갈라져 있어요."},{"b":[0.62,0.17,0.35,0.64],"c":[0.6025,0.138,0.385,0.704],"r":0.7292,"img":"img/U2/walk/p062_21_04.jpg","say":"오른쪽 사진과 글이에요. **트리뷴 타워**(Tribune Tower)의 현재 모습이에요."},{"b":[0.04,0.88,0.26,0.11],"c":[0.027,0.858,0.286,0.142],"r":2.6854,"img":"img/U2/walk/p062_21_05.jpg","say":"왼쪽 캡션이에요. **아돌프 로스(Adolf Loos)**, 제출안, 1922."},{"b":[0.32,0.88,0.25,0.11],"c":[0.3075,0.858,0.275,0.142],"r":2.5822,"img":"img/U2/walk/p062_21_06.jpg","say":"가운데 캡션이에요. 레이먼드 후드 & 존 미들 하우얼스, 미국 시카고, 1925."}]}},{"p":63,"title":"아르데코 마천루 다섯 채","terms":["아르데코","록펠러 센터","엠파이어 스테이트 빌딩","크라이슬러 빌딩","리글리 빌딩","시카고 템플 빌딩"],"pass1":[{"kind":"say","lines":["사진 한 장과 캡션 다섯 줄이 있는 쪽이에요.","**록펠러 센터**, **엠파이어 스테이트 빌딩**, **크라이슬러 빌딩**, **리글리 빌딩**, **시카고 템플 빌딩** 이에요.","**아르데코** 시기의 마천루를 한 쪽에 모아 놓은 정리 쪽이에요."]},{"kind":"recap","items":["**아르데코** 는 마천루 형태를 빌려 왔어요.","그래서 이 시기 미국 마천루가 곧 **아르데코** 의 얼굴이에요.","도시와 연도만 외워도 객관식은 풀려요."]}],"pass2":[{"kind":"compare","head":"한 표로 정리하기","cols":["건물","설계자","도시와 연도"],"rows":[["**록펠러 센터**","레이먼드 후드","미국 뉴욕, 1939"],["**엠파이어 스테이트 빌딩**","슈리브, 램 & 하먼","미국 뉴욕, 1931"],["**크라이슬러 빌딩**","윌리엄 밴 앨런","미국 뉴욕, 1930"],["**리글리 빌딩**","그레이엄, 앤더슨 & 프로브스트 앤드 화이트","미국 시카고, 1924"],["**시카고 템플 빌딩**","올러버드 앤드 로시","미국 시카고, 1924"]]},{"kind":"points","head":"사진에서 볼 것","items":["사진은 시카고의 마천루 무리를 아래에서 올려다본 것이에요.","가운데 건물은 꼭대기에 작은 돔이 얹혀 있어요.","그 오른쪽 뒤로 흰 탑이 뾰족하게 솟아 있어요.","왼쪽 건물들은 꼭대기가 계단처럼 한 단씩 물러나며 올라가요.","계단식으로 물러나는 이 모양이 **아르데코** 마천루의 공통된 실루엣이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**엠파이어 스테이트 빌딩** 의 도시와 연도는 무엇인가요?","choices":["미국 뉴욕, 1931","미국 시카고, 1924","미국 뉴욕, 1939"],"a":0,"why":"1939년 뉴욕은 **록펠러 센터**, 1924년 시카고는 **리글리 빌딩** 과 **시카고 템플 빌딩** 이에요."},{"kind":"check","q":"1924년 미국 시카고에 지어진 건물끼리 묶인 것은 무엇인가요?","choices":["**리글리 빌딩** 과 **시카고 템플 빌딩**","**크라이슬러 빌딩** 과 **록펠러 센터**","**엠파이어 스테이트 빌딩** 과 **크라이슬러 빌딩**"],"a":0,"why":"나머지는 모두 뉴욕이에요. 도시로 먼저 갈라 두면 외우기 쉬워요."}],"walk":{"head":null,"parts":[{"b":[0.02,0.07,0.68,0.62],"c":[0,0.039,0.748,0.682],"r":1.4624,"img":"img/U2/walk/p063_22_01.jpg","say":"사진이에요. 시카고 하늘을 배경으로 마천루가 줄지어 서 있어요."},{"b":[0.34,0.75,0.61,0.06],"c":[0.3095,0.7122,0.671,0.1356],"r":6.5978,"img":"img/U2/walk/p063_22_02.jpg","say":"첫 캡션이에요. 레이먼드 후드, **록펠러 센터**, 미국 뉴욕, 1939."},{"b":[0.34,0.81,0.61,0.06],"c":[0.3095,0.7722,0.671,0.1356],"r":6.5978,"img":"img/U2/walk/p063_22_03.jpg","say":"둘째 캡션이에요. 슈리브, 램 & 하먼, **엠파이어 스테이트 빌딩**, 미국 뉴욕, 1931."},{"b":[0.34,0.86,0.61,0.05],"c":[0.3095,0.8172,0.671,0.1356],"r":6.5978,"img":"img/U2/walk/p063_22_04.jpg","say":"셋째 캡션이에요. 윌리엄 밴 앨런, **크라이슬러 빌딩**, 미국 뉴욕, 1930."},{"b":[0.34,0.91,0.64,0.05],"c":[0.296,0.8578,0.704,0.1422],"r":6.601,"img":"img/U2/walk/p063_22_05.jpg","say":"넷째 캡션이에요. **리글리 빌딩**, 미국 시카고, 1924."},{"b":[0.34,0.95,0.53,0.045],"c":[0.3135,0.8822,0.583,0.1178],"r":6.5988,"img":"img/U2/walk/p063_22_06.jpg","say":"다섯째 캡션이에요. 올러버드 앤드 로시, **시카고 템플 빌딩**, 미국 시카고, 1924."}]}},{"p":64,"title":"시카고 학파 고층건물의 특징 정리","terms":["시카고 학파","시카고 창","시카고 빌딩","3단구성법","steel"],"pass1":[{"kind":"say","lines":["항목 세 줄과 사진 두 장, 그리고 글상자 라벨이 있는 쪽이에요.","**시카고 학파** 고층건물의 특징을 한 쪽으로 정리한 마지막 쪽이에요.","핵심 세 가지는 철골에 테라코타 외벽, 3부분 분할, **시카고 창** 이에요."]},{"kind":"analogy","head":"건물을 기둥으로 읽기","scene":"고전 기둥 하나를 크게 키워 건물 전체로 읽는 방법이에요.","map":[["주춧돌","베이스"],["기둥 몸통","바디, 약간의 장식"],["기둥 머리","주두에 해당하는 코니스"]]}],"pass2":[{"kind":"points","head":"**시카고 학파** 고층건물의 특징","items":["**철골(강철)** 에 테라코타 외벽을 붙여요.","3부분으로 분할된 건물이에요. 베이스, 약간의 장식을 둔 바디, 주두에 해당하는 코니스예요.","그래서 건물 전체가 기둥 같은 구조로 읽혀요.","**시카고 창** 은 3개로 나뉘고 격자이며 돌출된 창이에요.","사진의 **시카고 빌딩**(1905)이 이 특징을 한눈에 보여 주는 사례예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**시카고 학파** 고층건물의 3부분 분할을 바르게 부른 것은 무엇인가요?","choices":["베이스, 바디, 코니스","base, shaft, attic","저층, 중층, 옥탑"],"a":0,"why":"base, shaft, attic 은 설리번의 **3단구성법** 이에요. 이름이 다르니 함께 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**시카고 학파** 일반론은 베이스, 바디, 코니스, 설리번의 **3단구성법** 은 base, shaft, attic 이에요.","**시카고 창** 은 창 이야기, 3부분 분할은 건물 전체 이야기예요. 섞지 않아요."]},{"kind":"english","head":"논술 답안: 시카고 학파","en":"시카고 학파는 1871년 시카고 대화재 이후 철골에 테라코타 외벽을 두른 고층 사무소 건축을 전개하였으며, 건물을 베이스와 바디, 코니스의 3부분으로 분할하여 기둥처럼 읽히게 하고 3개로 나뉜 격자의 돌출된 시카고 창을 사용하였다.","ko":"화재, 철골과 테라코타, 3부분 분할, 시카고 창이 채점 항목이에요.","tip":"건물을 기둥 하나로 보는 그림과 창 세 칸 그림 두 개만 기억해요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.04,0.35,0.22],"c":[0.0325,0.024,0.385,0.252],"r":2.037,"img":"img/U2/walk/p064_21_01.jpg","say":"위 항목 세 줄이에요. 철골에 테라코타 외벽, 3부분으로 분할, 시카고 창."},{"b":[0.19,0.3,0.27,0.62],"c":[0.1765,0.269,0.297,0.682],"r":0.5806,"img":"img/U2/walk/p064_21_02.jpg","say":"왼쪽 사진이에요. **시카고 빌딩**, 1905. 모서리가 각진 벽돌 고층건물이에요."},{"b":[0.2,0.92,0.26,0.05],"c":[0.187,0.89,0.286,0.11],"r":3.4667,"img":"img/U2/walk/p064_21_03.jpg","say":"캡션이에요. Chicago Building, 1905."},{"b":[0.53,0.45,0.15,0.11],"c":[0.505,0.434,0.2,0.142],"r":1.8779,"img":"img/U2/walk/p064_21_04.jpg","say":"오른쪽 위 라벨이에요. 주두에 해당하는 코니스, 기둥 같은 구조."},{"b":[0.53,0.58,0.13,0.1],"c":[0.495,0.564,0.2,0.132],"r":2.0202,"img":"img/U2/walk/p064_21_05.jpg","say":"가운데 라벨이에요. 바디, 약간의 장식."},{"b":[0.52,0.82,0.3,0.14],"c":[0.505,0.804,0.33,0.172],"r":2.5581,"img":"img/U2/walk/p064_21_06.jpg","say":"아래 라벨이에요. 베이스, 그리고 시카고 창은 3개로 나뉨, 격자, 돌출."}]}}]};
